(window.TNQ=window.TNQ||[]).push({"terms":{"성문법원":{"d":"문서 형식으로 제정되어 공포된 법으로 헌법과 법률과 명령과 조례 등이 해당합니다.","r":["불문법"]},"불문법":{"d":"문서로 제정되지 않았으나 법의 효력을 가지는 관습법과 판례법과 조리를 말합니다.","r":["성문법원"]},"대통령령":{"d":"대통령이 법률의 위임이나 집행을 위해 내는 명령으로 시행령이 이에 해당합니다.","r":["총리령"]},"총리령":{"d":"국무총리가 소관 사무에 관하여 법률이나 대통령령의 위임으로 내는 명령입니다.","r":["대통령령"]},"조례":{"d":"지방의회가 법령의 범위 안에서 지방자치단체의 사무에 관해 의결해 제정하는 자치법규입니다.","r":[]},"프로그램규정설":{"d":"사회적 기본권을 국가가 입법으로 추진할 방침만 정한 규정으로 보고 개인의 직접 청구권은 부정하는 학설입니다.","r":["추상적 권리설","구체적 권리설"]},"추상적 권리설":{"d":"사회적 기본권이 권리이기는 하지만 법률이 있어야 비로소 구체화된다고 보는 학설입니다.","r":["프로그램규정설","구체적 권리설"]},"구체적 권리설":{"d":"헌법 규정만으로도 개인이 국가에 직접 청구할 수 있는 구체적 권리라고 보는 학설입니다.","r":["프로그램규정설","추상적 권리설"]},"사회적 기본권":{"d":"국가에 적극적인 급부와 배려를 요구할 수 있는 권리로 자유권과 대비됩니다.","r":[]},"구상권":{"d":"제3자의 잘못으로 급여를 한 쪽이 그 비용 범위에서 제3자에게 배상을 청구할 수 있는 권리입니다.","r":[]},"사회보장위원회":{"d":"사회보장 주요 시책을 심의하고 조정하려고 국무총리 소속으로 두는 위원회입니다.","r":[]},"보장기관":{"d":"관계 법령에 따라 사회보장급여를 제공하는 국가기관과 지방자치단체입니다.","r":["지원대상자"]},"지원대상자":{"d":"사회보장급여를 필요로 하는 사람으로 신청 전이라도 발굴 대상이 됩니다.","r":["보장기관"]},"사회복지전담공무원":{"d":"사회복지사 자격을 가지고 급여 상담과 조사 같은 복지 업무를 전담하는 공무원입니다.","r":[]},"사회복지법인":{"d":"사회복지사업을 할 목적으로 설립된 법인으로 시·도지사의 허가를 받아야 합니다.","r":["정관","기본재산"]},"정관":{"d":"법인의 목적과 조직과 운영에 관한 기본 규칙을 적은 문서입니다.","r":["사회복지법인"]},"기본재산":{"d":"법인이 사업을 위해 반드시 유지해야 하는 재산으로 처분 등에 관청의 허가가 필요한 재산입니다.","r":["사회복지법인"]},"최저보장수준":{"d":"소득과 지출과 물가 등을 고려해 급여 종류별로 공표하는 보장 금액이나 수준입니다.","r":["기준 중위소득"]},"기준 중위소득":{"d":"국민 가구소득을 크기순으로 세웠을 때 한가운데에 해당하는 값으로 급여 기준의 바탕이 됩니다.","r":["소득인정액"]},"소득인정액":{"d":"개별가구의 소득평가액에 재산의 소득환산액을 더한 금액으로 수급 여부를 가르는 기준입니다.","r":["기준 중위소득"]},"차상위계층":{"d":"수급권자는 아니지만 소득인정액이 일정 기준 이하여서 지원이 필요한 계층입니다.","r":["소득인정액"]},"부양의무자":{"d":"수급권자를 부양할 법적 의무가 있는 가족으로 보통 직계혈족과 그 배우자입니다.","r":[]},"자활기업":{"d":"수급자와 차상위자가 서로 협력해 설립하고 보장기관의 인정을 받는 자활 사업체입니다.","r":["지역자활센터"]},"지역자활센터":{"d":"수급자와 차상위자의 자활을 돕는 사업을 하려고 보장기관이 지정하는 비영리 기관입니다.","r":["자활기업"]},"대지급":{"d":"급여비용 일부를 기금에서 부담할 때 나머지를 기금이 먼저 내주고 나중에 갚게 하는 제도입니다.","r":[]},"기준연금액":{"d":"기초연금 계산의 바탕이 되는 금액으로 장관이 물가변동률을 반영해 매년 고시합니다.","r":["부가연금액"]},"부가연금액":{"d":"국민연금의 기본연금액에 더해지는 금액으로 부양가족이나 가입기간 사정에 따라 붙습니다.","r":["기준연금액"]},"반환일시금":{"d":"가입기간이 짧아 연금을 받지 못하는 경우 낸 보험료를 한꺼번에 돌려주는 급여입니다.","r":[]},"분할연금":{"d":"혼인 기간이 일정 기간 이상인 사람이 이혼했을 때 전 배우자의 노령연금 일부를 나누어 받는 연금입니다.","r":[]},"조기노령연금":{"d":"가입기간 요건을 채운 사람이 소득 업무에 종사하지 않을 때 60세 전에 앞당겨 받는 연금입니다.","r":[]},"임의계속가입자":{"d":"60세가 되었지만 신청해서 가입기간을 늘리려고 국민연금에 계속 가입하는 사람입니다.","r":[]},"요양급여":{"d":"건강보험에서 진찰과 약제와 처치와 입원 등으로 질병과 부상을 치료해 주는 현물급여입니다.","r":["선별급여"]},"선별급여":{"d":"효과나 경제성이 불확실해 예비적으로 지정하고 주기적으로 적합성을 평가하는 요양급여입니다.","r":["요양급여"]},"피부양자":{"d":"직장가입자에게 주로 생계를 의존하는 가족으로 소득과 재산이 기준 이하인 사람입니다.","r":[]},"구직급여":{"d":"실업 중인 수급자격자에게 구직 활동 기간 동안 지급하는 고용보험의 기본 급여입니다.","r":["소정급여일수","피보험 단위기간"]},"소정급여일수":{"d":"구직급여를 받을 수 있는 최대 일수로 피보험기간과 연령에 따라 정해집니다.","r":["구직급여"]},"피보험 단위기간":{"d":"보수 지급의 기초가 된 날을 합쳐 셈한 기간으로 구직급여 수급 요건에 쓰입니다.","r":["구직급여"]},"취업촉진 수당":{"d":"재취업을 돕기 위한 조기재취업 수당과 직업능력개발 수당과 광역 구직활동비와 이주비를 말합니다.","r":["구직급여"]},"업무상 재해":{"d":"업무상 사유로 근로자가 입은 부상과 질병과 장해와 사망으로 산재보험의 보상 대상입니다.","r":[]},"상병보상연금":{"d":"요양을 시작한 지 오래되어도 치유되지 않고 취업하지 못하는 근로자에게 휴업급여 대신 주는 연금입니다.","r":["장해급여"]},"장해급여":{"d":"치유 뒤에도 장해가 남은 근로자에게 장해등급에 따라 연금이나 일시금으로 주는 산재 급여입니다.","r":["상병보상연금"]},"장기요양급여":{"d":"혼자 일상생활을 하기 어려운 노인등에게 활동 지원이나 간병 또는 현금 등으로 주는 급여입니다.","r":["재가급여","시설급여","특별현금급여"]},"재가급여":{"d":"방문요양과 주·야간보호처럼 집에서 생활하면서 이용하는 장기요양급여입니다.","r":["시설급여"]},"시설급여":{"d":"장기요양기관에 장기간 입소한 수급자에게 제공하는 장기요양급여입니다.","r":["재가급여"]},"특별현금급여":{"d":"가족요양비와 특례요양비와 요양병원간병비처럼 현금으로 지급하는 장기요양급여입니다.","r":["장기요양급여"]},"보호대상아동":{"d":"보호자가 없거나 학대 등으로 양육에 적당하지 않아 국가의 보호가 필요한 아동입니다.","r":["가정위탁"]},"가정위탁":{"d":"보호대상아동을 일정 기간 기준에 맞는 가정에 맡겨 키우게 하는 보호조치입니다.","r":["보호대상아동"]},"아동학대관련범죄":{"d":"아동학대범죄처벌특례법상 아동학대범죄와 아동에 대한 형법상 살인의 죄를 아우르는 개념입니다.","r":[]},"노인학대":{"d":"노인에 대한 신체적·정서적·성적 폭력과 경제적 착취와 가혹행위와 유기·방임을 말합니다.","r":[]},"장애인권익옹호기관":{"d":"장애인학대 신고접수와 현장조사와 응급보호를 맡는 기관으로 중앙과 지역에 둡니다.","r":[]},"건강가정":{"d":"가족구성원의 욕구가 충족되고 인간다운 삶이 보장되는 가정입니다.","r":[]},"분과실행위원회":{"d":"공동모금회 안에서 기획과 홍보와 모금과 배분 업무를 나누어 맡는 실무 위원회입니다.","r":[]},"사회보장협정":{"d":"두 나라가 서로 국민의 사회보험 가입과 급여를 조정하려고 맺는 조약입니다.","r":["상호주의"]},"상호주의":{"d":"상대 나라가 우리 국민에게 베푸는 만큼 그 나라 국민에게도 같게 대우하는 원칙입니다.","r":["사회보장협정"]},"이중가입 방지":{"d":"같은 사람이 두 나라에서 보험료를 중복해 내지 않도록 한 나라만 적용하는 일입니다.","r":["가입기간 합산"]},"가입기간 합산":{"d":"두 나라의 보험 가입기간을 합쳐 연금 같은 급여의 수급 요건을 채우게 하는 일입니다.","r":["이중가입 방지"]}},"notes":{"18세 미만 근로자는 사업장가입자로 보되 원하지 않으면 제외":"18세 미만 근로자는 사업장가입자로 간주하지만 본인이 원하지 않으면 제외합니다.","1960년대: 아동복리법(1961) / 산업재해보상보험법(1963) / 생활보호법(1961)":"1960년대에 제정된 법으로 아동복리법과 생활보호법은 1961년, 산업재해보상보험법은 1963년입니다.","1970년대: 사회복지사업법(1970) / 국민복지연금법(1973) / 의료보호법(1977)":"1970년대에는 사회복지사업법이 1970년, 국민복지연금법이 1973년, 의료보호법이 1977년에 제정되었습니다.","1급은 국가시험 합격자에게 부여한다":"1급 자격은 국가시험에 합격한 사람에게 줍니다.","1단계는 시장·군수·구청장(교육급여는 시·도교육감)의 처분에 이의가 있으면 결정 통지를 받은 날부터 90일 이내에 해당 보장기관을 거쳐 시·도지사에게 서면 또는 구두로 신청":"1단계 이의신청은 결정 통지를 받은 날부터 90일 이내에 해당 보장기관을 거쳐 시·도지사에게 서면 또는 구두로 합니다.","1인가구는 1명이 단독으로 생계를 유지하고 있는 생활단위 (성인 1명 또는 그와 생계를 같이하는 미성년자녀로 구성된 생활단위는 한부모가구 설명으로 오답)":"1인가구는 한 명이 혼자 생계를 유지하는 생활단위이며 미성년 자녀와 사는 가구 설명은 한부모가구 것입니다.","2026 기출 선지: 국민건강보험법 / 다문화가족지원법 /":"가장 최근에 제정된 법률이 무엇인지 고르는 문제의 보기 앞부분으로, 법률 다섯 개가 이어서 제시됩니다.","2단계는 시·도지사 처분에 이의가 있으면 통지를 받은 날부터 90일 이내에 시·도지사를 거쳐 보건복지부장관(주거·교육급여는 소관 중앙행정기관의 장)에게 신청":"2단계는 시·도지사의 처분에 이의가 있을 때 90일 이내에 보건복지부장관에게 신청하는 것입니다.","5가지는 ① 출산지원시설(임신·출산 및 3세 미만 출산 아동 양육 주거 지원) ② 양육지원시설(6세 미만 자녀 동반) ③ 생활지원시설(18세 미만 자녀 동반) ④ 일시지원시설(배우자의 학대로 아동 양육이나 모·부 건강에 지장 우려 시 일시적 주거·생계 지원) ⑤ 한부모가족복지상담소":"한부모가족복지시설은 출산지원과 양육지원과 생활지원과 일시지원 등 다섯 가지이며 자녀 나이에 따라 구분됩니다.","60~65세 미만 노령연금 수급권자가 소득 있는 업무에 종사하면 초과소득월액 구간(200만원 이상 300만원 미만 15만원+초과분의 1천분의 150 / 300~400만원 30만원+1천분의 200 / 400만원 이상 50만원+1천분의 250)을 뺀다, 감액은 노령연금액의 2분의 1 한도":"60세 이상 65세 미만이 일하며 초과소득이 생기면 구간별로 정한 금액을 연금에서 줄이는 감액 규정입니다.","→ 국민건강보험법(1999 제정으로 대체)":"국민의료보험법이 국민건강보험법으로 대체되면서 1999년 제정 법이 이를 이어받았습니다.","→ 국민연금법(1986 전부개정)":"국민복지연금법은 1986년 전부개정을 통해 국민연금법으로 바뀌었습니다.","→ 기초연금법(2014 대체) → 장애인연금법과 개정 관계 없음":"기초노령연금법은 2014년 기초연금법으로 대체되었고 장애인연금법과는 개정 관계가 없습니다.","→ 아동복지법(1981 전부개정)":"아동복리법은 1981년에 전부개정되면서 아동복지법으로 이름이 바뀌었습니다.","→ 장애인복지법(1989 전부개정)":"심신장애자복지법은 1989년 전부개정으로 장애인복지법이 되었습니다.","→ 정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률(2016 전부개정)":"정신보건법은 2016년에 전부개정되어 지금의 긴 이름의 법이 되었습니다.","① 건강하고 쾌적한 환경에서 생활할 권리(환경권) ② 환경권 내용·행사는 법률로 ③ 국가는 주택개발정책 등을 통하여 쾌적한 주거생활을 위해 노력":"환경권과 쾌적한 주거생활을 위한 국가 노력을 정한 조항으로 내용과 행사는 법률에 맡깁니다.","① 근로의 권리. 국가는 사회적·경제적 방법으로 고용의 증진과 적정임금의 보장에 노력하여야 하며 법률에 따라 최저임금제를 시행하여야 한다 ② 근로의 의무 ③ 근로조건 기준은 인간의 존엄성 보장 ④ 여자의 근로 특별 보호와 부당한 차별 금지 ⑤ 연소자 근로 특별 보호 ⑥ 국가유공자·상이군경·전몰군경 유가족 우선적 근로 기회":"근로 기본권 조항으로 고용 증진과 최저임금제와 여자와 연소자 근로 보호를 담습니다.","① 근로자는 자주적인 단결권·단체교섭권·단체행동권을 가진다 ② 공무원인 근로자는 법률이 정하는 자에 한하여 노동3권을 가진다(모든 공무원 보장이 아님) ③ 주요방위산업체 근로자의 단체행동권은 법률로 제한·부인 가능":"노동3권인 단결권과 단체교섭권과 단체행동권을 보장하며 공무원은 법률이 정한 사람만 가집니다.","① 기초생활보장법상 의료급여 수급자 ② 재해구호법상 이재민으로 보건복지부장관이 필요하다고 인정한 사람 ③ 의사상자 등 예우 및 지원에 관한 법률에 따라 의료급여를 받는 사람 ④ 국내입양에 관한 특별법에 따라 입양된 18세 미만 아동 ⑤ 독립유공자·국가유공자·보훈보상대상자와 그 가족으로 국가보훈부장관이 추천해 보건복지부장관이 인정한 사람 ⑥ 국가무형유산 보유자(명예보유자 포함)와 그 가족으로 국가유산청장이 추천해 보건복지부장관이 인정한 사람 ⑦ 북한이탈주민과 그 가족으로 보건복지부장관이 인정한 사람 ⑧ 5·18민주화운동 관련 보상금등을 받은 사람과 그 가족으로 보건복지부장관이 인정한 사람 ⑨ 노숙인 등으로 보건복지부장관이 인정한 사람 ⑩ 그 밖에 대통령령으로 정하는 사람":"수급권자에는 기초생활보장법 수급자와 이재민과 의사상자와 입양된 18세 미만 아동 등 열 가지 유형이 있습니다.","① 능력에 따라 균등하게 교육을 받을 권리 ② 보호하는 자녀에게 적어도 초등교육과 법률이 정하는 교육을 받게 할 의무 ③ 의무교육 무상 ④ 교육의 자주성·전문성·정치적 중립성·대학의 자율성 ⑤ 국가는 평생교육을 진흥하여야 한다 ⑥ 교육제도 기본 사항은 법률로 정한다":"교육 기본권 조항으로 능력에 따른 균등 교육과 의무교육 무상과 평생교육 진흥을 담습니다.","① 사회복지를 필요로 하는 사람은 누구든지 자신의 의사에 따라 서비스를 신청하고 제공받을 수 있다":"사회복지법의 기본이념 중 하나로, 필요한 사람은 누구나 자기 뜻에 따라 서비스를 신청하고 받을 수 있습니다.","① 상담·지도 ② 친족 가정에서 보호·양육 ③ 적합한 유형의 가정에 위탁 ④ 아동복지시설 입소 ⑤ 전문치료기관 또는 요양소 입원·입소 ⑥ 입양과 관련하여 필요한 조치, 시·도지사 또는 시장·군수·구청장이 한다":"보호조치는 상담, 친족 가정 양육, 위탁, 시설 입소, 치료기관 입원, 입양 관련 조치 여섯 가지입니다.","① 인적사항 및 가족관계 확인 ② 소득·재산·근로능력 및 취업상태 ③ 사회보장급여 수급이력 ④ 그 밖에 수급권자를 선정하기 위해 보장기관의 장이 필요하다고 인정하는 사항":"수급자격 조사에서는 인적사항과 소득과 재산, 수급 이력 등 수급권자를 정하는 데 필요한 사항을 봅니다.","① 장애인복지법 장애인 거주시설 ② 노인복지법 노인주거복지시설·노인의료복지시설 ③ 아동복지시설 및 통합시설 ④ 정신요양시설·정신재활시설 ⑤ 노숙인재활시설·노숙인요양시설 ⑥ 가정폭력피해자 보호시설 ⑦ 성매매피해자등 지원시설 ⑧ 성폭력피해자보호시설 ⑨ 한부모가족복지시설 ⑩ 결핵 및 한센병요양시설 ⑪ 그 밖에 보건복지부령으로 정하는 시설":"보장시설에는 장애인 거주시설과 노인주거·의료복지시설과 아동복지시설과 정신요양·재활시설과 노숙인시설과 피해자 보호시설이 있습니다.","① 주소득자가 사망 가출 행방불명 구금시설 수용 등으로 소득 상실 ② 중한 질병 또는 부상 ③ 가구구성원으로부터 방임 또는 유기되거나 학대 등을 당함 ④ 가정폭력으로 원만한 가정생활이 곤란하거나 가구구성원으로부터 성폭력을 당함 ⑤ 화재 또는 자연재해 등으로 주택 또는 건물에서 생활 곤란 ⑥ 주소득자 또는 부소득자의 휴업 폐업 또는 사업장 화재 등으로 영업 곤란 ⑦ 주소득자 또는 부소득자의 실직으로 소득 상실 ⑧ 보건복지부령 기준에 따라 지방자치단체 조례로 정한 사유 ⑨ 그 밖에 보건복지부장관이 정하여 고시하는 사유":"위기상황의 사유는 주소득자의 소득 상실과 중한 질병과 방임과 학대와 가정폭력 등 아홉 가지입니다.","① 혼인과 가족생활은 개인의 존엄과 양성의 평등을 기초로 성립·유지 ② 국가는 모성의 보호를 위하여 노력 ③ 모든 국민은 보건에 관하여 국가의 보호를 받는다(제36조제3항)":"제36조는 혼인과 가족생활의 평등한 기초와 모성 보호, 모든 국민의 보건 보호를 정합니다.","② 사회복지법인 및 사회복지시설은 공공성을 가지며 사업 시행에서 공공성을 확보하여야 한다":"사회복지법인과 시설은 공공성을 가지므로 사업을 할 때 공공성을 확보해야 합니다.","③ 사회복지를 제공하는 자는 필요로 하는 사람의 인권을 보장하여야 한다":"서비스를 제공하는 사람은 도움이 필요한 사람의 인권을 지켜야 합니다.","④ 서비스 제공자는 필요한 정보를 제공하는 등 이용자의 선택권을 보장하여야 한다":"서비스 제공자는 필요한 정보를 주어 이용자가 선택할 수 있도록 선택권을 보장해야 합니다.","④ 업무수행 중 고의·중대한 과실로 타인에게 손해를 입힘 ⑤ 자격정지 처분 3회 이상 또는 정지 종료 후 3년 이내 재차 정지 해당 행위 ⑥ 자격정지 기간에 자격증을 사용해 업무 수행":"재량으로 취소하거나 정지하는 사유에는 업무 중 고의나 중대한 과실로 타인에게 손해를 입힌 경우 등이 있습니다.","④에 해당해 취소·정지하려면 한국사회복지사협회의 장 등 관계 전문가의 의견을 들을 수 있다":"그 사유로 처분하려면 한국사회복지사협회의 장 같은 관계 전문가의 의견을 들을 수 있습니다.","가입기간은 월 단위로 계산한다":"가입기간은 일이 아니라 월 단위로 셉니다.","가입자 종류 4가지는 사업장가입자 / 지역가입자 / 임의가입자 / 임의계속가입자":"가입자는 사업장과 지역과 임의와 임의계속가입자 네 가지입니다.","가입자 종류는 직장가입자와 지역가입자":"건강보험 가입자는 직장가입자와 지역가입자 두 가지입니다.","가정위탁은 성범죄 가정폭력 아동학대 정신질환 등의 전력이 없는 보건복지부령 기준 적합 가정에 보호대상아동을 일정 기간 위탁":"범죄나 학대나 정신질환 전력이 없는 기준에 맞는 가정에 보호대상아동을 일정 기간 맡기는 제도입니다.","가정위탁지원센터는 시·도 및 시·군·구에 둔다, 가정위탁사업 홍보 및 가정 발굴 / 조사·상담 / 교육 / 사례관리 / 친부모 가정 복귀 지원 / 자립계획 및 사례 관리 / 정보 제공":"가정위탁지원센터는 시·도와 시·군·구에 두고 위탁 가정 발굴과 상담과 교육과 친부모 복귀 지원 등을 합니다.","가정은 가족구성원이 생계 또는 주거를 함께 하는 생활공동체로서 부양·양육·보호·교육 등이 이루어지는 생활단위":"가정은 생계나 주거를 함께하는 생활공동체로 부양과 양육과 보호와 교육이 이루어지는 단위입니다.","가정의 달은 5월 / 가정의 날은 5월 15일":"5월은 가정의 달이고 5월 15일은 가정의 날입니다.","가정이 건전하게 유지되고 그 기능이 향상되도록 노력하여야 하며 제도 시행 때 가정과 지역공동체의 자발적 복지활동을 촉진하여야 한다":"가정이 건전하게 유지되고 기능이 향상되도록 노력하고, 가정과 지역공동체의 자발적 복지활동도 북돋워야 합니다.","가정폭력을 예방하고 피해자를 보호·지원":"가정폭력방지법은 가정폭력을 예방하고 피해자를 보호하고 지원하려는 법입니다.","가족요양비는 도서·벽지 등 기관 부족 지역 거주자 / 천재지변 등으로 기관 이용이 어려운 자 / 신체·정신·성격 등 대통령령 사유로 가족 등으로부터 요양을 받아야 하는 자가 가족 등에게서 방문요양에 상당한 급여를 받은 때 지급":"기관이 부족한 지역에 살거나 천재지변 등으로 기관을 이용하기 어려운 사람이 가족에게 요양받을 때 주는 비용입니다.","가족은 혼인·혈연·입양으로 이루어진 사회의 기본단위":"사회를 이루는 최소 단위로서 가족의 성립 근거를 혼인과 혈연과 입양 세 가지로 정의합니다.","가족지원서비스는 아동의 양육·교육 / 장애인·노인·만성질환자 부양 / 가사 / 가족관계 증진 교육·상담 / 인지청구 및 자녀양육비 청구 등 법률구조 / 유전자검사비용 지원":"양육·교육과 부양과 가사와 가족관계 교육·상담과 법률구조와 유전자검사비용 지원 등이 가족지원서비스입니다.","각 시설의 수용인원은 300명 초과 불가(대통령령 정하는 경우 제외), 200명이라는 선지는 오답":"시설 수용인원은 300명을 넘을 수 없고 200명이라는 말은 틀립니다.","간병급여는 요양급여를 받은 사람 중 치유 후 의학적으로 상시 또는 수시로 간병이 필요하여 실제로 간병을 받는 사람에게 지급":"치유 후에도 상시 또는 수시로 간병이 필요해 실제로 간병을 받는 사람에게 지급하는 급여입니다.","감사는 이사·시설의 장·시설 직원을 겸할 수 없다":"감사는 감시 대상인 이사와 시설 운영진을 겸하지 못해 독립성을 지킵니다.","감사는 이사와 특별한 관계가 없어야 하고 감사 중 1명은 법률 또는 회계 지식이 있는 사람 중에서 선임":"감사는 이사와 특별한 관계가 없어야 하고 그중 1명은 법률이나 회계 지식이 있는 사람이어야 합니다.","개별가구는 급여를 받거나 자격요건 조사를 받는 기본단위로서 수급자 또는 수급권자로 구성된 가구 / 소득인정액은 개별가구의 소득평가액과 재산의 소득환산액을 합산한 금액 / 차상위계층은 수급권자에 해당하지 않는 계층으로서 소득인정액이 대통령령으로 정하는 기준 이하인 계층":"개별가구는 급여를 받는 기본단위이고, 소득인정액은 소득평가액과 재산의 소득환산액의 합이며, 차상위계층은 기준 이하인 계층입니다.","개선·사업정지·장 교체·폐쇄 명령은 보건복지부장관·시·도지사·시장·군수·구청장이 설치기준 미달 / 법인 설립허가 취소 / 설치 목적 달성 / 회계부정·불법행위 / 무신고 설치·운영 / 운영위원회 미설치·미운영 / 보고·자료제출 거부 / 검사·질문 거부 / 성폭력·학대관련범죄 발생 / 1년 이상 휴지 후 재개 권고 불응 시 명할 수 있다":"시설이 설치기준에 못 미치거나 회계부정을 하거나 운영위원회가 없으면 개선과 사업정지와 폐쇄 명령을 받을 수 있습니다.","개의·회의 중지·산회 일시 / 안건 / 의사 / 출석 임원 성명 / 표결수 / 그 밖에 대표이사가 필요하다고 인정하는 사항을 기재":"회의록에는 개의와 산회 일시와 안건과 출석 임원과 표결수 등을 적습니다.","거부 시 급여 결정 취소 또는 정지·중지 가능":"조사를 거부하면 급여 결정을 취소하거나 정지하거나 중지할 수 있습니다.","거짓·부정 수령과 목적 외 사용은 반환을 명하여야 한다":"보조금을 거짓으로 받거나 목적 외에 쓰면 반환을 명해야 합니다.","건강가정기본계획은 성평등가족부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립하고 국무회의 심의로 확정, 1인가구 복지 증진 대책 포함":"건강가정기본계획은 장관이 5년마다 세우고 국무회의 심의로 확정하며 1인가구 복지 대책을 포함합니다.","건강가정은 가족구성원의 욕구가 충족되고 인간다운 삶이 보장되는 가정 / 건강가정사업은 가정문제 예방·해결과 가정기능 강화 사업":"건강가정은 구성원의 욕구가 채워지고 인간다운 삶이 보장되는 가정이고 건강가정사업은 문제 예방과 기능 강화 사업입니다.","건강검진은 공단이 가입자와 피부양자에 대해 실시, 일반건강검진(직장가입자 세대주인 지역가입자 20세 이상 지역가입자 20세 이상 피부양자) / 암검진 / 영유아건강검진(6세 미만)":"공단은 가입자와 피부양자에게 일반건강검진과 암검진과 6세 미만 영유아건강검진을 실시합니다.","건강검진은 시장·군수·구청장이 수급권자에 대해 질병의 조기발견과 그에 따른 의료급여를 위해 할 수 있다":"시장·군수·구청장은 질병을 일찍 발견하고 의료급여로 이어지도록 건강검진을 할 수 있습니다.","건강보험사업은 보건복지부장관이 맡아 주관한다":"건강보험 사업을 주관하는 곳은 보건복지부장관입니다.","건강보험정책을 심의·의결하기 위해 보건복지부장관 소속으로 둔다":"건강보험정책심의위원회는 정책을 심의하고 의결하려고 보건복지부장관 소속으로 둡니다.","건강손상자녀의 보험급여는 요양급여 / 장해급여 / 간병급여 / 장례비 / 직업재활급여":"건강손상자녀에게는 요양과 장해와 간병과 장례비와 직업재활급여를 줍니다.","건강진단은 국가 또는 지방자치단체는 65세 이상에 대하여 건강진단과 보건교육을 실시할 수 있다":"건강진단과 보건교육은 65세 이상 노인을 대상으로 공공이 할 수 있는 사업입니다.","결격사유(제19조제1항제1호의7~제1호의9 등)에 해당하면 종사자가 될 수 없다":"종사자도 법이 정한 결격사유에 해당하면 일할 수 없습니다.","결격은 정신질환자(전문의가 적합하다고 인정한 사람 제외) / 마약·대마·향정신성의약품 중독자 / 피성년후견인 / 금고 이상 실형 집행 종료·면제 전 / 집행유예 기간 중 / 법원 판결로 자격 정지·상실 / 취소 후 1년 미경과":"요양보호사 결격사유에는 정신질환자와 약물 중독자와 피성년후견인과 실형 집행이 끝나지 않은 사람 등이 있습니다.","고등교육법상 교직원은 포함되지 않는다":"신고의무자 가운데 대학 같은 고등교육법의 교직원은 포함되지 않습니다.","고령이나 노인성 질병으로 일상생활을 혼자 수행하기 어려운 노인등에게 신체활동·가사활동 지원 등 장기요양급여를 제공해 노후의 건강증진 및 생활안정을 도모하고 가족의 부담을 덜어 국민의 삶의 질을 향상":"장기요양보험법은 일상생활이 어려운 노인에게 신체활동과 가사활동 지원을 해 노후 건강과 생활안정 및 가족 부담 경감을 꾀합니다.","고용보험기금은 고용노동부장관이 설치하고 관리·운용한다(기획재정부장관 아님), 보험료 징수금 적립금 기금운용 수익금 등으로 조성":"고용보험기금은 고용노동부장관이 설치하고 관리·운용하며 기획재정부장관이 아닙니다.","고용보험사업 4가지는 고용안정·직업능력개발 사업 / 실업급여 / 육아휴직 급여 / 출산전후휴가 급여 등, 보험연도는 정부의 회계연도에 따른다":"네 갈래 사업을 고용안정부터 출산전후휴가까지 두며 보험연도는 정부의 회계연도에 맞춥니다.","고용보험심사위원회는 고용노동부에 두며 근로자·사용자 대표 각 1명 이상을 포함한 15명 이내, 재심사 청구를 받으면 50일 이내 재결":"고용보험심사위원회는 고용노동부에 두며 15명 이내이고 재심사 청구를 받으면 50일 이내에 재결합니다.","고용보험위원회는 고용노동부에 둔다, 위원장 포함 20명 이내이고 위원장은 고용노동부차관, 위원은 근로자·사용자·공익·정부 대표를 같은 수로 구성, 보험제도 개선 / 보험료율 결정 / 사업 평가 / 기금운용 계획 등을 심의":"고용보험위원회는 고용노동부에 두며 위원장은 차관이고 근로자와 사용자와 공익과 정부 대표를 같은 수로 구성합니다.","고용부담금제도는 고용의무제 실효성 확보 수단으로 입법목적의 정당성이 인정되며 고용의무를 이행하는 사업주와 아닌 사업주 사이의 경제적 부담의 불균형을 조정하는 기능을 한다":"부담금제도는 고용의무를 지키게 하려는 정당한 목적을 가지며 이행하는 사업주와 아닌 사업주의 부담 불균형을 조정합니다.","고용 촉진은 직업능력개발훈련을 실시하여야 하고 우선 고용 노력, 공공시설 매점 우선 허가 / 시설 우선이용 / 국민주택 우선 분양 노력":"직업능력개발훈련은 반드시 실시하고 우선 고용 노력과 공공시설 매점 우선 허가와 국민주택 우선 분양 노력도 합니다.","공공부조 및 일정 소득 수준 이하 국민의 사회서비스 비용은 전부 또는 일부를 국가와 지방자치단체가 부담(지방자치단체 전부 부담 아님)":"공공부조와 일정 소득 이하 국민의 사회서비스 비용은 국가와 지방자치단체가 전부 또는 일부를 내며 지자체가 전부 내는 것은 아닙니다.","공단의 업무는 가입자 및 피부양자의 자격 관리 / 보험료와 그 밖의 징수금의 부과·징수 / 보험급여의 관리 / 질병의 조기발견·예방·건강관리 예방사업 / 보험급여 비용의 지급 / 자산의 관리·운영 및 증식사업 / 의료시설의 운영 / 건강보험 교육훈련 및 홍보 / 조사연구 및 국제협력 / 징수위탁근거법(국민연금법 고용산재보험료징수법 임금채권보장법 석면피해구제법)에 따라 위탁받은 업무 / 그 밖의 위탁 업무":"공단은 자격 관리와 보험료 징수와 보험급여 관리와 예방사업과 급여 비용 지급과 자산 운영 등을 합니다.","공동모금을 통해 국민이 사회복지를 이해하고 참여하도록 하고 자발적 성금으로 조성된 재원을 효율적이고 공정하게 관리·운용해 사회복지증진에 이바지":"공동모금으로 국민이 사회복지에 참여하게 하고 자발적 성금을 효율적이고 공정하게 관리해 복지를 증진하려는 법입니다.","공무원연금·군인연금·사학연금·별정우체국법 적용 대상자 등은 제외":"다른 직역연금의 적용을 받는 사람은 국민연금 가입 대상에서 빠집니다.","과징금은 업무정지가 수급권자에게 심한 불편을 주면 갈음하여 속임수로 부담하게 한 급여비용의 5배 이하 금액을 부과, 12개월 범위에서 분할 납부 가능":"업무정지가 수급권자에게 큰 불편을 줄 때는 대신 속임수 부담액의 5배 이하 과징금을 매기고 12개월 안에 나누어 낼 수 있습니다.","관계 법령에 따로 정하면 국가나 지방자치단체가 신청을 대신할 수 있다":"법령에 따로 정해 두었다면 국가나 지방자치단체가 신청을 대신 해 줄 수도 있습니다.","관계 법령에 따로 정한 경우는 예외":"법령에 따로 규정한 경우에는 제한이나 정지가 예외적으로 허용됩니다.","관계 중앙행정기관의 장과 지방자치단체의 장은 위원회의 심의·조정 사항을 반영하여 사회보장제도를 운영 또는 개선하여야 한다":"위원회가 심의하고 조정한 사항은 중앙행정기관과 지방자치단체가 제도 운영과 개선에 반영해야 합니다.","관계 중앙행정기관의 장과 지방자치단체의 장이 보건복지부장관에게 제출, 보건복지부장관이 종합해 위원회에 제출(통계청장 아님)":"통계는 보건복지부장관에게 모이고 이를 종합해 위원회에 내며 통계청장이 종합하는 것은 아닙니다.","관련 공공기관·비영리법인·시설 등에 위탁해 실시할 수 있고 비용은 보장기관이 부담":"자활급여는 공공기관이나 비영리법인 등에 위탁해 실시할 수 있고 비용은 보장기관이 부담합니다.","관리운영기관은 공단, 공단 업무는 자격관리 / 보험료 부과·징수 / 신청인 조사 / 등급판정위원회 운영 및 등급 판정 / 인정서 작성 / 급여 관리 및 평가 / 정보 제공·상담 / 급여비용 심사·지급 / 부당이득금 부과·징수 / 노인성질환예방사업 등":"장기요양의 관리운영기관은 공단이며 자격 관리와 보험료 징수와 조사와 등급 판정과 급여 관리 등을 합니다.","관습법 / 판례법 / 조리 (관습법·판례법·조리를 성문법원이라고 한 선지는 오답)":"관습법과 판례법과 조리는 문서로 정해진 법이 아니라 불문법원에 속합니다.","관습법 판례법도 인정되는 불문법을 포함하되 성문법원이 중심이다 (관습법은 법원이 될 수 없다는 선지는 오답)":"불문법인 관습법과 판례법도 법원으로 인정되며 성문법이 중심이고 관습법이 법원이 못 된다는 말은 틀립니다.","광역 구직활동비는 직업안정기관의 소개에 따라 광범위한 지역에서 구직 활동을 하는 경우 필요하다고 인정하면 지급":"소개받아 넓은 지역에서 구직 활동을 할 때 필요하다고 인정하면 주는 비용입니다.","교육급여는 입학금 수업료 학용품비 그 밖의 수급품 지급, 교육부장관 소관, 선정기준은 기준 중위소득의 100분의 50 이상":"교육급여는 입학금과 수업료와 학용품비 등을 주며 교육부장관 소관이고 기준 중위소득 100분의 50 이상이 선정기준입니다.","교육을 이유로 불리한 처분을 하여서는 아니 된다":"보수교육을 받았다는 이유로 불리한 처분을 해서는 안 됩니다.","구상권은 제3자의 행위로 보험급여사유가 생겨 급여를 한 경우 급여 비용 한도에서 제3자에게 손해배상 청구권":"제3자의 잘못으로 급여 사유가 생겨 급여를 했다면 공단은 급여 비용 범위에서 제3자에게 손해배상을 청구할 수 있습니다.","구상권은 제3자의 행위로 의료급여를 한 경우 시장·군수·구청장은 급여비용 범위에서 제3자에게 손해배상 청구권을 얻는다":"제3자의 행위로 의료급여를 했다면 시장·군수·구청장은 급여비용 범위에서 제3자에게 손해배상을 청구할 수 있습니다.","구성은 시설의 장 / 거주자 대표 / 거주자 보호자 대표 / 종사자 대표 / 해당 시·군·구 사회복지업무 담당 공무원 / 후원자 대표 또는 지역주민 / 공익단체 추천인 / 전문 지식·경험이 풍부한 사람, 관할 시장·군수·구청장이 임명하거나 위촉":"위원은 시설의 장과 거주자와 보호자와 종사자 대표와 담당 공무원과 후원자와 지역주민과 전문가 등으로 구성합니다.","구성은 위원장 1명 부위원장 1명 포함 25명, 위원장은 보건복지부차관, 위원 임기 3년(공무원 위원 제외)":"위원은 위원장과 부위원장 각 1명을 포함해 25명이고 위원장은 보건복지부차관이며 위원 임기는 3년입니다.","구 장애인고용촉진등에관한법률 제35조제1항 본문은 헌법에 합치(합헌)한다는 취지":"헌법재판소가 장애인고용촉진법의 부담금 조항을 헌법에 합치한다고 결정했다는 취지입니다.","구직급여일액은 기초일액의 100분의 60, 최저기초일액(이직 전 1일 소정근로시간 x 최저임금)이 적용되면 그 기초일액의 100분의 80(최저구직급여일액)":"구직급여일액은 기초일액의 100분의 60이고 최저기초일액이 적용되면 그 기초일액의 100분의 80입니다.","국가기본계획은 행정안전부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립":"국가기본계획은 행정안전부장관이 부처와 협의해 5년마다 수립합니다.","국가나 지방자치단체는 모금회에 기부금품 모집에 필요한 비용과 관리·운영에 필요한 비용을 보조할 수 있다":"공공은 모금회의 기부금품 모집 비용과 관리·운영 비용을 보조할 수 있습니다.","국가나 지방자치단체는 시설을 설치·운영할 수 있다":"국가와 지방자치단체는 사회복지시설을 직접 설치하고 운영할 수 있습니다.","국가는 개인이 가지는 불가침의 기본적 인권을 확인하고 이를 보장할 의무를 진다 (행복추구권이 헌법 제10조)":"국가는 불가침의 기본 인권을 확인하고 보장할 의무가 있으며 행복추구권은 헌법 제10조에 근거합니다.","국가는 노인과 청소년의 복지향상을 위한 정책을 실시할 의무를 진다":"노인과 청소년의 복지를 높이는 정책을 국가가 펼쳐야 할 의무로 정한 조항입니다.","국가는 매년 보험사업에 드는 비용의 일부를 일반회계에서 부담하여야 한다(지방자치단체 아님), 관리·운영 비용은 예산 범위에서 부담할 수 있다":"국가는 해마다 보험사업 비용의 일부를 일반회계에서 부담해야 하며 지방자치단체가 아닙니다.","국가는 보수 등 비용의 전부 또는 일부를 보조할 수 있다":"국가는 사회복지전담공무원의 보수 같은 비용의 전부나 일부를 보조할 수 있습니다.","국가는 사회보장·사회복지의 증진에 노력할 의무를 진다 (공공부조 아님)":"국가가 사회보장과 사회복지의 증진에 힘쓸 의무를 지는 조항으로, 공공부조를 정한 것은 아닙니다.","국가는 양성이 평등한 육아휴직제 확대와 생애주기에 따른 가족구성원의 종합적인 건강증진대책을 마련하여야 한다":"국가는 양성이 평등한 육아휴직 확대와 생애주기별 가족 건강증진대책을 마련해야 합니다.","국가는 여자의 복지와 권익의 향상을 위하여 노력하여야 한다":"여성의 복지와 권익의 향상을 위해 국가가 노력해야 한다는 조항입니다.","국가는 재해를 예방하고 그 위험으로부터 국민을 보호하기 위하여 노력하여야 한다":"국가는 재해를 막고 위험에서 국민을 보호하려고 노력해야 합니다.","국가데이터처가 공표하는 통계자료의 가구 경상소득(근로·사업·재산·이전소득 합산)의 중간값에 가구소득 평균 증가율 가구규모별 소득수준 차이를 반영해 가구규모별로 산정":"통계자료의 가구 경상소득 중간값에 소득 증가율과 가구규모별 차이를 반영해 가구규모별로 산정합니다.","국가 등의 책무는 신고체계 구축 / 조사·연구·교육·홍보 / 보호시설 설치·운영 / 임대주택 우선 입주권·직업훈련 등 자립·자활 지원 / 법률구조 / 협력 체계 / 법령 정비 / 종사자 신변보호 / 신변노출 방지 / 아동 상담·치료 프로그램":"국가 등은 신고체계와 조사·연구·홍보와 보호시설과 자립·자활 지원과 법률구조 등을 해야 합니다.","국가 등의 책임은 한부모가족의 복지 증진 책임 / 여건 조성과 시책 수립·시행 / 편견·차별 예방과 이해 교육·홍보 / 교육부장관과 교육감은 학교에서 이해 교육 시책 수립 / 청소년 한부모가족 자립 노력 / 모든 국민은 복지 증진에 협력":"국가 등은 한부모가족의 복지를 높일 여건을 만들고 편견과 차별을 예방하며 학교에서 이해 교육을 하도록 합니다.","국가 또는 시·도가 직접 수행하는 업무 비용은 국가 또는 해당 시·도 부담, 시·군·구 보장비용 중 급여 실시 비용 등은 국가가 100분의 40 이상 100분의 90 이하를 부담하고 시·도는 나머지 중 100분의 30 이상 100분의 70 이하를 부담하며 나머지는 시·군·구가 부담":"100분의 40 이상 100분의 90 이하는 국가가, 시·도는 나머지의 100분의 30 이상 100분의 70 이하를 냅니다.","국가 및 지방자치단체가 발굴조사를 연 1회 이상 정기적으로 실시":"발굴조사는 연 1회 이상 정기적으로 합니다.","국가 및 지방자치단체의 책무는 노인성질환예방사업 실시 / 적정한 수의 장기요양기관 확충과 설립 지원 / 국·공립 기관 확충 노력 / 장기요양요원 처우 개선 노력":"노인성질환 예방사업과 기관 확충 및 설립 지원과 국·공립 기관 확충과 요양요원 처우 개선에 노력해야 합니다.","국가 및 지방자치단체의 책무는 위기상황에 처한 사람을 찾아내 신속 지원 노력 / 지원 후에도 위기상황이 해소되지 않으면 다른 법률에 따른 구호·보호·지원을 받도록 노력 / 어려우면 민간기관·단체와 연계":"위기에 처한 사람을 찾아 빨리 돕고 해소되지 않으면 다른 법의 보호로 이어 주며 어려우면 민간과 연계하는 책무입니다.","국가시험은 보건복지부장관이 시행하고 관리는 전문기관에 위탁할 수 있다":"시험 시행 책임은 장관에게 있고 관리 업무는 전문기관에 맡길 수 있습니다.","국가아동권리보장원은 국가가 설립, 아동정책 자료 개발·분석 / 기본계획 수립 및 시행계획 평가 지원 / 위원회 운영 지원 / 아동보호서비스 기술지원 / 아동학대예방사업 / 가정위탁사업 활성화 / 지역 아동복지 지원 / 입양 체계 구축·운영(국내입양에 관한 특별법 및 국제입양에 관한 법률) / 아동 관련 조사·통계·교육·홍보":"국가가 세운 보장원은 아동정책 자료를 분석하고 계획 수립을 지원하며 학대예방과 가정위탁 사업 등을 합니다.","국가안전보장·질서유지·공공복리를 위하여 필요한 경우에 한하여 법률로써 제한할 수 있고 본질적인 내용은 침해할 수 없다":"자유와 권리는 필요한 경우에만 법률로 제한할 수 있고 그 본질적인 내용은 침해할 수 없습니다.","국가에 대하여 적극적 급부·배려를 요구하는 권리로 자유권과 대비된다":"사회적 기본권은 국가에 급부와 배려를 요구하는 권리로 국가의 간섭을 막는 자유권과 대비됩니다.","국가와 지방자치단체가 자원봉사활동의 홍보 및 교육 / 프로그램 개발·보급 / 활동 중 재해 대비 시책 개발 / 그 밖의 지원 사항을 실시하여야 한다":"국가와 지방자치단체는 자원봉사 홍보와 교육, 프로그램 개발, 재해 대비 시책 등을 해야 합니다.","국가와 지방자치단체가 작성·관리":"사회보장통계는 국가와 지방자치단체가 만들고 관리합니다.","국가와 지방자치단체는 관계 법령에 따라 상담에 응하여야 한다":"국가와 지방자치단체는 사회보장에 관한 상담 요청에 응해야 합니다.","국가와 지방자치단체는 급여 수준 향상에 노력하고, 국가는 관계 법령에 따라 최저보장수준과 최저임금을 매년 공표하며 국가와 지방자치단체는 이를 고려해 급여 수준을 결정한다":"국가는 최저보장수준과 최저임금을 매년 공표하고 이를 고려해 급여 수준을 정합니다.","국가와 지방자치단체는 기존 제도와의 관계, 전달체계·재정에 미치는 영향, 지역별 특성을 사전 검토하고 급여가 중복·누락되지 않게 하여야 한다":"새 제도를 만들 때 기존 제도와의 관계와 재정 영향과 지역 특성을 미리 따지고 급여의 중복과 누락을 막아야 합니다.","국가와 지방자치단체는 민간 참여 유도 정책을 개발·시행하고 자원봉사·기부 활성화, 상호협력체계 구축 지원 사업 등을 시책에 포함할 수 있다":"민간의 참여를 끌어내는 정책을 마련하고 자원봉사와 기부 활성화를 시책에 담을 수 있습니다.","국가와 지방자치단체는 서비스 품질향상과 원활한 제공을 위해 필요한 시책을 마련하여야 한다":"서비스의 품질을 높이고 원활히 제공하기 위해 필요한 시책을 반드시 마련해야 합니다.","국가와 지방자치단체는 서비스 환경·서비스 제공 인력의 전문성 등을 평가할 수 있다":"서비스의 시설 환경과 인력의 전문성 같은 질을 국가와 지방자치단체가 점검할 수 있습니다.","국가와 지방자치단체의 책임 하에 생활 유지 능력이 없거나 생활이 어려운 국민의 최저생활을 보장하고 자립을 지원하는 제도":"공공부조는 국가와 지방자치단체가 생활이 어려운 국민의 최저생활을 보장하고 자립을 돕는 제도입니다.","국가의 부담은 매년 예산 범위에서 장기요양보험료 예상수입액의 100분의 20에 상당하는 금액을 공단에 지원, 의료급여수급권자의 급여비용 등과 관리운영비는 국가와 지방자치단체가 전액 부담":"국가는 장기요양보험료 예상수입의 100분의 20에 해당하는 금액을 해마다 예산 범위에서 공단에 지원합니다.","국가의 부담은 회계연도마다 예산 범위에서 보험사업의 사무 집행에 드는 비용을 일반회계에서 부담하여야 한다, 사업비용의 일부는 지원할 수 있다":"국가는 해마다 예산 범위에서 보험사업의 사무 집행 비용을 일반회계로 부담해야 하며 사업비용 일부는 지원할 수 있습니다.","국가·지방자치단체가 설치한 시설은 사회복지법인이나 비영리법인에 위탁 운영하게 할 수 있다":"공공이 설치한 시설은 사회복지법인이나 비영리법인에 위탁해 운영하게 할 수 있습니다.","국가·지방자치단체가 운영비 등을 보조할 수 있다":"시설의 운영에 드는 경비는 공공이 재정으로 도울 수 있다고 정한 보조금 규정입니다.","국가·지방자치단체·공공기관·법인이 법령에 따라 생성·취득해 관리하는 자료·정보로서 사회보장 정책 수행에 필요한 것":"사회보장 행정데이터는 법령에 따라 생성되거나 취득해 관리되고 정책 수행에 필요한 자료와 정보입니다.","국가·지방자치단체는 비용의 전부 또는 일부를 보조할 수 있다(전부 보조 의무 아님)":"국가와 지방자치단체는 보험 비용의 일부나 전부를 보조할 수 있으나 전부를 보조할 의무는 없습니다.","국가·지방자치단체·민간부문의 도움이 필요한 모든 국민에게 복지·보건의료·교육·고용·주거·문화·환경 등의 분야에서 상담·재활·돌봄·정보제공·시설이용·역량개발·사회참여 지원 등으로 삶의 질을 높이는 제도":"사회서비스는 도움이 필요한 모든 국민에게 상담과 재활과 돌봄 등으로 삶의 질을 높이는 제도입니다.","국가·지방자치단체 외의 자는 시장·군수·구청장에게 신고(보건복지부 신고·허가 아님)":"국가와 지방자치단체가 아닌 자가 시설을 설치하려면 시장·군수·구청장에게 신고하며 보건복지부 신고나 허가가 아닙니다.","국내 거주 외국인에게는 상호주의 원칙에 따르되 관계 법령에서 정하는 바에 따른다":"국내에 사는 외국인에게는 상호주의를 기본으로 하면서 관계 법령이 정한 대로 적용합니다.","국내에 거주하는 국민으로서 18세 이상 60세 미만(65세 미만 아님)":"가입 대상은 국내 거주 국민 중 18세 이상 60세 미만이며 65세 미만이 아닙니다.","국내에 거주하는 국민은 가입자 또는 피부양자가 된다":"국내 거주 국민은 누구나 건강보험의 가입자 아니면 피부양자가 됩니다.","국내외 사회보장환경의 변화와 전망 / 기본목표 및 중장기 추진방향 / 주요 추진과제 및 추진방법 / 필요한 재원의 규모와 조달방안 / 사회보장 관련 기금 운용방안 / 사회보장 전달체계 / 그 밖에 정책 추진에 필요한 사항":"기본계획에는 환경의 변화와 전망, 목표, 추진과제, 필요한 재원 규모, 기금 운용, 전달체계 등이 들어갑니다.","국내 체류 외국인 중 ① 대한민국 국민과 혼인해 본인 또는 배우자가 임신 중인 사람 ② 대한민국 국적의 미성년 자녀를 양육하는 사람 ③ 배우자의 대한민국 국적인 직계존속과 생계나 주거를 같이하는 사람으로서 대통령령으로 정하는 사람이 급여 자격을 가진 경우 수급권자가 된다(직계비속·성인 장애인 동거는 아님)":"국내 체류 외국인 중 국민과 혼인해 임신한 사람과 국민인 미성년 자녀를 키우는 사람 등은 수급권자가 될 수 있습니다.","국무총리 또는 행정각부의 장은 소관사무에 관하여 법률이나 대통령령의 위임 또는 직권으로 총리령 또는 부령을 발할 수 있다":"국무총리나 행정각부의 장은 자기 맡은 일에 관해 위임을 받거나 직권으로 총리령이나 부령을 낼 수 있습니다.","국민건강보험법상 외국 정부가 사용자인 사업장의 근로자는 외국 정부와의 합의로 따로 정할 수 있다":"외국 정부가 사용자인 사업장의 근로자는 건강보험 적용을 그 정부와 합의해 별도로 정할 수 있습니다.","국민건강보험종합계획은 보건복지부장관이 건강보험정책심의위원회 심의를 거쳐 5년마다 수립":"종합계획은 장관이 건강보험정책심의위원회 심의를 거쳐 5년마다 세웁니다.","국민기초생활보장법(1999)":"1999년에는 국민기초생활보장법도 제정되어 생활보호법 체계를 대체했습니다.","국민기초생활 보장법 / 아동복지법 / 노인복지법 / 장애인복지법 / 한부모가족지원법 / 영유아보육법 / 성매매방지 및 피해자보호 등에 관한 법률 / 정신건강증진 및 정신질환자 복지서비스 지원에 관한 법률 / 성폭력방지 및 피해자보호 등에 관한 법률 / 국내입양에 관한 특별법 및 국제입양에 관한 법률 / 일제하 일본군위안부 피해자에 대한 생활안정지원 및 기념사업 등에 관한 법률 / 사회복지공동모금회법 / 장애인·노인·임산부 등의 편의증진 보장에 관한 법률 / 가정폭력방지 및 피해자보호 등에 관한 법률 / 농어촌주민의 보건복지증진을 위한 특별법 / 식품등 기부 활성화에 관한 법률 / 의료급여법 / 기초연금법 / 긴급복지지원법 / 다문화가족지원법 / 장애인연금법 / 장애인활동 지원에 관한 법률 / 노숙인 등의 복지 및 자립지원에 관한 법률 / 보호관찰 등에 관한 법률 / 장애아동 복지지원법 / 발달장애인 권리보장 및 지원에 관한 법률 / 청소년복지 지원법 / 스토킹방지 및 피해자보호 등에 관한 법률 / 그 밖에 대통령령으로 정하는 법률":"사회복지사업법이 말하는 사회복지사업 관련 법률로 국민기초생활보장법과 아동복지법 등 여러 법이 열거됩니다.","국민복지연금법 → 1986 국민연금법으로 전부개정":"국민복지연금법은 1986년 전부개정을 거쳐 국민연금법이라는 이름이 됩니다.","국민생활에 중대한 영향을 미치는 계획·정책 수립 시 공청회·정보통신망 등으로 국민과 전문가 의견을 충분히 수렴":"국민 생활에 큰 영향을 줄 계획을 세울 때 공청회와 정보통신망 등으로 국민과 전문가 의견을 널리 듣습니다.","국민연금공단은 보건복지부장관의 위탁을 받아 설립":"공단은 보건복지부장관의 위탁을 받아 국민연금 업무를 하려고 세운 기관입니다.","국민연금법으로 개정된 전신이 국민복지연금법이다":"국민연금법의 앞 이름이 국민복지연금법이라는 관계를 나타냅니다.","국민연금사업은 보건복지부장관이 맡아 주관한다(기획재정부장관 아님)":"국민연금 사업을 주관하는 곳은 보건복지부장관이며 기획재정부장관이 아닙니다.","국민연금 수급권자의 기초연금액은 (기준연금액 - 소득재분배급여금액 x 2/3) + 부가연금액(기준연금액의 2분의 1), 뺀 금액이 0보다 작으면 0":"국민연금 수급권자는 기준연금액에서 소득재분배급여 3분의 2를 빼고 부가연금액을 더하며 음수면 0입니다.","국민연금심의위원회는 보건복지부에 둔다":"연금 제도를 심의하는 이 위원회는 보건복지부 소속으로 설치됩니다.","국민연금 외국인은 외국인도 당연히 사업장가입자 또는 지역가입자가 된다, 다만 본국 법이 대한민국 국민에게 상응하는 연금을 적용하지 않으면 제외(상호주의)":"외국인은 원칙적으로 가입자가 되지만 그 나라가 우리 국민에게 상응하는 연금을 적용하지 않으면 제외하는 상호주의입니다.","국민의 노령 장애 또는 사망에 대하여 연금급여를 실시해 생활 안정과 복지 증진에 이바지":"국민연금법은 노령과 장애와 사망에 연금급여를 주어 생활 안정과 복지를 높이려는 법입니다.","국민의 자유와 권리는 헌법에 열거되지 아니한 이유로 경시되지 아니한다":"헌법에 적혀 있지 않다는 이유로 국민의 자유와 권리가 가볍게 여겨져서는 안 됩니다.","국회 의결 법률안은 정부에 이송되어 15일 이내에 대통령이 공포한다":"국회가 의결한 법률안은 정부로 넘어가고 대통령이 15일 이내에 공포합니다.","국회의원과 정부는 모두 법률안을 제출할 수 있다":"법률안은 국회의원뿐 아니라 정부도 제출할 수 있습니다.","군 복무 크레딧은 현역병 전환복무 상근예비역 사회복무요원의 복무기간을 12개월 한도로 가입기간에 추가 산입(병역 6개월 미만은 제외), 재원은 국가가 전부 부담":"군 복무 크레딧은 복무기간을 12개월 한도로 가입기간에 더해 주며 병역이 6개월 미만이면 제외하고 국가가 비용을 모두 냅니다.","권한 위탁은 시장·군수·구청장 업무 중 수급권자 관리 급여비용 심사·조정 적정성 평가 급여 대상 확인 급여비용 지급을 관계 전문기관에 위탁할 수 있다":"수급권자 관리와 급여비용 심사 등 일부 업무는 관계 전문기관에 맡길 수 있습니다.","균등부분은 연금 수급 3년 전·2년 전·전년도 평균소득월액을 물가변동률로 환산해 합산하고 3으로 나눈 금액, 소득비례부분은 가입 중 매년 기준소득월액을 재평가율로 현재가치 환산해 합산한 뒤 총 가입기간으로 나눈 금액":"균등부분은 수급 3년 전부터 전년까지 평균소득월액을 물가로 환산해 3으로 나누고 소득비례부분은 가입 중 소득을 현재가치로 환산합니다.","근로능력이 있는 수급자에게는 자활사업 참가를 조건으로 실시할 수 있다":"일할 수 있는 수급자에게는 자활사업에 참가하는 것을 조건으로 생계급여를 실시할 수 있습니다.","근로복지공단은 고용노동부장관의 위탁을 받아 설립(법인), 보험급여의 결정과 지급 / 보험료 징수 / 심사 청구 심리·결정 / 산재보험 시설 설치·운영 / 진료·요양 및 재활 / 재활보조기구 연구개발 / 건강진단 등 예방 사업 / 복지 증진 사업":"근로복지공단은 산재보험의 급여 결정과 보험료 징수와 심사 청구 심리와 재활 업무 등을 맡습니다.","근로자는 직업의 종류와 상관없이 사업장에서 노무를 제공하고 임금을 받아 생활하는 자(법인의 이사와 임원 포함) / 사용자는 해당 근로자가 소속된 사업장의 사업주 / 평균소득월액은 매년 사업장가입자 및 지역가입자 전원의 기준소득월액을 평균한 금액 / 기준소득월액은 연금보험료와 급여를 산정하기 위해 가입자의 소득월액을 기준으로 정하는 금액 / 부담금은 사용자가 부담하는 금액 / 기여금은 사업장가입자가 부담하는 금액":"용어 정의로, 근로자는 임금으로 생활하는 사람이고 사용자는 사업주이며 평균소득월액은 가입자 소득을 기준으로 산정합니다.","근로자는 직업 종류와 관계없이 근로 대가로 보수를 받아 생활하는 사람(법인의 이사 등 임원 포함)으로서 공무원과 교직원은 제외":"건강보험법의 근로자는 근로 대가로 보수를 받는 사람이며 임원은 포함하고 공무원과 교직원은 따로 정해 제외합니다.","근로자를 사용하는 모든 사업 또는 사업장(위험률·규모·장소 등을 고려해 대통령령으로 정하는 사업 제외)":"산재보험도 근로자를 쓰는 모든 사업장에 적용하되 위험률과 규모를 고려해 대통령령으로 정하는 사업은 제외합니다.","근로자를 사용하는 모든 사업 또는 사업장, 대통령령으로 정하는 사업은 제외":"고용보험은 근로자를 쓰는 모든 사업에 적용하되 대통령령으로 정한 사업은 제외합니다.","근로자의 고의·자해행위나 범죄행위 또는 그것이 원인이 되어 발생한 재해는 업무상 재해로 보지 않는다(정상적 인식능력이 뚜렷하게 낮아진 상태의 행위는 예외)":"근로자의 고의나 자해와 범죄행위로 생긴 재해는 업무상 재해가 아니며 인식 능력이 뚜렷이 낮아진 때는 예외입니다.","금융정보(예금 평균잔액 등)·신용정보(채무액 등)·보험정보(보험료 등) 제공 동의 서면을 받아야 한다":"금융과 신용과 보험 정보를 제공받으려면 지원대상자에게 동의 서면을 받아야 합니다.","금융정보등 사용·제공·누설은 5년 이하 징역 또는 5천만원 이하 벌금 / 조사로 얻은 정보·자료 목적 외 사용·제공은 3년 이하 징역 또는 3천만원 이하 벌금 / 거짓·부정한 방법으로 급여를 받거나 받게 한 자와 급여 목적 외 사용은 1년 이하 징역 1천만원 이하 벌금 구류 또는 과료 / 직무상 비밀 누설은 1년 이하 징역 또는 1천만원 이하 벌금 / 보장시설 위탁 거부·종교행위 강제는 300만원 이하 벌금 구류 또는 과료 (2021 기출 당시 부정수급 5년 이하 5천만원이 정답 선지였음)":"금융정보 누설은 5년 이하 징역이나 5천만원 이하 벌금이고 목적 외 사용은 3년 이하나 3천만원 이하 벌금입니다.","금전 지급이 원칙이고 금전으로 지급할 수 없거나 적당하지 않으면 물품 지급 가능(물품 지급 불가 아님)":"생계급여는 금전 지급이 원칙이지만 금전으로 주기 적당하지 않으면 물품으로 줄 수 있습니다.","금지행위는 아동 매매 / 음란한 행위 시킴·매개 및 성적 학대 / 신체적 학대 / 정서적 학대 / 유기·방임 / 장애 아동 공중 관람 / 구걸 시킴 / 유해 곡예 / 무권한 양육 알선 및 금품 취득 / 아동을 위한 금품 목적 외 사용":"아동 매매와 성적 학대와 신체적·정서적 학대와 유기·방임과 구걸 시킴 등이 금지행위에 해당합니다.","급여가 필요 없게 된 경우 또는 수급자가 거부한 경우 전부 또는 일부를 중지하여야 한다":"급여가 필요 없게 되거나 수급자가 거부하면 전부 또는 일부를 중지해야 합니다.","급여는 개별가구 단위로 실시한다":"급여는 원칙적으로 개별가구를 단위로 실시합니다.","급여는 건강하고 문화적인 최저생활을 유지할 수 있어야 한다":"급여 수준의 하한은 단순 생존이 아니라 건강과 문화생활이 가능한 정도로 잡습니다.","급여는 수급권자의 청구에 따라 공단이 지급":"급여는 자동으로 나오지 않고 수급권자가 청구하면 공단이 지급합니다.","급여는 수급자 신청에 따라 수급자 명의의 급여수급계좌로 입금":"수급자의 신청이 있으면 본인 명의의 전용 계좌로 급여가 들어갑니다.","급여는 신청일부터 시작한다(매년 1월 새로 수급자가 되는 사람은 그 해 1월 1일)":"급여는 신청한 날부터 시작하며 매년 1월에 새로 수급자가 되면 그 해 1월 1일부터 시작합니다.","급여를 받으려는 사람은 관계 법령에 따라 국가나 지방자치단체에 신청하여야 한다":"신청주의가 원칙이라 급여는 국가나 지방자치단체에 먼저 신청해야 받을 수 있습니다.","급여를 받을 권리는 양도할 수 없다":"급여를 받을 권리는 다른 사람에게 넘길 수 없습니다.","급여비용은 대통령령에 따라 전부 또는 일부를 의료급여기금에서 부담하고 일부 부담 시 나머지는 본인이 부담":"급여비용은 의료급여기금에서 전부 또는 일부를 부담하고 일부만 부담하면 나머지는 본인이 냅니다.","급여비용 청구는 의료급여기관이 급여비용심사기관에 심사청구 → 심사기관이 심사 후 시장·군수·구청장과 의료급여기관에 통보 → 시장·군수·구청장이 지급":"의료급여기관이 심사기관에 청구하고 심사 후 통보하면 시장·군수·구청장이 지급하는 순서입니다.","급여비용 청구는 장기요양기관은 재가·시설급여를 제공한 경우 공단에 장기요양급여비용을 청구하여야 한다(시·도지사 아님), 공단이 심사 후 공단부담금 지급":"장기요양기관은 급여 비용을 공단에 청구해야 하며 시·도지사가 아니고 공단은 심사한 뒤 공단부담금을 지급합니다.","급여 수급권은 양도·담보 제공·압류 불가, 이의가 있으면 결정 통지일부터 90일 이내 서면으로 복지실시기관에 심사청구하고 30일 이내 결정 통보":"급여 수급권은 양도·담보·압류가 안 되고 이의는 통지일부터 90일 이내 서면 심사청구하며 30일 이내 결정을 통보합니다.","급여 실시 주체는 수급권자 또는 수급자의 거주지를 관할하는 시·도지사와 시장·군수·구청장, 교육급여는 시·도교육감, 주거가 일정하지 않으면 실제 거주 지역 관할 시장·군수·구청장":"급여는 수급권자 거주지를 관할하는 시·도지사와 시장·군수·구청장이 실시하며 교육급여는 시·도교육감이 합니다.","급여의 종류 3가지는 재가급여 / 시설급여 / 특별현금급여":"장기요양급여는 재가급여와 시설급여와 특별현금급여로 나뉩니다.","급여의 특례는 수급권자에 해당하지 않아도 생활이 어려워 일정 기간 급여가 필요하다고 보건복지부장관 또는 소관 중앙행정기관의 장이 정하는 사람은 수급권자로 본다":"수급권자가 아니어도 생활이 어려워 일정 기간 급여가 필요하다고 정해진 사람은 수급권자로 봅니다.","급여 정지는 국외에 체류하는 경우 / 현역병 등 직장가입자 제외 사유에 해당하게 된 경우 / 교도소 등에 수용된 경우 (현역병·수용 시 요양급여비용 지급은 별도)":"국외 체류나 현역병 등 제외 사유나 교도소 수용 같은 경우에는 보험급여가 정지됩니다.","급여 제공은 수급자는 장기요양인정서와 개인별장기요양이용계획서가 도달한 날부터 급여를 받을 수 있다, 월 한도액 범위 안에서 제공(등급과 급여 종류 고려)":"수급자는 인정서와 이용계획서가 도달한 날부터 급여를 받을 수 있고 월 한도액 범위 안에서 제공됩니다.","급여 제한(하지 아니한다)은 고의 또는 중대한 과실로 인한 범죄행위에 원인이 있거나 고의 사고 / 고의 또는 중대한 과실로 공단·요양기관의 요양 지시에 따르지 않음 / 문서 제출 거부·질문·진단 기피 / 업무 또는 공무로 생긴 질병·부상·재해로 다른 법령의 보험급여나 보상을 받게 되는 경우":"고의나 중대한 과실로 범죄를 저지르거나 요양 지시를 따르지 않거나 서류 제출을 거부하면 급여를 하지 않습니다.","급여 제한은 고의로 질병·부상·사고를 일으켜 장애를 입으면 장애연금을 지급하지 않을 수 있다, 가입자 등을 고의로 사망하게 한 유족 등에게는 유족연금 등 지급하지 않음":"일부러 사고를 내서 장애가 생기면 장애연금을 주지 않을 수 있고 가입자를 고의로 숨지게 한 유족에게는 유족연금을 주지 않습니다.","급여 제한은 정당한 사유 없이 조사·자료제출 요구에 응하지 않으면 전부 또는 일부 제공하지 않을 수 있다, 기관의 부정 청구에 가담한 경우 중단하거나 1년의 범위에서 횟수·기간 제한":"정당한 사유 없이 조사에 응하지 않거나 기관의 부정 청구에 가담하면 급여를 주지 않거나 1년 범위에서 제한합니다.","급여 종류 4가지는 노령연금 / 장애연금 / 유족연금 / 반환일시금 (장해급여 장애인연금은 이 법의 급여가 아님, 사망일시금은 급여 종류 열거 외 별도 규정 제80조)":"국민연금의 급여는 노령연금과 장애연금과 유족연금과 반환일시금이고 장애인연금은 이 법의 급여가 아닙니다.","급여 환수는 거짓·부정 수령 / 신고의무자의 신고 불이행 또는 지연 / 사망 추정 후 생존 확인 / 상속권 상실 유족 지급 / 그 밖의 잘못 지급은 환수하여야 한다, 일부 경우 이자 가산":"거짓으로 받은 급여와 신고의무 불이행과 사망 추정 후 생존과 잘못 지급된 급여는 환수하고 일부는 이자를 더합니다.","기관·단체 대표자 자격으로 위촉된 위원은 대표 지위를 유지하는 기간 (2023·2024·2025 기출에서 3년·4년은 모두 오답)":"대표 자격으로 위촉된 위원의 임기는 대표 지위를 유지하는 동안이며 3년이나 4년이 아닙니다.","기금 용도는 고용안정·직업능력개발 사업 경비 / 실업급여 지급 / 국민연금 보험료의 지원 / 육아휴직 급여 및 출산전후휴가 급여등 지급 / 보험료의 반환 / 일시 차입금의 상환금과 이자 / 법에 따른 업무를 대행하거나 위탁받은 자에 대한 출연금 / 그 밖에 대통령령 정하는 경비":"기금은 고용안정과 직업능력개발 사업과 실업급여와 육아휴직 급여 등의 지급에 씁니다.","기금은 보건복지부장관이 설치하고 관리·운용, 재원은 연금보험료 / 기금 운용 수익금 / 적립금 / 공단 결산상 잉여금, 국민연금기금운용위원회가 기금운용을 심의·의결(위원 임기 2년 1차 연임 회의 연 4회 이상)":"기금은 장관이 설치하고 운용하며 재원은 보험료와 운용수익과 적립금과 공단 잉여금이고 기금운용위원회가 심의·의결합니다.","기본계획 / 사회보장 관련 주요 계획 / 제도의 평가 및 개선 / 제도 신설·변경에 따른 우선순위 / 둘 이상 중앙행정기관이 관련된 주요 정책 / 급여 및 비용 부담 / 국가와 지방자치단체의 역할 및 비용 분담 / 재정추계 및 재원조달 방안 / 전달체계 운영 및 개선 / 사회보장통계 / 사회보장정보의 보호 및 관리 / 제26조제4항에 따른 조정 / 위원장이 심의에 부치는 사항":"위원회는 기본계획, 제도의 평가와 개선, 비용 분담, 재정추계, 전달체계, 통계와 정보 보호 같은 사항을 심의합니다.","기본계획은 성평등가족부장관이 5년마다 수립하고 관계 중앙행정기관의 장과 협의, 다문화가족정책위원회 심의 후 확정, 국회 소관 상임위원회에 보고":"기본계획은 5년마다 세우고 부처와 협의해 다문화가족정책위원회 심의 후 확정하며 국회 상임위원회에 보고합니다.","기본 방향은 국민의 협동적 참여 능력을 높이는 방향 / 무보수성·자발성·공익성·비영리성·비정파성·비종파성의 원칙 / 사회적 배경에 관계없이 누구나 참여 / 민·관 협력 기본 정신 (무차별성은 원칙에 포함되지 않음)":"자원봉사는 무보수·자발성·공익성·비영리·비정파·비종파 원칙에 따르고 누구나 참여하며 민·관이 협력하는 방향입니다.","기본연금액은 (균등부분 A값 3년 평균 + 소득비례부분 B값)을 합한 금액 x 1천분의 1천290, 가입기간이 20년을 초과하면 초과 1년마다 1천분의 50을 더한다":"기본연금액은 균등부분과 소득비례부분을 합해 1천분의 1천290을 곱하고 20년 초과 1년마다 1천분의 50을 더해 계산합니다.","기본 원칙 ① 기부하는 자의 의사에 반하여 기부금품을 모집하여서는 아니 된다 ② 공동모금재원은 지역·단체·대상자 및 사업별로 복지수요가 공정하게 충족되도록 배분하고 목적과 용도에 맞게 공정하게 관리·운용 ③ 공동모금재원의 배분은 객관적인 기준에 따라 효율적으로 이루어지도록 하고 그 결과를 공개하여야 한다":"기부하는 사람의 뜻에 반해 모집해서는 안 되고 모금재원은 지역과 단체와 대상자별로 복지수요가 공정하게 채워지도록 배분합니다.","기본원칙은 노인등이 자신의 의사와 능력에 따라 최대한 자립적으로 일상생활을 수행할 수 있도록 제공 / 심신상태·생활환경·욕구·선택을 종합 고려해 적정하게 제공 / 가족과 함께 생활하며 가정에서 받는 재가급여를 우선 제공 / 의료서비스와 연계":"급여는 노인이 스스로의 뜻과 능력에 맞게 자립적으로 살도록 돕고 심신 상태와 선택을 종합해 적정하게 제공해야 합니다.","기본이념은 노인은 존경받으며 건전하고 안정된 생활을 보장받는다 / 능력에 따라 적당한 일에 종사하고 사회적 활동에 참여할 기회를 보장받는다 / 심신의 건강을 유지하고 지식과 경험을 활용해 사회 발전에 기여하도록 노력한다":"노인은 존경받으며 안정된 생활을 보장받고 능력에 따라 일하고 사회 활동에 참여할 기회를 보장받습니다.","기본 이념은 어떠한 차별도 받지 않고 자람 / 안전한 가정환경에서 행복하게 자람 / 아동에 관한 모든 활동에서 아동의 이익이 최우선 고려 / 보호와 지원을 받을 권리":"아동은 차별받지 않고 안전한 가정환경에서 자라며 모든 활동에서 아동의 이익이 최우선으로 고려되어야 합니다.","기본이념은 장애인의 완전한 사회 참여와 평등을 통하여 사회통합을 이루는 데에 있다":"장애인이 사회에 완전히 참여하고 평등해져서 사회통합을 이루는 것이 이 법의 기본이념입니다.","기본재산과 보통재산으로 구분하고 기본재산 목록·가액은 정관에 기재":"재산은 기본재산과 보통재산으로 나누고 기본재산의 목록과 가액은 정관에 적습니다.","기본재산의 매도·증여·교환·임대·담보제공·용도변경이나 일정 금액 이상 1년 이상 장기차입은 시·도지사의 허가":"기본재산을 팔거나 담보로 주거나 일정 금액 이상을 1년 이상 빌릴 때는 시·도지사의 허가가 필요합니다.","기본재산 허가 위반과 보조금 목적 외 사용은 5년 이하 징역 또는 5천만원 이하 벌금":"기본재산과 보조금 관련 위반은 이 법의 벌칙 가운데 비교적 무거운 5년 이하 징역에 해당합니다.","기부금품의 모집은 연중 모집·접수할 수 있다, 접수 사실을 장부에 기록하고 영수증 교부":"기부금품은 연중 모집·접수할 수 있고 접수 사실을 장부에 적고 영수증을 줍니다.","기업의 경제상 자유는 공공복리를 위해 법률로 제한할 수 있고 국가는 경제민주화를 위해 규제·조정할 수 있다":"경제활동의 자유도 무제한이 아니라 공공복리와 경제민주화를 이유로 법률과 국가 규제에 제한됩니다.","기준기간은 이직일 이전 18개월(36개월 아님), 질병·부상 등으로 계속 30일 이상 보수를 받지 못한 경우 18개월에 그 일수를 가산(3년 한도), 1주 소정근로시간 15시간 미만 및 소정근로일수 2일 이하 근로자는 24개월":"기준기간은 이직일 이전 18개월이며 36개월이 아니고 질병 등으로 30일 이상 보수를 못 받으면 그 일수를 더하되 3년까지입니다.","기준연금액은 보건복지부장관이 전년도 기준연금액에 전국소비자물가변동률을 반영해 매년 고시, 적용기간은 해당 연도 1월부터 12월까지, 2021년 기준연금액은 30만원":"기준연금액은 장관이 전년도 금액에 물가변동률을 반영해 매년 고시하고 적용기간은 해당 연도 1월부터 12월까지입니다.","기준연금액을 지급하는 사람은 국민연금 등 해당 없는 사람 / 지급 정지된 노령연금·분할연금 수급권자 / 장애인연금 수급권자 / 기초생활보장 수급권자로 대통령령이 정하는 사람 등, 국민연금 급여액이 기준연금액의 100분의 150 이하인 사람에게도 기준연금액":"국민연금 등이 없는 사람이나 지급 정지된 노령연금 수급권자나 장애인연금 수급권자 등은 기준연금액을 받습니다.","기준은 연령 가구 규모 거주지역 생활여건 등을 고려해 급여 종류별로 보건복지부장관이 정하거나 소관 중앙행정기관의 장이 보건복지부장관과 협의해 정한다":"급여 기준은 연령과 가구 규모와 거주지역과 생활여건을 고려해 보건복지부장관이 정하거나 협의해 정합니다.","기초연금법에서 장애인연금법으로 바뀐 것이 아니다":"두 법은 서로 다른 법률이라 기초연금법이 장애인연금법으로 바뀐 것이 아닙니다.","기초연금액이 기준연금액을 초과하면 기준연금액으로 본다":"계산된 기초연금액이 기준연금액보다 많으면 기준연금액까지만 인정합니다.","기초연금이 필요한 수준이 되도록 최대한 노력 / 재원 조성(국민연금기금은 기초연금 지급 재원으로 사용 불가) / 계층 간 소득역전 현상과 근로의욕·저축유인 저하 방지 노력":"국가는 기초연금이 필요한 수준이 되게 노력하고 재원을 마련하되 국민연금기금은 지급 재원으로 쓰지 못합니다.","기초일액은 수급자격 인정과 관련된 마지막 이직 당시 근로기준법상 평균임금, 통상임금보다 적으면 통상임금":"기초일액은 마지막 이직 당시의 평균임금이고 통상임금보다 적으면 통상임금으로 삼습니다.","긴급전화는 국가 및 지방자치단체는 노인학대를 예방하고 수시로 신고를 받을 수 있도록 긴급전화를 설치하여야 한다":"국가와 지방자치단체는 노인학대 신고를 수시로 받을 긴급전화를 반드시 설치해야 합니다.","긴급지원기관은 긴급지원대상자의 거주지를 관할하는 시장·군수·구청장, 거주지가 분명하지 않으면 지원요청·신고를 받은 시장·군수·구청장, 긴급지원담당공무원을 지정":"긴급지원기관은 대상자의 거주지를 관할하는 시장·군수·구청장이고 거주지가 분명치 않으면 요청을 받은 단체장입니다.","긴급한 필요가 있으면 결정 전이라도 급여의 일부를 실시할 수 있다":"급히 필요하면 결정이 나기 전에도 급여의 일부를 먼저 실시할 수 있습니다.","난민법에 따른 난민인정자로 기초생활보장법상 의료급여 수급권자 범위에 해당하는 사람은 수급권자로 본다":"난민으로 인정받아도 기초생활보장법상 의료급여 대상이면 수급권자에 포함시키는 특례입니다.","납부기한은 그 달의 보험료를 다음 달 10일까지, 보수 외 소득월액보험료와 지역가입자 보험료는 분기별 납부 가능":"그 달의 보험료는 다음 달 10일까지 내며 소득월액보험료와 지역가입자 보험료는 분기별로 낼 수 있습니다.","납부 기한은 다음 달 10일까지(농어업인은 신청하면 분기별로 해당 분기의 다음 달 10일까지)":"보험료는 다음 달 10일까지 내며 농어업인은 신청하면 분기별로 그 분기의 다음 달 10일까지 낼 수 있습니다.","납부 예외는 사업 중단·실직·휴직 / 병역의무 수행 / 학교 재학 / 교정시설 수용 / 치료감호시설 수용 / 1년 미만 행방불명 / 소득 감소 등, 내지 않은 기간은 가입기간에 산입하지 않음":"사업 중단과 실직과 병역과 재학과 수용 등의 사유가 있으면 납부를 면하지만 그 기간은 가입기간에 산입하지 않습니다.","납부의무는 보수월액보험료는 사용자(2명 이상이면 연대), 보수 외 소득월액보험료는 직장가입자, 지역가입자는 세대 전원 연대, 사용자는 근로자 부담분을 보수에서 공제해 납부":"보수월액보험료는 사용자가 내고 소득월액보험료는 직장가입자가 내며 지역가입자는 세대 전원이 연대하여 책임집니다.","내용은 생계비 / 아동교육지원비 / 아동양육비 / 그 밖에 대통령령으로 정하는 비용 (아동수당은 포함되지 않음)":"복지 급여는 생계비와 아동교육지원비와 아동양육비 등이며 아동수당은 포함되지 않습니다.","노령연금액은 가입기간 20년 이상이면 기본연금액, 10년 이상 20년 미만이면 기본연금액의 1천분의 500 + 10년 초과 1년마다 1천분의 50, 여기에 부양가족연금액을 더한다":"가입 20년 이상이면 기본연금액을 받고 10년 이상 20년 미만이면 1천분의 500에 10년 초과 1년마다 1천분의 50을 더합니다.","노인 금지행위는 폭행·상해 / 성폭행·성희롱 / 유기·방임 / 구걸을 하게 하거나 노인을 이용한 구걸 / 노인을 위한 금품 목적 외 사용 / 정서적 학대":"노인에 대한 폭행과 성폭행과 유기·방임과 구걸 이용과 금품의 목적 외 사용과 정서적 학대가 금지됩니다.","노인등은 65세 이상의 노인 또는 65세 미만으로 치매·뇌혈관성질환 등 대통령령이 정하는 노인성 질병을 가진 자 (60세 이상이라는 선지는 오답)":"노인등은 65세 이상이거나 65세 미만이라도 치매나 뇌혈관성질환 같은 노인성 질병이 있는 사람이고 60세 이상이 아닙니다.","노인복지법은 1981년 제정":"노인복지법은 1981년에 제정되어 노인장기요양보험법보다 먼저 만들어졌습니다.","노인복지상담원은 특별자치도와 시·군·구에 둔다":"상담원은 특별자치도와 시·군·구라는 지역 단위에 배치됩니다.","노인복지시설 7가지는 ① 노인주거복지시설 ② 노인의료복지시설 ③ 노인여가복지시설 ④ 재가노인복지시설 ⑤ 노인보호전문기관 ⑥ 노인일자리지원기관 ⑦ 학대피해노인 전용쉼터 (독거노인종합지원센터는 제외)":"노인복지시설은 주거복지와 의료복지와 여가복지와 재가노인복지시설과 보호전문기관과 일자리지원기관과 학대피해노인 전용쉼터입니다.","노인복지시설 설치·운영자가 두어야 하며 요양보호사교육기관 교육과정을 마치고 시·도지사의 자격시험에 합격하여야 한다, 자격증은 시·도지사가 교부(보건복지부장관 아님), 대여·알선 금지":"시설 설치자가 요양보호사를 두어야 하며 교육과정을 마치고 시·도지사의 자격시험에 합격하고 자격증도 시·도지사가 교부합니다.","노인복지주택 입소자격은 60세 이상의 노인(65세 아님), 배우자와 부양 책임이 있는 24세 미만 자녀·손자녀 또는 장애로 부양하는 24세 이상 자녀·손자녀는 함께 입소 가능":"노인복지주택은 60세 이상이 입소하며 65세가 아니고 배우자와 부양하는 24세 미만 자녀·손자녀가 함께 입소할 수 있습니다.","노인사회참여 지원은 노인의 지역봉사 활동기회 확대 / 적합 직종 개발 / 근로능력 있는 노인에게 일할 기회 우선 제공 노력, 노인지역봉사기관 노인취업알선기관 등 지원":"노인의 지역봉사 기회를 넓히고 알맞은 직종을 개발하며 일할 능력이 있는 노인에게 일자리를 우선 제공하도록 노력합니다.","노인실태조사는 보건복지부장관이 3년마다 실시하고 공표":"보건복지부장관이 3년마다 노인실태조사를 실시하고 공표합니다.","노인에게 기초연금을 지급해 안정적인 소득기반을 제공함으로써 노인의 생활안정을 지원하고 복지를 증진":"기초연금법은 노인에게 연금을 주어 소득기반을 안정시키고 생활과 복지를 돕는 법입니다.","노인여가복지시설은 노인복지관 / 경로당 / 노인교실, 노인복지관은 여가복지시설":"여가복지시설은 노인복지관과 경로당과 노인교실이며 노인복지관도 여기에 속합니다.","노인의 날은 매년 10월 2일 / 경로의 달은 10월 / 어버이날은 5월 8일 / 노인학대예방의 날은 6월 15일":"10월 2일이 노인의 날이고 10월 전체가 경로의 달이며 어버이날과 노인학대예방의 날은 5월 8일과 6월 15일입니다.","노인의료복지시설은 노인요양시설 / 노인요양공동생활가정 (노인요양공동생활가정은 노인의료복지시설이고 주거복지시설이 아님)":"노인요양시설과 노인요양공동생활가정이 의료복지시설이며 공동생활가정은 주거복지시설이 아닙니다.","노인의 질환을 사전예방·조기발견하고 질환상태에 맞는 치료·요양으로 심신의 건강을 유지하며 노후 생활안정에 필요한 조치로 보건복지증진에 기여":"노인복지법은 질환을 예방하고 조기에 발견해 치료와 요양으로 건강을 지키고 노후 생활안정을 돕는 법입니다.","노인 일자리 및 사회활동 지원에 관한 법률 / 사회보장기본법 / 긴급복지지원법 중":"보기로 나온 법률 가운데 나머지 선지를 이어서 나열한 부분입니다.","노인 일자리 및 사회활동 지원에 관한 법률이 정답":"다섯 개 법률 중 노인 일자리 및 사회활동 지원에 관한 법률이 가장 늦게 제정된 정답입니다.","노인일자리전담기관은 노인인력개발기관 노인취업알선기관 노인일자리지원기관":"일자리 사업을 전담하는 곳으로 인력개발과 취업알선과 일자리지원 기능을 하는 세 종류의 기관이 있습니다.","노인장기요양보험법(2007) / 다문화가족지원법(2008)":"노인장기요양보험법은 2007년, 다문화가족지원법은 2008년에 제정된 법입니다.","노인장기요양보험법은 2007년 제정":"요양 보험의 근거 법률이 마련된 때가 2007년이라는 제정 시기 정보입니다.","노인주거복지시설은 양로시설 / 노인공동생활가정 / 노인복지주택":"노인이 거처로 삼는 시설로 양로시설과 공동생활가정과 노인복지주택 세 가지가 해당합니다.","노인학대는 노인에 대하여 신체적·정신적·정서적·성적 폭력 및 경제적 착취 또는 가혹행위를 하거나 유기 또는 방임을 하는 것":"노인학대는 신체적·정신적·정서적·성적 폭력과 경제적 착취와 가혹행위와 유기·방임을 말합니다.","노인학대 신고는 누구든지 노인학대를 알게 된 때에는 노인보호전문기관 또는 수사기관에 신고할 수 있다, 직무상 65세 이상 노인에 대한 학대를 알게 된 신고의무자(의료인 사회복지사 노인복지시설 종사자 장기요양기관 종사자 119구급대원 가정폭력상담소 종사자 등 16종)는 즉시 신고하여야 한다":"누구든 노인학대를 알게 되면 보호전문기관이나 수사기관에 신고할 수 있고 직무상 알게 된 신고의무자는 반드시 신고해야 합니다.","누구든지 정당한 이유 없이 사회복지시설의 설치를 방해하여서는 아니 된다":"정당한 이유 없이 누구도 사회복지시설의 설치를 방해해서는 안 됩니다.","누구든지 지원대상자를 발견하면 보장기관에 알려야 한다":"지원대상자를 발견한 사람은 누구든지 보장기관에 알려야 합니다.","다른 기관에 신청한 경우 그 기관은 지체 없이 정당한 권한이 있는 기관에 이송하여야 하고, 이송된 날을 신청일로 본다":"엉뚱한 기관에 신청해도 권한 있는 기관으로 바로 넘기고 넘긴 날을 신청일로 봅니다.","다른 법령에 따라 국가·지방자치단체로부터 보험급여에 상당하는 급여를 받으면 그 한도에서 하지 않는다":"다른 법으로 국가나 지방자치단체에서 같은 성격의 급여를 받으면 그만큼은 보험급여를 하지 않습니다.","다른 법령에 따라 수립되는 사회보장 계획에 우선하며 그 계획의 기본이 된다":"기본계획은 다른 법령에 따른 사회보장 계획보다 우선하고 그 계획의 바탕이 됩니다.","다른 법령에 따라 지원을 받으면 그 범위에서 급여하지 않으나 아동양육비는 지급할 수 있다":"같은 목적의 지원이 겹치면 중복을 피하되 아동양육비만은 예외적으로 계속 줄 수 있습니다.","다른 법령으로 의료급여에 상당하는 급여를 받으면 그 한도에서 하지 않는다":"다른 법으로 의료급여에 맞먹는 급여를 받으면 그만큼은 의료급여를 하지 않습니다.","다른 법령의 보호 수준이 이 법의 수준에 못 미치면 나머지는 이 법에 따라 받을 권리를 잃지 않는다":"다른 법령의 보호가 이 법에 못 미치면 모자라는 부분은 이 법에 따라 받을 수 있습니다.","다른 법률(재해구호법 기초생활보장법 의료급여법 사회복지사업법 가정폭력방지법 성폭력방지법 등)로 동일 내용 지원을 받고 있으면 이 법에 따른 지원을 하지 않는다":"같은 내용의 지원을 이미 다른 법으로 받고 있다면 이 법의 지원은 중복되지 않게 하지 않습니다.","다른 사회보장 법률을 제정·개정할 때는 이 법에 부합되도록 하여야 한다":"다른 사회보장 법률을 만들거나 고칠 때는 이 법의 취지에 맞게 해야 합니다.","다문화가족 구성원이 안정적인 가족생활을 영위하고 사회구성원으로서 역할과 책임을 다하도록 하여 삶의 질 향상과 사회통합에 이바지":"다문화가족지원법은 구성원의 안정된 가족생활과 사회구성원의 역할을 도와 삶의 질과 사회통합을 높이려는 법입니다.","다문화가족은 결혼이민자와 국적취득자로 이루어진 가족 / 출생이 아닌 국적취득자(인지·귀화)끼리 이루어진 가족, 결혼이민자등은 결혼이민자 + 귀화허가를 받은 자":"다문화가족은 결혼이민자와 국적취득자로 이루어진 가족이며 국적취득자끼리 이룬 가족은 해당하지 않습니다.","다문화가족정책위원회는 국무총리 소속, 위원장 포함 20명 이내이고 위원장은 국무총리":"다문화가족정책위원회는 국무총리 소속으로 위원장은 국무총리이며 위원장 포함 20명 이내입니다.","다문화가족지원센터는 국가·지방자치단체가 설치·운영하거나 법인·단체에 위탁, 그 외의 자는 시·도지사 또는 시장·군수·구청장의 지정, 업무는 교육·상담 / 한국어교육 / 정보제공·홍보 / 서비스 연계 / 일자리 정보·알선 / 통역·번역 / 가정폭력 방지 및 피해자 연계":"국가나 지방자치단체가 설치하거나 법인·단체에 위탁하며 그 밖의 사람은 단체장의 지정을 받아야 합니다.","다함께돌봄센터는 초등학교 정규교육 이외의 시간 방과 후 돌봄서비스(아동 안전 보호 / 균형 급식·간식 / 등·하교 전후·야간·긴급 돌봄 / 체험활동 프로그램 연계 / 돌봄 상담·정보 제공·서비스 연계)":"초등학교 정규교육 외 시간에 방과 후 돌봄을 하는 곳으로 안전 보호와 급식과 간식과 긴급 돌봄 등을 합니다.","당연적용사업장의 18세 이상 60세 미만 근로자와 사용자":"당연적용사업장에서 일하는 18세 이상 60세 미만 근로자와 사용자는 사업장가입자가 됩니다.","대기기간은 실업의 신고일부터 7일간은 대기기간으로 보아 구직급여를 지급하지 않는다(14일은 오답), 건설일용근로자는 신고일부터 지급":"실업 신고일부터 7일은 대기기간으로 급여를 주지 않으며 14일이 아니고 건설일용근로자는 신고일부터 지급합니다.","대상 시설 예는 사회복지관 / 아동양육시설 / 장애인 지역사회재활시설 / 부자가족복지시설 등":"최저기준을 마련해야 하는 시설로 사회복지관과 아동양육시설과 지역사회재활시설과 부자가족복지시설이 있습니다.","대상은 지원대상자와 그 부양의무자(배우자와 1촌 직계혈족 및 그 배우자)":"부양의무자 범위는 배우자와 1촌 직계혈족 및 그 배우자이고 이들도 조사 대상에 들어갑니다.","대지급금 독촉은 납부기한이 지난 날부터 6개월 이내 기간을 정해 독촉장 발급 → 지방세 체납처분의 예에 따라 징수":"납부기한이 지난 날부터 6개월 이내 독촉장을 내고 지방세 체납처분의 예에 따라 징수합니다.","대지급은 급여비용의 일부를 기금에서 부담하는 경우 나머지 비용(보건복지부장관이 정한 금액)은 수급권자 또는 부양의무자의 신청으로 기금에서 대지급할 수 있다":"대지급은 일부 급여비용을 기금에서 부담할 때 나머지를 신청에 따라 기금에서 먼저 내주는 제도입니다.","대통령령 / 조례 / 일반적으로 승인된 국제법규 / 규칙이 모두 해당한다":"사회복지법의 성문법원에는 대통령령과 조례와 규칙과 국제법규가 모두 들어갑니다.","대통령령에 따라 시·도지사의 허가(보건복지부장관 허가·시·도지사 인가 아님)":"사회복지법인의 설립은 시·도지사의 허가를 받아야 하며 보건복지부장관 허가나 인가가 아닙니다.","대통령령으로 정하는 중요한 사항을 변경할 때도 같다":"중요한 사항을 바꿀 때에도 처음 수립할 때와 똑같은 심의 절차를 따릅니다.","대통령은 법률에서 구체적으로 범위를 정하여 위임받은 사항과 법률을 집행하기 위하여 필요한 사항에 관하여 대통령령을 발할 수 있다":"법률이 위임한 사항과 법률을 집행하는 데 필요한 사항에 대해 대통령령을 만들 수 있습니다.","대통령이 기간 내에 공포나 재의 요구를 하지 않아도 확정":"대통령이 기한 안에 공포도 재의 요구도 하지 않으면 법률안은 그대로 확정됩니다.","대표이사를 포함한 이사 7명 이상과 감사 2명 이상":"이사는 대표이사를 포함해 7명 이상이고 감사는 2명 이상이어야 합니다.","대한민국이 외국과 사회보장협정을 맺은 경우 국민연금의 가입 보험료 납부 급여 수급 요건 급여액 산정 급여 지급 등에 관하여 협정이 정하는 바에 따른다":"협정을 맺은 나라와는 국민연금의 가입과 보험료와 급여 수급 등에 관해 협정의 내용이 일반 규정보다 우선합니다.","둘 이상의 시설을 하나로 설치하거나 하나의 시설에서 둘 이상의 사회복지사업을 통합 수행할 수 있다":"둘 이상의 시설을 하나로 설치하거나 한 시설에서 여러 사회복지사업을 함께 할 수 있습니다.","등급 등 변경은 수급자는 장기요양등급·급여의 종류 또는 내용을 변경하려면 공단에 변경신청을 하여야 한다":"등급이나 급여 내용을 바꾸고 싶은 수급자는 공단에 변경신청을 해야 합니다.","등급은 1급·2급이고 정신건강·의료·학교 영역은 정신건강사회복지사·의료사회복지사·학교사회복지사 자격을 부여할 수 있다":"사회복지사는 1급과 2급으로 나뉘고 정신건강·의료·학교 영역의 사회복지사 자격도 줄 수 있습니다.","등급판정 기간은 신청서 제출일부터 30일 이내에 완료, 정밀조사 필요 등 부득이한 경우 30일 이내 연장 가능":"등급판정은 신청서를 낸 날부터 30일 이내에 끝내며 부득이하면 30일 이내에서 연장할 수 있습니다.","등급판정위원회가 신청자격을 충족하고 6개월 이상 혼자 일상생활을 수행하기 어렵다고 인정하는 경우 등급판정기준에 따라 수급자로 판정":"6개월 이상 혼자 생활이 어렵다고 인정되면 등급판정기준에 따라 수급자로 판정합니다.","등급판정위원회는 공단에 두고 시·군·구 단위로 설치, 위원장 포함 15인, 시장·군수·구청장이 추천한 위원 7인과 의사·한의사 1인 이상 포함, 임기 3년 한 차례 연임 가능, 과반수 출석 개의 출석위원 과반수 찬성 의결":"등급판정위원회는 시·군·구 단위로 두며 위원장 포함 15인 구성에 임기 3년으로 한 차례 연임할 수 있습니다.","등록장애인 수급권자에게 보조기기 급여 실시 가능":"등록장애인 수급권자에게는 보조기기 급여를 할 수 있습니다.","등록 취소는 사망 / 기준에 맞지 않게 됨 / 정당한 사유 없이 장애 진단 명령 불이행 / 취소 신청":"사망하거나 기준에 맞지 않게 되거나 정당한 사유 없이 진단 명령을 따르지 않거나 본인이 취소를 신청하면 등록이 취소됩니다.","매월 정기적으로 지급(반기 지급 아님)":"생계급여는 매월 정기적으로 지급하며 반기마다 주는 것이 아닙니다.","명령(시행령·시행규칙)은 법률의 하위":"시행령과 시행규칙으로 이루어진 명령은 법률보다 한 단계 아래입니다.","명령·규칙·처분의 위헌·위법 심사는 대법원이 최종 권한을 가진다":"명령과 규칙과 처분이 위헌이거나 위법인지를 최종 판단하는 기관은 대법원입니다.","모금창구는 언론기관을 모금창구로 지정하고 지정된 언론기관의 명의로 모금계좌를 개설할 수 있다":"언론기관을 모금창구로 지정하고 그 명의로 모금계좌를 열 수 있습니다.","모금회가 아닌 자는 사회복지공동모금 또는 유사 명칭을 사용하지 못한다":"모금회가 아닌 곳은 사회복지공동모금이나 비슷한 이름을 쓸 수 없습니다.","모금회의 사업은 사회복지공동모금사업 / 공동모금재원의 배분 / 운용·관리 / 조사·연구·홍보 및 교육·훈련 / 지회 운영 / 국제교류 및 협력증진 / 다른 기부금품 모집자와의 협력 / 그 밖에 목적 달성에 필요한 사업":"모금회는 모금사업과 재원 배분과 운용·관리와 조사·연구와 지회 운영과 국제교류 등을 합니다.","모두 충족: ① 기준기간 동안 피보험 단위기간 합산 180일 이상 ② 근로의 의사와 능력이 있음에도 취업하지 못한 상태 ③ 이직사유가 수급자격 제한 사유에 해당하지 않을 것 ④ 재취업을 위한 노력을 적극적으로 할 것 ⑤ 일용근로자였던 사람은 근로일수 요건(신청월 직전 달 초일부터 신청일까지 근로일 수가 총 일수의 3분의 1 미만 / 건설일용근로자는 신청일 이전 14일간 연속 근로내역 없음) ⑥ 일용근로자는 90일 이상 일용근로 요건":"구직급여는 피보험 단위기간 합산 180일 이상 등 네 가지 요건을 모두 갖춰야 받을 수 있습니다.","모든 국민은 양심의 자유를 가진다 (자유권. 사회적 기본권이 아님)":"양심의 자유는 국가의 간섭을 막는 자유권이며 사회적 기본권에 들지 않습니다.","모든 국민은 인간다운 생활을 할 권리를 가진다":"헌법이 인간다운 생활을 누릴 권리를 모든 국민에게 인정한다는 사회권의 근거 조항입니다.","모든 국민은 인간으로서의 존엄과 가치를 가지며 행복을 추구할 권리를 가진다":"모든 국민이 존엄한 존재로 대우받고 행복을 추구할 수 있다는 헌법상 기본 권리 선언입니다.","모든 국민은 혼인과 출산의 사회적 중요성을 인식하여야 한다, 국가와 지방자치단체는 출산·육아 환경 조성을 위해 모성·부성권 보호 및 태아 건강보장 등을 적극 지원":"모든 국민은 혼인과 출산의 사회적 중요성을 인식해야 하고 국가는 출산·육아 환경을 적극 지원합니다.","모든 국민의 인간다운 생활을 유지·증진하는 책임을 가진다":"국가와 지방자치단체는 모든 국민의 인간다운 생활을 유지하고 높이는 책임을 집니다.","모든 국민이 사회보장 관계 법령에서 정하는 바에 따라 사회보장급여를 받을 권리":"사회보장수급권은 모든 국민이 관계 법령에 따라 사회보장급여를 받을 수 있는 권리입니다.","모 또는 부는 아동인 자녀를 양육하는 ① 배우자와 사별·이혼하거나 유기된 자 ② 정신·신체 장애로 장기간 노동능력을 상실한 배우자를 가진 자 ③ 교정시설·치료감호시설 입소 배우자 또는 병역복무 중인 배우자를 가진 사람 ④ 미혼자(사실혼 관계에 있는 자는 제외) ⑤ 그에 준하는 자로 성평등가족부령 정하는 자":"모 또는 부는 아동을 양육하는 사람으로 사별·이혼·유기된 사람과 배우자의 노동능력 상실이나 수용 등 사유가 있는 사람입니다.","모자가족은 모가 세대주(세대원을 사실상 부양하는 자 포함)인 가족 / 부자가족은 부가 세대주인 가족 / 한부모가족은 모자가족 또는 부자가족":"모자가족은 모가 세대주인 가족, 부자가족은 부가 세대주인 가족이고 한부모가족은 이 둘을 아우릅니다.","모자복지법(1989) → 한부모가족지원법의 전신":"1989년 모자복지법은 오늘날 한부모가족지원법의 앞 단계 법률입니다.","목적 / 명칭 / 주된 사무소의 소재지 / 사업의 종류 / 자산 및 회계에 관한 사항 / 임원의 임면 등에 관한 사항 / 회의에 관한 사항 / 수익사업이 있는 경우 그에 관한 사항 / 정관의 변경에 관한 사항 / 존립시기와 해산 사유를 정한 경우 그 시기·사유 및 남은 재산의 처리방법 / 공고 및 공고방법":"정관에는 목적과 명칭과 사무소와 사업과 회계와 임원과 해산 사유 등 필수 기재 사항이 법에 정해져 있습니다.","목적에 따라 국가·지방자치단체·민간부문 간에 합리적으로 조정":"비용 부담은 목적에 맞게 국가와 지방자치단체와 민간 사이에 합리적으로 나눕니다.","미성년자 / 피성년후견인 또는 피한정후견인 / 파산선고를 받고 복권되지 아니한 사람 / 법원 판결로 자격 상실·정지 / 금고 이상 실형 집행 종료·면제 후 3년 미경과 / 금고 이상 집행유예 기간 중 / 사회복지사업 관련 범죄 등(벌금 100만원 이상 확정 후 5년, 집행유예 확정 후 7년, 징역형 집행 종료 후 7년) / 성폭력·아동청소년 성범죄 10년 / 아동학대관련범죄 / 해임명령으로 해임된 날부터 5년 / 설립허가 취소 법인의 임원이었던 사람 5년 / 시설의 장에서 해임된 날부터 5년 / 폐쇄명령 후 3년 / 사회복지분야 6급 이상 공무원 퇴직 3년 미경과":"임원 결격사유에는 미성년자와 후견 개시를 받은 사람과 파산 후 복권되지 않은 사람과 일정한 범죄 전력자 등이 있습니다.","미지급 급여는 수급권자 사망 시 배우자·자녀·부모·손자녀·조부모·형제자매 순으로 청구하고 사망한 날부터 5년 이내 청구":"못 받은 급여는 배우자와 자녀와 부모 등의 순서로 청구하고 사망한 날부터 5년 이내에 해야 합니다.","미지급 기초연금은 수급자 사망 시 생계를 같이한 부양의무자(배우자와 직계혈족 및 그 배우자)가 청구":"수급자가 사망했을 때 못 받은 연금은 생계를 같이한 부양의무자가 청구할 수 있습니다.","미혼 한부모가 5세 이하 아동을 양육하거나 34세 이하의 모 또는 부가 아동을 양육하면 추가 급여를 실시하여야 한다":"미혼 한부모가 5세 이하 아동을 기르거나 34세 이하의 모 또는 부가 아동을 기르면 추가 급여를 반드시 줍니다.","민간기관·단체와의 연계 지원은 대한적십자사 사회복지공동모금회 등과의 연계 지원 / 상담·정보제공 그 밖의 지원":"대한적십자사나 사회복지공동모금회 같은 민간기관과 이어 주는 연계 지원과 상담 및 정보제공이 있습니다.","민법 중 사단법인 규정 준용":"교육훈련기관에는 민법 중 사단법인 규정을 준용합니다.","반납금은 반환일시금을 받은 자가 다시 가입자가 되면 지급받은 반환일시금에 이자를 더한 금액을 공단에 낼 수 있고 납부하면 그에 상응하는 기간을 가입기간에 넣어 계산":"반환일시금을 받은 사람이 다시 가입하면 이자를 더해 공단에 반납하고 그만큼의 기간을 가입기간에 넣을 수 있습니다.","반환명령: 급여 변경·정지·중지로 과잉지급분이 생기면 즉시 반환을 명하여야 한다, 이미 소비했거나 부득이한 사유가 있으면 면제할 수 있다":"급여가 바뀌어 과잉지급이 생기면 곧바로 반환을 명하지만 이미 소비했거나 부득이하면 면제할 수 있습니다.","반환일시금 수급권 소멸은 다시 가입자가 된 때 / 노령연금 수급권 취득 / 장애연금 수급권 취득 / 유족이 유족연금 수급권 취득":"다시 가입자가 되거나 노령·장애·유족연금 수급권을 얻으면 반환일시금 수급권이 사라집니다.","반환일시금 지급 사유는 가입기간 10년 미만인 자가 60세가 된 때 / 가입자 또는 가입자였던 자가 사망한 때(유족연금이 지급되는 경우 제외) / 국적을 상실하거나 국외로 이주한 때, 액수는 납부한 연금보험료(사업장가입자는 사용자 부담금 포함)에 이자를 더한 금액":"10년 미만 가입자가 60세가 되거나 사망하거나 국적을 잃거나 국외로 이주하면 낸 보험료를 되돌려 주는 일시금입니다.","발굴조사는 보장기관의 장이 지원대상자에 대한 발굴조사를 분기마다 정기적으로 실시(긴급복지지원법 제7조의2에 따른 발굴조사를 실시한 경우 제외)":"발굴조사는 분기마다 정기적으로 하고 긴급복지지원법에 따른 발굴조사를 했다면 제외합니다.","발굴체계 운영 실태를 정기적으로 점검하고 개선방안을 수립":"발굴체계가 제대로 돌아가는지 정기적으로 살피고 고칠 방법을 마련합니다.","방문요양은 장기요양요원이 가정 등을 방문해 신체활동 및 가사활동 등을 지원 / 방문목욕은 목욕설비를 갖춘 장비로 방문해 목욕 제공 / 방문간호는 간호사 등이 방문간호지시서에 따라 간호 진료 보조 요양 상담 구강위생 등 제공":"방문요양은 신체와 가사 지원, 방문목욕은 목욕 제공, 방문간호는 간호사 등이 지시서에 따라 하는 간호를 말합니다.","배분기준은 매년 8월 31일까지 다음 회계연도 배분기준을 정하여 공고(배분대상 / 배분한도액 / 배분신청기간·제출 장소 / 배분심사기준 / 과부족 시 조정방법 / 제출 서류 / 그 밖의 사항), 긴급 시 별도 기준으로 지원 가능":"매년 8월 31일까지 다음 회계연도 배분기준을 정해 공고하며 배분대상과 한도액과 신청기간 등을 담습니다.","배분 절차는 배분신청서는 해당 회계연도에만 유효 → 배분분과실행위원회가 배분금액·순위·시기 심의 → 배분계획 수립(분기별 균형 배분) → 배분 종료일부터 3개월 이내 1개 이상 전국 일간신문에 결과 공고":"배분신청서는 해당 회계연도에만 유효하고 분과실행위원회가 금액·순위·시기를 심의해 분기별 균형 배분 계획을 세웁니다.","배우자 남편 아내에는 사실상의 혼인관계에 있는 자를 포함한다":"이 법에서 배우자와 남편과 아내에는 혼인신고가 없어도 사실상의 혼인관계에 있는 사람이 포함됩니다.","범위는 약제 외에는 비급여대상으로 정한 것을 제외한 일체, 약제는 보건복지부장관이 요양급여대상으로 결정·고시한 것":"약제를 뺀 요양급여는 비급여로 정한 것 외 모두 대상이고 약제는 장관이 대상으로 고시한 것만 해당합니다.","법률은 특별한 규정이 없는 한 공포한 날로부터 20일을 경과함으로써 효력을 발생한다(7일 아님)":"법률은 부칙 등 특별한 규정이 없으면 공포일로부터 20일이 지나야 효력이 생기며 7일이 아닙니다.","법률이 헌법에 위반되는지는 법원의 제청으로 헌법재판소가 심판한다":"법률이 헌법에 어긋나는지는 법원이 제청하면 헌법재판소가 심판합니다.","법인 대표이사와 시설의 장은 후원금 수입·지출 내용을 공개하여야 한다":"후원금을 투명하게 관리하도록 법인과 시설의 책임자에게 수입과 지출의 공개 의무가 있습니다.","법인·시설에 종사하는 사회복지사는 정기적으로 인권에 관한 내용이 포함된 보수교육을 받아야 한다":"시설에 종사하는 사회복지사는 인권 내용이 담긴 보수교육을 정기적으로 받아야 합니다.","법인·시설 운영자는 시설에 근무할 종사자를 채용할 수 있다":"운영자는 시설에서 일할 종사자를 채용할 수 있습니다.","변경은 소득·재산상황·근로능력 등이 변동되면 직권 또는 신청으로 변경하고 서면으로 이유를 알림":"소득과 재산이나 근로능력이 바뀌면 직권이나 신청으로 급여를 바꾸고 서면으로 이유를 알립니다.","별표 1은 30세 미만 120~240일 / 30세 이상 50세 미만 120~270일 / 50세 이상 및 장애인 120~270일 (피보험기간 1년 미만 120일 → 10년 이상 최대)":"연령과 피보험기간에 따라 소정급여일수는 120일에서 최대 270일까지 커집니다.","보건복지부 시·도 시·군·구에 각각 둔다":"의료급여심의위원회는 보건복지부와 시·도와 시·군·구에 각각 둡니다.","보건복지부장관 또는 소관 중앙행정기관의 장이 급여 종류별 수급자 선정기준과 최저보장수준을 결정하고, 매년 8월 1일까지 중앙생활보장위원회 심의·의결을 거쳐 다음 연도 기준을 공표":"수급자 선정기준과 최저보장수준은 매년 8월 1일까지 위원회 심의를 거쳐 다음 연도 기준으로 공표합니다.","보건복지부장관 및 관계 중앙행정기관의 장이 기본계획에 따라 소관 주요 시책의 시행계획을 매년 수립·시행":"보건복지부장관과 관계 중앙행정기관의 장이 기본계획에 따라 해마다 시책의 시행계획을 세워 실행합니다.","보건복지부장관은 공무원과 사회복지사업 종사자의 자질 향상을 위해 인권교육 등 지도와 훈련을 할 수 있다":"보건복지부장관은 공무원과 종사자의 자질을 높이려고 인권교육 등 지도와 훈련을 할 수 있습니다.","보건복지부장관은 급여 업무에 공통 적용되는 기준을 마련할 수 있다":"급여 업무를 통일하려고 보건복지부장관이 모든 기관에 쓰일 공통 기준을 만들 권한이 있습니다.","보건복지부장관은 발굴체계의 운영 실태를 매년 정기적으로 점검하고 개선방안을 마련":"보건복지부장관은 발굴체계가 잘 운영되는지 해마다 점검하고 개선 방안을 마련합니다.","보건복지부장관은 사회서비스 품질기준 마련·평가·개선을 위한 전담기구를 설치할 수 있다":"보건복지부장관은 사회서비스 품질을 정하고 평가하고 개선하는 전담기구를 둘 수 있습니다.","보건복지부장관은 자격을 취소하거나 1년의 범위에서 정지시킬 수 있다":"자격 처분은 취소와 정지가 있으며 정지는 길어야 1년까지만 가능합니다.","보건복지부장관은 평가기관을 설치·운영하거나 평가의 전부 또는 일부를 관계 기관·단체에 위탁할 수 있다(위탁 금지 아님)":"보건복지부장관은 평가기관을 직접 운영하거나 평가를 관계 기관에 맡기는 위탁도 할 수 있습니다.","보건복지부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립":"사회보장 기본계획은 보건복지부장관이 관계 기관과 협의하여 5년마다 수립합니다.","보건복지부장관이 사회복지에 관한 전문지식과 기술을 가진 사람에게 발급할 수 있다(시·도지사 아님)":"사회복지사 자격증은 보건복지부장관이 전문지식과 기술을 가진 사람에게 발급하고 시·도지사가 발급하지 않습니다.","보건복지부장관이 상담·정보제공·연계서비스를 위한 담당기구를 설치·운영할 수 있다":"장관은 상담과 정보제공과 연계서비스를 맡을 담당기구를 만들어 운영할 수 있습니다.","보건복지부장관이 설치·운영할 수 있다":"행정데이터 분석센터는 보건복지부장관이 설치하고 운영할 수 있습니다.","보건복지부장관이 장기간 대규모 예산이 투입되는 사업 등 대통령령으로 정하는 제도에 대해 실시할 수 있고, 결과를 사회보장위원회에 보고":"오랜 기간 큰 예산이 들어가는 제도를 대상으로 평가를 하고 결과를 위원회에 보고합니다.","보건복지부장관이 중앙생활보장위원회 심의·의결을 거쳐 고시하는 국민 가구소득의 중위값":"중위값은 평균이 아니라 가구소득을 줄 세웠을 때 한가운데 값이며 위원회 심의 후 고시합니다.","보건의료서비스는 국민의 건강을 보호·증진하기 위해 보건의료인이 하는 모든 활동":"보건의료서비스는 국민의 건강을 지키고 늘리기 위해 보건의료인이 하는 모든 활동입니다.","보궐위원의 임기는 전임자 임기의 남은 기간":"중간에 채워진 보궐위원은 앞 사람 임기의 남은 기간만 일합니다.","보장기관과 관계 기관·법인·단체·시설은 지역사회 내 지원대상자 발굴과 가정·지역공동체의 자발적 협조를 위해 노력":"보장기관과 관련 기관과 단체는 지역에서 지원대상자를 찾고 가정과 지역공동체의 자발적 협조를 이끌려고 노력합니다.","보장기관은 수급권자의 거주지를 관할하는 시·도지사(특별시장·광역시장·도지사)와 시장·군수·구청장, 주거가 일정하지 않으면 실제 거주지 관할 시장·군수·구청장(출생지 아님)":"보장기관은 거주지를 관할하는 시·도지사와 시장·군수·구청장이고 주거가 일정치 않으면 실제 거주지 관할이며 출생지는 아닙니다.","보장기관은 조사·결정·실시 업무를 위해 사회복지 전담공무원을 배치하여야 하고 자활급여 업무 담당자는 따로 배치":"보장기관은 업무를 위해 사회복지 전담공무원을 두어야 하고 자활급여 담당자는 따로 배치합니다.","보장기관의 업무담당자가 지원대상자 누락 방지를 위해 직권으로 신청할 수 있다":"보장기관의 담당자는 지원대상자가 빠지지 않도록 직권으로 신청할 수 있습니다.","보장기관의 장은 수급자에 대한 급여의 적정성을 확인하기 위해 수급자격 조사 사항을 조사할 수 있다":"보장기관의 장은 급여가 알맞게 지급되는지 보기 위해 수급자격 조사 사항을 다시 조사할 수 있습니다.","보장기관의 장은 신청을 받으면 사회보장 요구(요구 사항 / 건강상태·가구 구성 등 생활실태 / 필요한 급여)를 조사하여야 한다":"신청을 받으면 사회보장 요구, 곧 요구 사항과 생활 실태와 필요한 급여를 조사해야 합니다.","보장기관의 장은 신청을 받은 날부터 10일 이내 결정·통지":"보장기관의 장은 이의신청을 받으면 10일 이내에 결정해서 통지해야 합니다.","보장기관의 장이 위기가구(관계 기관 공유 정보와 자료 처리 결과 위기상황으로 판단한 가구 / 자살자·자살시도자가 발생한 가구)를 발굴하기 위해 노력하고 지원":"보장기관의 장은 위기상황이 있는 가구와 자살 시도가 있었던 가구를 찾아 지원하려고 노력합니다.","보장기관이 사회보장기본법 제3조제1호에 따라 제공하는 현금·현물·서비스 및 그 이용권":"보장기관이 사회보장기본법에 따라 제공하는 현금과 현물과 서비스와 그 이용권을 사회보장급여라 합니다.","보장기관이 사회복지법인 사회적협동조합 등 비영리법인·단체를 신청받아 지정":"보장기관이 사회복지법인이나 사회적협동조합 같은 비영리법인을 신청받아 지역자활센터로 지정합니다.","보장비용은 보장업무 인건비·사무비 / 생활보장위원회 운영비 / 급여 실시 비용 / 그 밖의 비용":"보장비용에는 보장업무의 인건비와 사무비, 위원회 운영비, 급여 실시 비용 등이 있습니다.","보험급여 8가지는 ① 요양급여 ② 휴업급여 ③ 장해급여 ④ 간병급여 ⑤ 유족급여 ⑥ 상병보상연금 ⑦ 장례비 ⑧ 직업재활급여 (예방·재활급여와 실업급여는 보험급여가 아님)":"산재보험급여는 요양과 휴업과 장해와 간병과 유족과 상병보상연금과 장례비와 직업재활급여 여덟 가지입니다.","보험급여는 수급권자의 청구에 따라 지급한다":"산재보험급여도 수급권자가 청구해야 지급합니다.","보험급여 지급 제한은 요양 지시 위반으로 상태 악화·치유 방해 / 장해보상연금·진폐보상연금 수급권자가 재판정 전 고의로 장해 상태를 악화":"요양 지시를 어겨 상태가 나빠지거나 연금 수급자가 고의로 장해를 악화시키면 급여 지급이 제한됩니다.","보험료 경감 대상은 섬·벽지·농어촌 거주자 / 65세 이상 / 등록장애인 / 국가유공자 / 휴직자 / 생활이 어려운 사람 등":"섬·벽지·농어촌 거주자와 65세 이상과 등록장애인과 국가유공자와 휴직자와 생활이 어려운 사람 등은 보험료를 줄여 줍니다.","보험료 면제는 직장가입자가 급여정지 사유(국외 체류 1개월 이상 등 현역병 수용)에 해당하면 면제, 지역가입자는 세대 보험료 산정에서 그 가입자의 소득과 재산 제외":"직장가입자가 급여정지 사유에 해당하면 보험료를 면제받고 지역가입자는 세대 보험료 산정에서 그 사람의 소득과 재산을 뺍니다.","보험료 체납(보수 외 소득월액보험료 또는 세대단위 보험료)이 대통령령 기간 이상이면 완납 시까지 급여를 하지 않을 수 있다":"보험료를 일정 기간 이상 체납하면 모두 낼 때까지 급여를 하지 않을 수 있습니다.","보험사업은 고용노동부장관이 관장하고 보험연도는 정부의 회계연도에 따른다":"사업을 맡는 부처는 고용노동부이고 회계 처리도 정부 회계연도에 맞춰 이루어집니다.","보험은 고용노동부장관이 관장한다":"고용보험 사업을 관장하는 사람은 고용노동부장관입니다.","보험자는 국민건강보험공단(건강보험심사평가원 아님), 공단은 법인이며 주된 사무소 소재지에서 설립등기로 성립":"건강보험의 보험자는 건강보험공단이고 심사평가원이 아니며 공단은 설립등기로 성립하는 법인입니다.","보호가 필요한 아동을 발견하고 양육환경을 개선하기 위해 이용할 수 있는 자료와 정보에는 요양급여 실시 기록 / 영유아건강검진 실시 기록 / 학교생활기록 정보 / 단전 가구정보 등이 포함된다":"보호가 필요한 아동을 찾을 때 요양급여 기록과 영유아건강검진 기록과 학교생활기록 등의 자료를 활용할 수 있습니다.","보호기간 연장은 18세에 달한 보호대상아동이 연장 의사가 있으면 25세에 달할 때까지 연장하여야 한다, 대학 이하 재학 중이거나 직업 교육·훈련 중이면 추가 연장 가능":"18세가 된 아동이 원하면 25세에 이를 때까지 보호기간을 연장해야 하고 재학 중이면 추가 연장할 수 있습니다.","보호대상아동은 보호자가 없거나 보호자로부터 이탈된 아동 또는 보호자가 학대하는 등 양육하기에 적당하지 않거나 양육 능력이 없는 경우의 아동":"보호자가 없거나 보호자에게서 떨어졌거나 학대 등으로 양육에 적당하지 않은 경우의 아동입니다.","보호시설 보호비용 지원의 방법·절차와 전담의료기관 지정 등은 성평등가족부령 및 시장·군수·구청장의 지정 사항(기출 시점에는 여성가족부령)":"보호비용 지원의 방법과 전담의료기관 지정 등은 성평등가족부령과 단체장의 지정 사항으로 정합니다.","보호시설 업무는 숙식 제공 / 상담·치료 / 의료지원 / 수사·재판 지원 / 법률구조 협조 / 자립자활교육과 취업정보 / 다른 법률에 따른 위탁 사항":"보호시설은 숙식과 상담·치료와 의료지원과 수사·재판 지원과 자립교육과 취업정보 등을 제공합니다.","보호시설은 국가·지방자치단체가 설치·운영하고 사회복지법인과 그 밖의 비영리법인은 시장·군수·구청장의 인가를 받아 설치·운영할 수 있다":"보호시설은 공공이 설치하고 사회복지법인 등은 시장·군수·구청장의 인가를 받아 설치합니다.","보호시설 종류는 단기보호시설(6개월 범위, 3개월씩 두 차례 연장 가능) / 장기보호시설(2년 범위 자립을 위한 주거편의) / 외국인보호시설(2년) / 장애인보호시설(2년)":"단기보호시설은 6개월 범위에서 3개월씩 두 차례 연장하고 장기·외국인·장애인보호시설은 2년 범위입니다.","보호의무자는 민법에 따른 후견인 또는 부양의무자, 다음은 보호의무자가 될 수 없다 ① 피성년후견인 및 피한정후견인 ② 해당 정신질환자를 상대로 소송 중이거나 소송한 사실이 있는 사람과 그 배우자 ③ 미성년자 ④ 행방불명자 ⑤ 그 밖에 의무를 이행할 수 없는 사람, 순위는 후견인 → 부양의무자 (파산선고 후 복권되지 않은 사람은 현행 결격 목록에 없음)":"보호의무자는 후견인이나 부양의무자이며 피성년후견인이나 해당 환자와 소송 중인 사람 등은 될 수 없습니다.","보호의무자의 의무는 적절한 치료·요양과 사회적응 훈련을 받도록 노력 / 입원 시 본인 의사 존중과 퇴원 협조 / 자해·타해 유의와 재산권 보호 / 유기 금지":"보호의무자는 치료와 사회적응 훈련을 받도록 노력하고 입원 시 본인 의사를 존중하며 자해·타해를 유의하고 유기해서는 안 됩니다.","보호자는 부양의무자 또는 업무·고용 등의 관계로 사실상 노인을 보호하는 자":"법적 부양의무자와 별개로 일을 맡아 노인을 실제로 돌보는 사람도 보호자에 들어갑니다.","보호자는 친권자 후견인 아동을 보호·양육·교육하거나 그러한 의무가 있는 자 또는 업무·고용 등의 관계로 사실상 아동을 보호·감독하는 자":"보호자는 친권자와 후견인뿐 아니라 업무나 고용 관계로 사실상 아동을 보호·감독하는 사람까지 포함합니다.","보호조치(②~⑥) 중인 보호대상아동의 양육상황을 매년 점검(분기별·3년마다 아님)":"보호조치 중인 보호대상아동의 양육상황은 매년 점검하며 분기마다나 3년마다 하는 것이 아닙니다.","보호조치 ③~⑥을 하기 전에 상담 건강검진 심리검사 가정환경 조사를 실시하고 아동이 충분히 이해하도록 설명, 아동의 의사를 존중하고 보호자 의견을 들어야 한다(아동학대행위자 등은 제외)":"위탁이나 시설 입소 같은 조치 전에는 상담과 검진과 조사를 하고 아동의 의사를 존중하며 보호자 의견도 듣습니다.","복지업무 종사자는 인권을 존중하고 차별 없이 최대로 봉사하여야 한다":"복지업무 종사자는 인권을 존중하고 차별 없이 최선을 다해 봉사해야 합니다.","복지 자금의 대여는 사업 자금 / 아동교육비 / 의료비 / 주택자금 / 그 밖에 대통령령 자금(대여할 수 있음), 아동양육비는 대여가 아니라 지급 대상":"사업 자금과 아동교육비와 의료비와 주택자금 등은 빌려줄 수 있고 아동양육비는 대여가 아니라 지급 대상입니다.","복지조치 비용을 부담한 지방자치단체의 장이나 시설 운영자는 수혜자 본인 또는 부양의무자로부터 비용의 전부 또는 일부를 징수할 수 있다":"비용을 낸 지방자치단체의 장이나 시설 운영자는 수혜자나 부양의무자에게서 그 비용의 일부나 전부를 징수할 수 있습니다.","본인과 배우자가 모두 수급권자이면 각각의 기초연금액에서 100분의 20을 감액":"부부가 모두 수급권자이면 각자의 기초연금액에서 100분의 20씩 줄여 지급합니다.","본인부담금은 급여를 받는 자는 비용의 일부를 본인이 부담(특별현금급여 제외), 의료급여법상 기초생활 의료급여 수급자는 부담하지 않음, 월 한도액 초과 급여 / 인정서와 다르게 선택한 차액 / 급여 범위 밖 급여는 전부 본인 부담, 의료급여 수급권자·저소득자 등은 100분의 60 범위 감경":"급여를 받는 사람은 비용의 일부를 내지만 특별현금급여와 의료급여 수급자는 부담하지 않습니다.","본인일부부담금은 요양급여를 받는 자가 대통령령에 따라 비용의 일부 부담, 연간 본인부담상한액 초과 금액은 공단이 부담":"환자가 비용의 일부를 내고 연간 본인부담상한액을 넘는 금액은 공단이 부담합니다.","부가급여는 임신·출산 진료비 / 장제비 / 상병수당 / 그 밖의 급여를 대통령령에 따라 실시할 수 있다":"부가급여에는 임신·출산 진료비와 장제비와 상병수당과 그 밖의 급여가 있습니다.","부담 능력이 있는 국민의 사회서비스 비용은 수익자 부담 원칙, 국가와 지방자치단체가 일부 부담할 수 있다":"능력 있는 사람의 사회서비스 비용은 이용자가 내는 것이 원칙이고 일부는 공공이 지원할 수 있습니다.","부당이득 징수는 공단은 부정 등으로 급여를 받은 자 급여비용을 받은 자에게 징수, 구상권은 제3자의 행위로 급여한 경우 비용 한도에서 손해배상 청구":"공단은 부정하게 급여를 받은 사람에게서 징수하고 제3자의 행위로 급여했다면 비용 한도에서 손해배상을 청구합니다.","부당이득 징수는 속임수 등 부당한 방법으로 급여를 받은 사람 / 의료급여기관 등, 독촉 시 10일 이상 15일 이내 납부기한":"속임수로 급여를 받은 사람이나 의료급여기관에서 부당이득을 징수하며 독촉 시 납부기한은 10일 이상 15일 이내로 줍니다.","부당이득 징수는 속임수 등 부당한 방법으로 보험급여를 받은 사람 요양기관 준요양기관 보조기기 판매업자에게 징수":"속임수로 보험급여를 받은 사람과 부당하게 청구한 요양기관과 보조기기 판매업자에게서 이득을 거두어들입니다.","부득이한 경우 의료급여증명서로 갈음":"증을 발급하기 어려운 부득이한 때에는 의료급여증명서로 대신할 수 있습니다.","부모 사망·장애·장기복역·이혼 등으로 부양받을 수 없는 아동과 그 아동을 양육하는 조부 또는 조모 / 대한민국 국적 아동을 양육하는 외국인 모 또는 부로 대통령령이 정하는 사람도 지원대상자":"부양받을 수 없는 아동과 이를 기르는 조부모나 외국인 모 또는 부로 대통령령이 정한 사람도 지원대상자가 될 수 있습니다.","부양가족연금액은 배우자 연 15만원 / 19세 미만이거나 장애상태인 자녀 연 10만원 / 60세 이상이거나 장애상태인 부모 연 10만원 (수급권자에 의하여 생계를 유지하는 자)":"부양가족연금은 생계를 유지하는 배우자 연 15만원과 19세 미만이거나 장애상태인 자녀 연 10만원과 60세 이상 부모 연 10만원입니다.","부양가족연금 제외는 연금 수급권자·퇴직연금등수급권자·직역연금 유족연금 수급권자, 2명 이상 수급권자의 계산 대상이 될 수 없다, 사망 / 생계유지 종료 / 이혼 / 자녀 양자·파양 / 자녀 19세 도달 / 장애 해소 시 제외":"연금 수급권자 등과 두 사람 이상의 계산 대상이 될 수 없는 사람을 제외하며 사망이나 이혼, 자녀 19세 도달이면 끝납니다.","부양능력 없음으로 보는 경우는 기준 중위소득 수준을 고려해 대통령령으로 정하는 소득·재산 기준 미만 / 직계존속 또는 중증장애인인 직계비속을 자신의 주거에서 부양하는 경우로 고시하는 경우 / 질병 교육 가구 특성 등으로 부양능력이 없다고 보건복지부장관이 정하는 경우":"부양능력이 없다고 보는 경우는 소득과 재산이 기준에 못 미치거나 직계존속을 자기 집에서 부양하는 등의 사유가 있을 때입니다.","부양을 받을 수 없는 것으로 보는 경우는 병역법에 따라 징집·소집된 경우 / 해외이주자 / 교도소·구치소·치료감호시설 등 수용 중 / 실종선고 절차 진행 중 / 보장시설에서 급여를 받고 있는 경우 / 가출·행방불명 신고 후 1개월이 지났거나 시장·군수·구청장이 확인한 경우 / 부양 기피·거부 / 그 밖에 보건복지부장관이 정하는 경우":"부양받을 수 없는 경우는 징집과 해외이주와 수용 중과 실종선고 중과 보장시설 급여 중과 가출 신고 1개월 경과 등입니다.","부양의무자는 배우자(사실상 혼인관계 포함)와 직계비속 및 그 배우자(사실상 혼인관계 포함)":"노인복지법의 부양의무자는 배우자와 직계비속 및 그 배우자이며 사실상 혼인관계도 포함합니다.","부양의무자는 수급권자의 1촌 직계혈족 및 그 배우자":"의료급여법의 부양의무자도 수급권자의 1촌 직계혈족과 그 배우자입니다.","부양의무자의 부양과 다른 법령에 따른 보호가 이 법의 급여에 우선한다(타법 우선)":"부양의무자의 부양과 다른 법령의 보호가 이 법의 급여보다 먼저입니다.","부정수급 실태조사는 보건복지부장관이 3년마다 실시하고 결과를 공개":"보건복지부장관이 3년마다 부정수급 실태를 조사하고 그 결과를 공개합니다.","부정수급자는 1년 이하 징역 또는 1천만원 이하 벌금":"부정한 방법으로 급여를 받은 사람은 1년 이하의 징역이나 1천만원 이하의 벌금을 받습니다.","부정행위 시 거짓·부정한 방법으로 받거나 받으려 한 사람에게는 그 날부터의 구직급여 지급 안 함, 반환 명령에 더해 2배 이하(사업주와 공모 시 5배 이하) 추가 징수":"거짓으로 받으면 그 날부터의 구직급여를 주지 않고 반환을 명하며 추가로 2배 이하, 사업주와 공모하면 5배 이하를 징수합니다.","분과실행위원회는 기획·홍보·모금·배분 분과를 두고 위원장 포함 20명 이내(모금·배분분과는 각각 20명 이상), 위원 임기 2년이며 배분분과실행위원회 위원은 한 차례만 연임 가능":"기획·홍보·모금·배분 분과를 두고 위원장 포함 20명 이내이며 모금·배분분과는 각각 20명 이상이고 위원 임기는 2년입니다.","분할연금 수급권은 취득 후 배우자였던 자에게 생긴 사유로 노령연금 수급권이 소멸·정지되어도 영향을 받지 않는다":"분할연금 수급권은 취득한 뒤 전 배우자의 사유로 노령연금이 소멸하거나 정지되어도 영향을 받지 않습니다.","분할연금 수급권자에게 노령연금 수급권이 발생하면 합산 지급":"분할연금을 받던 사람에게 본인의 노령연금 수급권이 생기면 두 가지를 합쳐서 줍니다.","분할연금은 혼인 기간(별거 가출 등 실질 혼인관계가 없던 기간 제외)이 5년 이상인 자가 ① 배우자와 이혼 ② 배우자였던 자가 노령연금 수급권자 ③ 60세가 된 요건을 모두 갖추면 받는다, 분할연금액은 노령연금액 중 혼인 기간에 해당하는 연금액을 균등하게 나눈 금액, 요건을 갖춘 때부터 5년 이내 청구":"혼인 기간이 5년 이상인 사람이 이혼하고 배우자였던 사람이 노령연금을 받으며 60세가 되면 연금을 나누어 받습니다.","불지급은 초진일이 가입 대상 제외 기간이거나 국외이주·국적상실 기간 중인 경우 / 반환일시금을 지급받은 경우":"초진일이 가입 대상 제외 기간이거나 국외이주·국적상실 기간 중이거나 반환일시금을 받은 경우에는 장애연금을 주지 않습니다.","비밀 엄수는 긴급전화센터·상담소·보호시설의 장이나 이를 보조하는 자 또는 그 직에 있었던 자는 직무상 알게 된 비밀을 누설하여서는 아니 된다":"긴급전화센터와 상담소와 보호시설의 장과 보조자는 직무상 알게 된 비밀을 누설하면 안 되고 그만둔 뒤에도 같습니다.","비용 분담은 국가가 100분의 40 이상 100분의 90 이하 범위에서 대통령령으로 정하는 비율을 부담하고 나머지는 시·도와 시·군·구가 분담":"국가는 100분의 40 이상 100분의 90 이하 범위에서 정한 비율을 내고 나머지는 시·도와 시·군·구가 나눕니다.","비용은 건강진단·상담·입소 조치 소요비용과 노인복지시설 설치·운영 비용은 국가 또는 지방자치단체가 부담하며 시설 운영 비용은 보조할 수 있다":"건강진단과 상담과 입소 조치 비용과 복지시설 설치·운영 비용은 공공이 부담하며 운영 비용은 보조할 수 있습니다.","비용 징수: 부양능력 있는 부양의무자가 있으면 생활보장위원회 심의·의결을 거쳐 비용의 전부 또는 일부를 징수할 수 있다, 부정수급자로부터도 징수할 수 있다":"부양능력이 있는 부양의무자와 부정수급자에게서 비용을 징수할 수 있습니다.","비용 청구는 요양기관이 심사평가원에 심사청구 → 심사평가원이 심사 후 공단과 요양기관에 통보 → 공단이 지급, 적정성 평가 결과에 따라 가산·감액":"요양기관이 심사평가원에 청구해 심사를 받고 공단이 지급하며 적정성 평가에 따라 가산하거나 감액합니다.","사고 선박·항공기 탑승자 등 생사를 알 수 없는 사람은 대통령령에 따라 사망한 것으로 추정":"선박이나 항공기 사고로 생사를 알 수 없는 사람은 대통령령에 따라 사망한 것으로 추정합니다.","사망일시금은 가입자 노령연금 수급권자 장애등급 3급 이상 장애연금 수급권자가 사망했는데 유족연금 대상 유족이 없으면 배우자·자녀·부모·손자녀·조부모·형제자매·4촌 이내 방계혈족 순으로 지급, 가입자 사망 시 반환일시금 상당액(최종 기준소득월액 평균의 4배 한도)":"유족연금을 받을 사람이 없을 때 배우자와 자녀 등 순서대로 지급하며 4촌 이내 방계혈족까지 넓어집니다.","사무국은 보건복지부에 둔다(국무총리실·고용노동부 아님)":"위원회의 사무를 맡는 사무국은 국무총리실이나 고용노동부가 아니라 보건복지부에 둡니다.","사실혼 배우자 및 자녀는 대한민국 국민과 사실혼 관계에서 출생한 자녀를 양육하는 다문화가족 구성원에게도 준용":"국민과 사실혼 관계에서 낳은 자녀를 기르는 다문화가족 구성원에게도 이 법을 같게 적용합니다.","사업계획 및 예산안은 회계연도 시작 1개월 전에 보건복지부장관에게 제출하고 결산서는 회계연도 종료 후 3개월 이내 제출(회계법인 감사보고서 첨부), 회계연도는 1월 1일부터 12월 31일":"사업계획과 예산안은 회계연도 시작 1개월 전에, 결산서는 종료 후 3개월 이내에 보건복지부장관에게 냅니다.","사업기밀을 경쟁관계에 있는 사업자에게 제공한 경우도 중대한 귀책사유(사업에 막대한 지장 초래 등) 해당":"사업기밀을 경쟁 사업자에게 넘긴 행위도 사업에 큰 지장을 주는 중대한 귀책사유에 포함됩니다.","사업 운영에 필요한 재산을 소유하여야 한다":"사회복지법인은 사업을 운영하는 데 필요한 재산을 가지고 있어야 합니다.","사업은 자활의욕 고취 교육 / 자활을 위한 정보제공 상담 직업교육 취업알선 / 생업을 위한 자금융자 알선 / 자영창업 지원 및 기술·경영 지도 / 자활기업의 설립·운영 지원 / 그 밖에 자활을 위한 사업":"센터 사업은 의욕을 북돋는 교육과 정보제공과 직업교육과 취업알선과 창업 지원과 자활기업 지원 등입니다.","사업은 지역 특성과 복지욕구를 고려한 서비스 제공 / 사례관리 / 복지자원 관리·주민교육·조직화 / 그 밖에 지역사회가 요청하는 사업":"사회복지관은 지역 특성에 맞는 서비스와 사례관리와 자원 관리, 주민교육, 조직화 사업을 합니다.","사업자금 융자는 센터 사업이 아니라 자활기업 지원(제18조)":"사업자금 융자는 센터가 하는 사업이 아니라 자활기업을 지원하는 내용입니다.","사업장가입자가 아닌 18세 이상 60세 미만":"지역가입자는 사업장가입자가 아닌 18세 이상 60세 미만 국민입니다.","사업장가입자 자격 취득은 당연적용사업장에 고용된 때 또는 사용자가 된 때 / 사업장이 당연적용사업장이 된 때, 지역가입자는 사업장가입자 자격 상실 시 등, 임의가입자는 신청 수리일":"사업장가입자는 당연적용사업장에 고용되거나 사용자가 된 때 자격을 얻고 임의가입자는 신청 수리일입니다.","사용자가 기여금을 공제하고 보험료를 내지 않으면 그 기간의 2분의 1을 근로자 가입기간으로 산입(1개월 미만은 1개월)":"사용자가 공제만 하고 내지 않았다면 근로자 책임이 아니어서 그 기간의 2분의 1을 가입기간으로 산입하고 1개월 미만은 1개월로 합니다.","사용자는 근로자가 속한 사업장의 사업주 / 공무원이 소속된 기관의 장으로서 대통령령이 정하는 사람 / 사립학교를 설립·운영하는 자":"사용자는 사업주와 공무원 소속 기관의 장과 사립학교 설립·운영자를 말합니다.","사회보장급여로 지급된 금품과 이를 받을 권리는 압류하지 못한다":"급여로 받은 금품과 그것을 받을 권리는 압류하지 못합니다.","사회보장급여의 이용·제공 및 수급권자 발굴에 관한 법률(2014 제정)":"수급권자 발굴을 다루는 사회보장급여법은 2014년에 제정된 법입니다.","사회보장기본법상 수급권은 양도·담보 제공·압류가 금지되고 제한·정지는 원칙적으로 불가하며 필요한 최소한의 범위에서만 가능":"수급권은 넘기거나 담보로 쓰거나 압류할 수 없고 제한과 정지는 원칙적으로 안 되며 필요한 최소 범위에서만 됩니다.","사회보장수급권은 관계 법령에서 정하는 바에 따라 양도·담보 제공을 할 수 없고 압류할 수 없다":"수급권은 다른 사람에게 넘기거나 담보로 쓸 수 없고 압류도 금지됩니다.","사회보장수급권은 제한되거나 정지될 수 없다":"수급권은 원칙적으로 제한하거나 정지할 수 없습니다.","사회보장에 관한 국민의 권리와 국가·지방자치단체의 책임을 정하고, 사회보장정책의 수립·추진과 관련 제도의 기본 사항을 규정해 국민의 복지증진에 이바지함":"이 법은 국민의 권리와 국가와 지방자치단체의 책임을 정하고 기본 사항을 규정해 복지증진에 이바지하려는 목적입니다.","사회보장에 관한 주요 시책을 심의·조정하기 위해 국무총리 소속으로 사회보장위원회를 둔다":"국무총리 소속의 사회보장위원회가 주요 시책을 심의하고 조정합니다.","사회보장에 관한 책임과 역할을 합리적으로 분담하여야 한다":"국가와 지방자치단체가 사회보장의 책임과 역할을 합리적으로 나누어야 합니다.","사회보장위원회와 국무회의의 심의를 거쳐 확정한다":"사회보장 기본계획은 사회보장위원회와 국무회의의 심의를 거쳐 확정됩니다.","사회보장정보시스템의 운영·지원을 위해 설립한 법인":"한국사회보장정보원은 사회보장정보시스템을 운영하고 지원하려고 세운 법인입니다.","사회보장 학식경험자와 비영리민간단체 추천자가 2분의 1 이상":"위원 중 사회보장 전문가와 비영리민간단체 추천자가 2분의 1 이상이어야 합니다.","사회보험 비용은 사용자·피용자·자영업자가 부담함을 원칙으로 하되 관계 법령에 따라 국가가 일부 부담할 수 있다":"사회보험 비용은 사용자와 근로자와 자영업자가 부담하는 것이 원칙이고 국가도 일부를 낼 수 있습니다.","사회보험은 국가의 책임, 공공부조와 사회서비스는 국가와 지방자치단체의 책임으로 시행":"사회보험은 국가가 책임지고 공공부조와 사회서비스는 국가와 지방자치단체가 함께 책임집니다.","사회복지공동모금은 사회복지사업이나 그 밖의 사회복지활동 지원에 필요한 재원을 조성하기 위해 이 법에 따라 기부금품을 모집하는 것":"공동모금은 사회복지사업 등에 필요한 재원을 마련하기 위해 이 법에 따라 기부금품을 모집하는 것입니다.","사회복지공동모금회(모금회)를 두며 사회복지법인으로 한다, 정관을 작성하여 보건복지부장관의 인가를 받아 등기함으로써 설립된다(허가 아님)":"모금회는 사회복지법인이며 정관을 작성해 보건복지부장관의 인가를 받아 등기함으로써 설립되고 허가를 받는 것이 아닙니다.","사회복지공동모금회법(1997) / 국민의료보험법(1997) / 국민건강보험법(1999)":"1997년에는 사회복지공동모금회법과 국민의료보험법이, 1999년에는 국민건강보험법이 제정되었습니다.","사회복지법인 등 비영리법인·단체에 위탁할 수 있다":"자원봉사활동 지원 업무는 사회복지법인 같은 비영리법인이나 단체에 위탁할 수 있습니다.","사회복지법인·시설 운영자는 사회복지사를 종사자로 채용하고 임면 사항을 시·도지사 또는 시장·군수·구청장에게 보고하여야 한다(대통령령으로 정하는 시설 제외)":"운영자는 사회복지사를 종사자로 채용하고 임면 사항을 시·도지사 또는 시장·군수·구청장에게 보고해야 합니다.","사회복지법인은 사회복지사업을 할 목적으로 설립된 법인":"사업 주체가 되는 단체를 가리키며 시설과 달리 법인격을 가진 조직입니다.","사회복지사가 아니면 사회복지사 또는 유사한 명칭을 사용하지 못한다":"자격이 없는 사람은 사회복지사나 그와 비슷한 명칭을 쓸 수 없습니다.","사회복지사업을 하는 자는 필요한 경우 주민의 복지 욕구를 조사할 수 있다":"사회복지사업을 하는 사람은 필요할 때 주민의 복지 욕구를 조사할 수 있습니다.","사회복지사 임면 보고 위반은 300만원 이하 벌금":"사회복지사 임면을 보고하지 않으면 300만원 이하의 벌금입니다.","사회복지서비스는 사회보장기본법 제3조제4호의 사회서비스 중 사회복지사업을 통한 서비스(사회서비스가 사회복지서비스보다 넓은 개념)":"사회복지서비스는 사회서비스 가운데 사회복지사업으로 하는 서비스여서 사회서비스가 더 넓은 개념입니다.","사회복지시설은 사회복지사업을 할 목적으로 설치된 시설":"사업을 하는 장소나 건물에 해당하며 법인과 달리 설치된 시설을 말합니다.","사회복지시설의 설치·운영 및 관리는 주민의 복지증진과 관련된 지방자치단체의 사무이다":"시설을 설치하고 운영하며 관리하는 일은 주민 복지와 관련된 지방자치단체의 고유 사무입니다.","사회복지시설의 장과 종사자 / 장애인활동지원기관 / 의료인·의료기관의 장 / 의료기사 / 응급구조사 / 소방 구조대·구급대원 / 경찰공무원 / 자치경찰공무원 / 정신건강복지센터 종사자 / 어린이집 원장 등 보육교직원 / 유아교육법상 교직원·강사 / 초·중등교육법상 교직원·전문상담교사 / 학원 운영자·강사·직원과 교습소 교습자 / 성폭력피해상담소·보호시설 종사자 / 성매매 지원시설·상담소 종사자 / 가정폭력 상담소·보호시설 종사자 / 건강가정지원센터·가족센터 종사자 / 장기요양기관의 장과 종사자 / 보건소 방문간호 종사자 / 다문화가족지원센터 종사자 / 행정리 이장·통장 / 공동주택 관리주체 / 자살예방센터 종사자 / 전기·수도·도시가스 검침·안전점검 종사자 / 국민연금공단·건강보험공단·근로복지공단의 민원·상담 종사자 / 우편집배원":"신고의무자는 시설 종사자와 의료인, 경찰, 교직원, 상담소 종사자, 검침원, 집배원 등 매우 넓은 직군입니다.","사회복지에 관한 조사·연구 및 정책 건의는 사회복지협의회의 업무(협회 아님)":"조사와 연구와 정책 건의는 협회가 아니라 사회복지협의회가 하는 일입니다.","사회복지의 날은 매년 9월 7일, 그날부터 1주간을 사회복지주간으로 한다":"해마다 9월 7일이 기념일이고 그날부터 1주간을 복지주간으로 정한 기간 규정입니다.","사회복지 자원봉사활동은 사회복지사업법 제9조에 따라 국가가 홍보·교육, 프로그램 개발·보급, 재해 대비 시책을 실시하여야 한다":"사회복지사업법의 해당 조문이 국가에 자원봉사 홍보와 교육과 프로그램 개발과 재해 대비 의무를 지웁니다.","사회복지 전담공무원은 수급권자 동의를 구해 직권 신청 가능":"사회복지 전담공무원은 수급권자의 동의를 얻어 직권으로 신청할 수 있습니다.","사회복지전담공무원은 시·도, 시·군·구, 읍·면·동 또는 전담기구에 둘 수 있고 사회복지사 자격을 가진 사람":"전담공무원은 시·도부터 읍·면·동까지 배치될 수 있고 사회복지사 자격이 임용 요건입니다.","사회적 위험을 보험의 방식으로 대처하여 국민의 건강과 소득을 보장하는 제도":"여러 사람이 위험을 보험으로 나누어 지고 가입자의 건강과 소득을 지켜 주는 제도입니다.","사후조사는 시장·군수·구청장이 지원받은 대상자의 소득·재산 등을 조사해 지원이 적정한지 확인":"지원이 끝난 뒤 대상자의 소득과 재산을 조사해 지원이 알맞았는지 따져 봅니다.","사후조사로 얻은 정보·자료를 목적 외 사용·제공하면 3년 이하 징역 또는 3천만원 이하 벌금":"사후조사에서 얻은 정보를 목적 외로 쓰거나 제공하면 3년 이하 징역이나 3천만원 이하 벌금입니다.","산업재해보상보험및예방기금은 고용노동부장관이 설치, 재원은 보험료 기금운용 수익금 적립금 결산상 잉여금 출연금·기부금 차입금 등":"기금은 고용노동부장관이 설치하고 보험료와 운용수익과 적립금 등으로 마련합니다.","산업재해보상보험및예방심의위원회는 고용노동부에 두며 근로자·사용자·공익 대표를 같은 수로 구성":"이 위원회는 고용노동부에 두고 근로자와 사용자와 공익 대표를 같은 수로 구성합니다.","상급종합병원 요양은 응급환자 등 부득이한 경우 외에는 상급종합병원에서 요양할 필요가 있다는 의학적 소견이 필요":"응급환자 등이 아니면 상급종합병원에서 요양하려면 의학적 소견이 있어야 합니다.","상담소는 국가·지방자치단체가 설치·운영하고 그 외의 자는 시장·군수·구청장에게 신고, 업무는 신고·상담 / 가족 상담 / 긴급 피해자 임시 보호·인도 / 법적 자문 협조 요청 / 경찰 인도 피해자 임시 보호 / 예방 교육·홍보 / 조사·연구":"상담소는 공공이 설치하고 그 밖의 사람은 신고하며 신고·상담과 임시 보호와 법적 자문 협조를 합니다.","상담·입소 조치는 65세 이상의 자 또는 보호자 상담·지도 / 거택 보호가 곤란한 자의 노인주거복지시설·재가노인복지시설 입소 / 항상 보호가 필요하고 경제적 이유로 곤란한 자의 노인의료복지시설 입소, 65세 미만도 노쇠현상이 현저하면 가능":"65세 이상의 상담과 지도를 하고 거택 보호가 어려운 사람은 주거복지시설이나 재가노인복지시설에 입소시킵니다.","상병보상연금은 요양을 시작한 지 2년이 지난 날 이후 ① 부상·질병이 치유되지 않은 상태 ② 중증요양상태등급 기준 해당 ③ 요양으로 취업하지 못한 상태가 계속되면 휴업급여 대신 지급":"요양을 시작한 지 2년이 지나도 치유되지 않고 중증요양상태이며 취업하지 못하면 휴업급여 대신 상병보상연금을 받습니다.","상실은 사망 / 국적 상실·국외 이주 / 사용관계 종료 / 60세가 된 때 → 해당일의 다음 날 상실, 가입 대상 제외자가 된 때는 해당일 상실":"사망이나 국적 상실 등으로 자격을 잃고 60세가 되면 그날 다음 날, 제외자가 되면 그날 상실합니다.","상환은 무이자로 거주지 관할 시장·군수·구청장에게 하고 상환받은 금액은 의료급여기금에 납입한다(시·도지사 아님)":"대지급금은 이자 없이 거주지 관할 시장·군수·구청장에게 갚으며 시·도지사에게 갚는 것이 아닙니다.","생계곤란 등 위기상황에 처한 사람을 신속하게 지원해 위기상황에서 벗어나 건강하고 인간다운 생활을 하게 함":"긴급복지지원법은 생계곤란 같은 위기에 빠진 사람을 빨리 도와 건강하고 인간다운 생활로 돌아오게 하려는 법입니다.","생계급여 / 주거급여 / 의료급여 / 교육급여 / 해산급여 / 장제급여 / 자활급여":"급여의 종류는 생계와 주거와 의료와 교육과 해산과 장제와 자활급여 일곱 가지입니다.","생계급여·의료급여 수급자는 희망에 따라 제외":"생계급여나 의료급여를 받는 사람은 희망하면 가입에서 제외할 수 있습니다.","생계를 같이 하던 유족은 주민등록상 세대를 같이하고 동거한 유족이 대표적이며 학업·취업 등으로 주민등록을 달리하거나 동거하지 않아도 생계를 유지했다면 포함될 수 있다(판단 기준은 대통령령)":"같은 세대에서 함께 산 유족이 대표적이지만 주민등록이 다르거나 따로 살아도 생계를 유지했다면 포함될 수 있습니다.","생계지원과 주거지원은 각각 기준 중위소득의 100분의 40을 한도로 한다":"두 지원은 지급액에 상한이 있어 기준 중위소득의 100분의 40을 넘는 금액은 줄 수 없습니다.","생애주기에 걸쳐 보편적으로 충족되어야 하는 기본욕구와 특정 사회위험으로 생기는 특수욕구를 동시에 고려해 소득·서비스를 보장하는 맞춤형 사회보장제도":"평생사회안전망은 모든 생애에 필요한 기본욕구와 특정 위험에서 생기는 특수욕구를 함께 고려해 소득과 서비스를 보장합니다.","생활보장위원회는 생활보장사업의 기획·조사·실시 등을 심의·의결하기 위해 보건복지부와 시·도 및 시·군·구에 각각 둔다(심의·의결기구, 자문기구 아님)":"생활보장위원회는 보건복지부와 시·도와 시·군·구에 각각 두는 심의·의결기구이고 자문기구가 아닙니다.","생활이 어려운 사람에게 필요한 급여를 실시해 최저생활을 보장하고 자활을 돕는 것":"급여로 최저생활을 지켜 주는 것에 더해 스스로 일어서게 돕는 자활까지가 법의 목적입니다.","서비스 제공은 현물 제공이 원칙이다(현금·현물 병행 아님)":"서비스는 현물로 제공하는 것이 원칙이어서 현금과 현물을 함께 주는 것이 원칙이 아닙니다.","서비스 증진 / 인권침해 예방·차별 금지·인권 옹호 / 사회복지서비스와 보건의료서비스 연계 / 시설의 균형 설치 노력 / 인권교육 강화 / 긴급한 인권침해 신속 대응체계 / 시설 거주자 희망을 반영한 지역사회보호체계 서비스 / 서비스 정보 제공 / 권리침해 사람을 위한 간이·신속한 구제조치":"국가와 지방자치단체는 서비스를 늘리고 인권침해를 막으며 시설을 균형 있게 설치하고 신속한 구제조치를 마련해야 합니다.","서비스 최저기준은 보건복지부장관이 마련하여야 하며 시설 운영자는 이 기준 이상을 유지하여야 한다(적정기준 아님)":"최저기준은 보건복지부장관이 마련하고 시설 운영자는 그 이상을 유지해야 하며 적정기준이 아닙니다.","선별급여는 경제성·치료효과성 등이 불확실해 추가 근거가 필요하거나 경제성이 낮아도 건강회복에 잠재적 이득이 있는 경우 예비적 요양급여로 지정, 보건복지부장관이 주기적으로 적합성 평가":"효과나 경제성이 불확실하거나 낮아도 이득이 있는 항목을 예비적으로 급여로 지정하고 장관이 주기적으로 적합성을 평가합니다.","선정기준은 소득인정액이 중앙생활보장위원회 심의·의결로 정하는 금액 이하(기준 중위소득의 100분의 30 이상)이고 부양의무자가 없거나 부양능력이 없거나 부양을 받을 수 없는 사람 (2023 기출에서 100분의 50은 오답)":"생계급여 선정기준은 소득인정액이 정해진 금액 이하인 사람이며 100분의 50은 틀린 숫자입니다.","설명은 노력 의무, 통지는 관계 법령에 따라 알려야 한다":"설명은 노력해야 하는 의무이고 통지는 관계 법령에 따라 반드시 알려야 하는 점이 서로 다릅니다.","설치는 국가 또는 지방자치단체는 설치할 수 있고 그 외의 자는 관할 시장·군수·구청장에게 신고한 후 설치":"국가나 지방자치단체는 아동복지시설을 설치할 수 있고 그 밖의 사람은 시장·군수·구청장에게 신고한 뒤 설치합니다.","설치·운영 사항은 보건복지부령":"센터의 설치와 운영에 관한 사항은 보건복지부령으로 정합니다.","센터 지원은 설립·운영 비용 또는 사업수행 비용의 전부 또는 일부 / 국유·공유 재산 무상임대 / 보장기관 사업의 우선 위탁":"센터에는 설립과 운영 비용의 지원과 국유·공유 재산 무상임대와 보장기관 사업의 우선 위탁이 이루어집니다.","소관 중앙행정기관의 장이 3년마다 기초생활보장 기본계획을 수립해 보건복지부장관에게 제출하고, 보건복지부장관이 이를 종합해 종합계획을 수립해 중앙생활보장위원회 심의를 받는다":"소관 중앙행정기관의 장이 3년마다 기본계획을 세워 내면 보건복지부장관이 종합계획을 세워 중앙위원회 심의를 받습니다.","소득인정액 + 기초연금액이 선정기준액 이상이면 초과 금액 범위에서 일부 감액 가능":"소득인정액과 기초연금액의 합이 선정기준액을 넘으면 초과분 범위에서 일부를 줄일 수 있습니다.","소득인정액 등을 고려해 차등지급할 수 있다":"소득인정액 등을 고려해 수급자마다 지급액을 다르게 할 수 있습니다.","소득인정액은 본인 및 배우자의 소득평가액과 재산의 소득환산액을 합산한 금액":"기초연금의 소득인정액은 본인과 배우자의 소득평가액에 재산의 소득환산액을 더한 금액입니다.","소득·재산·근로능력 등이 변동되면 직권 또는 신청으로 종류·방법을 변경할 수 있다":"수급자의 소득이나 재산이나 근로능력이 달라지면 직권이나 신청으로 급여의 종류와 방법을 바꿀 수 있습니다.","소득평가액은 근로소득 사업소득 재산소득 이전소득을 합한 실제소득에서 장애·질병·양육 등 가구 특성 지출요인 근로유인 요인 등을 감한 금액":"소득평가액은 실제소득에서 가구 특성에 따른 지출 요인과 근로유인 요인을 빼서 구합니다.","소멸시효 3년: 의료급여를 받을 권리 / 급여비용을 받을 권리 / 대지급금을 상환받을 권리, 급여비용 청구와 대지급금 납입 고지·독촉으로 중단":"의료급여 권리와 급여비용 청구권과 대지급금 상환권은 3년이 지나면 소멸하지만 청구나 독촉으로 시효가 중단됩니다.","소멸시효 3년은 지원금을 지급받거나 반환받을 권리 / 취업촉진 수당을 지급받거나 반환받을 권리 / 구직급여를 반환받을 권리 / 육아휴직 급여 등을 반환받을 권리":"지원금과 취업촉진 수당과 구직급여와 육아휴직 급여 등을 받거나 반환받을 권리는 3년이 지나면 소멸합니다.","소정급여일수는 대기기간이 끝난 다음 날부터 피보험기간과 연령에 따라 별표 1에서 정한 일수까지, 피보험기간은 이직 당시 적용 사업에서 고용된 기간이며 종전 적용 사업의 피보험자격 상실일부터 3년 이내 재취득하면 합산":"소정급여일수는 대기기간이 끝난 다음 날부터 피보험기간과 연령에 따라 별표 1에서 정한 일수까지입니다.","수급 권리 순위는 배우자 → 자녀 → 부모 → 손자녀 → 조부모 → 형제자매":"연금을 받을 순위는 배우자가 가장 앞이고 자녀와 부모와 손자녀와 조부모와 형제자매 순입니다.","수급권 보호는 보험급여를 받을 권리는 양도하거나 압류할 수 없다":"건강보험 급여를 받을 권리는 다른 사람에게 넘길 수 없고 압류도 안 됩니다.","수급권 보호는 보험급여를 받을 권리는 퇴직하여도 소멸하지 않는다, 양도·압류·담보 제공을 할 수 없다":"산재 급여를 받을 권리는 퇴직해도 사라지지 않고 넘기거나 압류하거나 담보로 쓸 수 없습니다.","수급권 보호는 양도·압류·담보 제공을 할 수 없다, 급여수급전용계좌 입금액도 압류 불가":"급여받을 권리는 넘기거나 압류하거나 담보로 쓸 수 없고 전용 계좌의 입금액도 압류가 안 됩니다.","수급권 보호는 장기요양급여를 받을 권리는 양도 압류 담보 제공할 수 없다":"장기요양급여를 받을 권리도 넘기거나 압류하거나 담보로 쓸 수 없습니다.","수급권 상실은 사망한 때 / 국적을 상실하거나 국외로 이주한 때 / 선정 요건에 해당하지 않게 된 때 (장기요양등급판정은 상실 사유 아님, 사망 추정은 지급 정지 사유)":"사망하거나 국적을 잃거나 국외로 이주하거나 선정 요건에 맞지 않게 되면 수급권을 잃고 장기요양등급 판정은 해당하지 않습니다.","수급권 소멸은 수급권자 사망 / 배우자인 수급권자 재혼 / 자녀·손자녀 파양 / 장애상태가 아닌 자녀가 25세 또는 손자녀가 19세가 된 때":"수급권자가 숨지거나 배우자가 재혼하거나 자녀가 25세, 손자녀가 19세가 되면 유족연금이 사라집니다.","수급권은 이 법에 따른 급여를 받을 권리 / 수급권자는 수급권을 가진 자 / 수급자는 급여를 받고 있는 자 (수급권자를 급여를 받을 권리라고 정의한 선지는 오답)":"수급권은 받을 권리 자체이고 수급권자는 그 권리를 가진 사람, 수급자는 실제 급여를 받는 사람입니다.","수급권자가 2명 이상일 때 그 중 1명을 대표자로 선임할 수 있다":"수급권자가 여럿이면 그중 한 명을 대표자로 뽑아 청구와 수령을 맡길 수 있습니다.","수급권자 권리구제 / 사각지대 발굴 / 부정·오류 관리 / 과오지급액 환수 등 관리":"급여 관리체계에는 권리구제와 사각지대 발굴과 부정과 오류 관리와 과오지급액 환수가 들어갑니다.","수급권자는 65세 이상으로 소득인정액이 보건복지부장관이 고시하는 선정기준액 이하인 사람, 선정기준액은 65세 이상 중 기초연금 수급자가 100분의 70 수준이 되도록 정한다":"수급권자는 65세 이상이고 소득인정액이 선정기준액 이하인 사람이며 기준액은 수급자가 100분의 70 수준이 되도록 정합니다.","수급권자는 가입기간 10년 이상인 가입자 또는 가입자였던 자에게 60세(특수직종근로자 55세)부터 생존하는 동안 지급":"가입기간이 10년 이상이면 60세부터 살아 있는 동안 받으며 특수직종근로자는 55세부터입니다.","수급권자는 사회보장급여를 제공받을 권리를 가진 사람 / 수급자는 사회보장급여를 받고 있는 사람 / 지원대상자는 사회보장급여를 필요로 하는 사람 / 보장기관은 관계 법령에 따라 사회보장급여를 제공하는 국가기관과 지방자치단체":"수급권자는 받을 권리가 있는 사람, 수급자는 받고 있는 사람, 지원대상자는 필요로 하는 사람입니다.","수급권자는 이 법에 따라 의료급여를 받을 수 있는 자격을 가진 사람":"의료급여법의 수급권자는 이 법에 따라 의료급여를 받을 수 있는 자격이 있는 사람입니다.","수급권자는 이 법에 따른 급여를 받을 수 있는 자격을 가진 사람 / 수급자는 이 법에 따른 급여를 받는 사람 / 수급품은 수급자에게 지급하거나 대여하는 금전 또는 물품 / 보장기관은 이 법에 따른 급여를 실시하는 국가 또는 지방자치단체":"수급권자는 자격이 있는 사람, 수급자는 받는 사람, 수급품은 금전이나 물품, 보장기관은 급여를 실시하는 국가나 지방자치단체입니다.","수급권자에 대한 급여는 수급자의 필요에 따라 전부 또는 일부를 실시한다":"수급자의 필요에 따라 급여를 전부 또는 일부만 실시할 수 있습니다.","수급권자와 그 친족 그 밖의 관계인이 관할 시장·군수·구청장에게 신청":"신청권자는 수급권자 본인뿐 아니라 친족과 관계인까지 넓고 신청처는 관할 시장·군수·구청장입니다.","수급권자 요건은 가입자 또는 가입자였던 자가 질병·부상으로 장애가 있고 ① 초진일 당시 18세 이상이고 노령연금 지급 연령 미만 ② 가입대상기간의 3분의 1 이상 보험료 납부 / 초진일 5년 전부터 초진일까지 3년 이상 납부 / 초진일 당시 가입기간 10년 이상 중 하나":"장애연금은 초진일에 18세 이상이고 가입대상기간의 3분의 1 이상 보험료를 냈거나 최근 5년의 납부 요건을 채워야 받습니다.","수급권자의 1촌의 직계혈족 및 그 배우자(사망한 1촌 직계혈족의 배우자는 제외)":"부양의무자는 수급권자의 1촌 직계혈족과 그 배우자이며 사망한 1촌 직계혈족의 배우자는 제외합니다.","수급권자인 유족 순위(일시금 등)는 생계를 같이한 배우자·자녀·부모·손자녀·조부모 → 생계를 같이하지 않던 그들 또는 생계를 같이한 형제자매 → 형제자매, 같은 순위가 2명 이상이면 똑같이 나눔, 근로자가 유언으로 수급 유족을 지정하면 그에 따름":"유족급여 일시금 순위는 생계를 같이한 가까운 가족이 먼저이고 같이하지 않던 가족과 형제자매가 그다음입니다.","수급기간은 이직일의 다음 날부터 12개월 내에 소정급여일수를 한도로 지급, 임신·출산·육아 등 취업 불가 사유를 신고하면 최대 4년까지 가산":"수급기간은 이직일 다음 날부터 12개월 안이며 임신·출산·육아 등으로 취업이 어려우면 최대 4년까지 늘어납니다.","수급이력 등 개인정보는 기관의 장의 취급승인을 받은 담당자만 취급":"수급이력 같은 개인정보는 기관의 장에게 취급승인을 받은 담당자만 다룰 수 있습니다.","수급자가 소득·재산·근로능력 등을 활용해 최대한 노력하는 것을 전제로 이를 보충·발전시킨다(보충급여·근로능력 활용)":"수급자가 자기 능력을 최대한 활용하는 것을 전제로 부족한 부분을 보충하는 보충급여의 원칙입니다.","수급자격자가 실업한 상태에 있는 날 중 직업안정기관의 장으로부터 실업의 인정을 받은 날에 대해 지급, 실업신고일부터 1주~4주 범위에서 지정한 실업인정일에 출석해 재취업 노력을 신고":"구직급여는 실업 인정을 받은 날에 대해 지급하며 실업신고일부터 1주~4주 범위의 실업인정일에 출석해 재취업 노력을 신고합니다.","수급자격자는 근로자 사망 당시 생계를 같이 하던 유족(외국 거주 외국인 제외) 중 배우자 + 부모·조부모 각 60세 이상 / 자녀 25세 미만 / 손자녀 25세 미만 / 형제자매 19세 미만 또는 60세 이상 / 장애인으로서 고용노동부령 장애 정도 해당자, 사망 당시 태아였던 자녀가 출생하면 포함":"유족보상연금은 사망 당시 생계를 같이한 배우자와 60세 이상 부모·조부모와 25세 미만 자녀와 손자녀 등이 받을 수 있습니다.","수급자는 거주지역 세대구성 임대차 계약내용 등이 변동되면 지체 없이 관할 보장기관에 신고":"거주지역이나 세대구성이나 임대차 계약이 달라지면 수급자는 지체 없이 보장기관에 신고해야 합니다.","수급자 및 차상위자의 자활 촉진 사업 수행":"지역자활센터는 수급자와 차상위자가 스스로 일어서도록 자활을 촉진하는 사업을 합니다.","수급품과 받을 권리는 압류할 수 없고 급여수급계좌 예금 채권도 압류 불가":"수급품과 받을 권리와 급여수급계좌의 예금 채권은 압류할 수 없습니다.","수요 측정·목표·추진전략 / 지역사회보장지표 / 분야별 추진전략·연계협력 / 전달체계 / 사각지대 발굴·지원 / 재원 규모·조달 / 통계 수집·관리 / 부정수급 현황 및 방지대책 / 그 밖의 사항":"시·군·구 계획에는 수요 측정과 목표, 지표, 전달체계, 사각지대, 재원, 통계, 부정수급 방지대책이 들어갑니다.","수익사업은 설립 목적 수행에 지장 없는 범위에서 가능, 수익은 법인·시설 운영 외 목적에 사용 금지, 회계는 구분 처리":"수익사업은 설립 목적 수행에 지장이 없는 범위에서 할 수 있으며 수익은 법인과 시설 운영에만 쓰고 회계는 따로 처리합니다.","시·군·구 계획은 이해관계인 의견 청취 후 수립 → 지역사회보장협의체 심의 → 시·군·구 의회 보고 → 시·도지사에게 제출":"시·군·구 계획은 의견 청취와 협의체 심의와 의회 보고를 거쳐 시·도지사에게 제출합니다.","시·군·구 지원 목표·전략 / 지표 / 급여 이용·제공 기반 구축 / 시·군·구 급여 담당 인력의 양성·전문성 제고 방안 / 통계자료 / 부정수급 방지 지원":"시·도 계획에는 시·군·구 지원 목표와 급여 기반 구축과 담당 인력 양성과 통계와 부정수급 방지 지원이 들어갑니다.","시·군 및 자치구의 조례나 규칙은 시·도의 조례나 규칙을 위반해서는 아니 된다":"기초 지방자치단체의 조례나 규칙은 광역 단위인 시·도의 조례나 규칙에 어긋나선 안 됩니다.","시·도 계획은 시·도사회보장위원회 심의 → 시·도 의회 보고 → 보건복지부장관에게 제출(보건복지부장관은 사회보장위원회에 보고)":"시·도 계획은 시·도사회보장위원회 심의와 의회 보고를 거쳐 보건복지부장관에게 내고 장관은 위원회에 보고합니다.","시·도 및 시·군·구 생활보장위원회 위원장은 시·도지사 또는 시장·군수·구청장":"지역 생활보장위원회의 위원장은 시·도지사나 시장·군수·구청장이 맡습니다.","시·도에 설치한다(보건복지부에 설치하는 것이 아님)":"의료급여기금의 설치 주체는 시·도이며 보건복지부에 두는 것으로 알면 틀립니다.","시·도지사가 명령 불이행 / 회계부정·인권침해 등 불법행위 / 보고 지연·거짓 보고 / 제18조 위반 선임 / 겸직 금지 위반 / 직무집행 정지명령 불이행 / 그 밖의 법 위반 시":"시·도지사가 해임을 명할 수 있는 사유에는 명령 불이행과 회계부정과 거짓 보고와 겸직 금지 위반 등이 있습니다.","시·도지사가 시·도의 사회보장 증진을 위해 둔다":"시·도지사가 시·도의 사회보장을 늘리려고 시·도사회보장위원회를 둡니다.","시·도지사가 시정명령 또는 취소할 수 있다":"시·도지사는 법인에 시정명령을 내리거나 설립허가를 취소할 수 있습니다.","시·도지사는 10일 이내 송부, 보건복지부장관 등은 30일 이내 심사·결정하고 통지":"시·도지사는 10일 안에 송부하고 보건복지부장관 등은 30일 이내에 심사하고 결정해 통지합니다.","시·도지사는 30일 이내에 심사해 각하·기각하거나 처분을 변경·취소하거나 필요한 급여를 명하고 신청인과 시장·군수·구청장에게 서면 통지":"시·도지사는 30일 이내에 심사해 각하나 기각하거나 처분을 바꾸거나 취소하고 서면으로 알립니다.","시·도지사 및 시장·군수·구청장이 4년마다 수립하고 매년 연차별 시행계획을 수립":"지역사회보장계획은 4년마다 세우고 해마다 연차별 시행계획도 세웁니다.","시·도지사와 시장·군수·구청장이 관계 법령에 따라 사회보장에 관한 지역계획을 수립·시행하며 기본계획과 연계되어야 한다":"시·도지사와 시장·군수·구청장은 지역계획을 세우고 시행하며 이 계획은 기본계획과 이어져야 합니다.","시설 개선·사업정지(6개월 이내)·위탁취소·시설장 교체·폐쇄 명령은 설치기준 미달 / 법인 설립허가 취소 / 운영 불필요 / 아동학대행위 확인 / 거짓 경비 지원 / 정지기간 중 사업 / 법 위반":"설치기준 미달이나 학대 확인이나 거짓 경비 지원 등이 있으면 개선·사업정지·시설장 교체·폐쇄를 명할 수 있고 정지는 6개월 이내입니다.","시설 개선·사업정지·시설장 교체·폐쇄 명령은 장애인복지실시기관이 시설기준 미달 / 보고 거부 / 법인 설립허가 취소 / 회계 부정·인권침해 / 운영 불필요 / 성폭력·학대관련범죄 발생 / 법 위반 시":"시설기준에 못 미치거나 보고를 거부하거나 인권침해가 있으면 개선·정지·교체·폐쇄를 명할 수 있습니다.","시설급여는 장기요양기관에 장기간 입소한 수급자에게 신체활동 지원 및 심신기능 유지·향상 교육·훈련 등을 제공":"시설급여는 장기요양기관에 오래 입소한 수급자에게 신체활동 지원과 교육·훈련 등을 제공합니다.","시설 설치는 국가나 지방자치단체가 설치할 수 있고 그 외의 자는 시장·군수·구청장에게 신고, 청소년 한부모가 입소를 요청하면 우선 입소 조치, 시설 폐지·중단·재개는 미리 신고":"공공은 시설을 설치할 수 있고 그 밖의 사람은 단체장에게 신고하며 청소년 한부모가 요청하면 우선 입소시킵니다.","시설 설치는 국가와 지방자치단체는 설치 가능, 그 외의 자는 시설 소재지 관할 시장·군수·구청장에게 신고, 폐쇄명령 후 1년 미경과자는 신고 불가, 장애인 거주시설 정원은 30명 초과 불가(예외 있음)":"공공은 시설을 설치할 수 있고 그 밖의 사람은 시장·군수·구청장에게 신고하며 폐쇄명령 후 1년이 안 되면 신고할 수 없습니다.","시설 설치방해 / 자격증 대여·알선 / 무신고 시설 운영 / 비밀누설 등은 1년 이하 징역 또는 1천만원 이하 벌금":"시설 설치 방해와 자격증 대여와 무신고 운영과 비밀누설은 1년 이하의 징역이나 1천만원 이하의 벌금입니다.","시설 운영자는 운영을 일정 기간 중단하거나 다시 시작하거나 폐지하려면 시장·군수·구청장에게 신고하여야 한다":"운영을 잠시 멈추거나 다시 열거나 폐지하려면 시장·군수·구청장에게 신고해야 합니다.","시설 운영자는 화재 및 화재 외 안전사고로 인한 손해배상책임을 위해 책임보험 또는 한국사회복지공제회 책임공제에 가입하여야 한다":"시설 운영자는 화재와 그 밖의 안전사고로 인한 손해배상책임을 대비해 책임보험이나 공제에 가입해야 합니다.","시설의 장 결격은 임원 결격사유 등 해당자 / 해임명령으로 해임된 날부터 5년 미경과 / 6급 이상 사회복지분야 공무원 퇴직 3년 미경과":"시설의 장은 임원 결격자나 해임명령 후 5년이 안 된 사람이나 퇴직 3년이 안 된 6급 이상 공무원이 될 수 없습니다.","시설의 장은 상근하여야 한다(비상근 겸직 불가)":"시설의 장은 상근하는 사람이어야 하며 비상근으로 겸직할 수 없습니다.","시설의 장의 의무는 위탁을 정당한 사유 없이 거부 금지 / 최저기준 이상의 급여 / 성별·신앙·사회적 신분 등 차별 금지 / 자유로운 생활 보장 / 종교상의 행위 강제 금지":"시설의 장은 위탁을 정당한 이유 없이 거부할 수 없고 최저기준 이상으로 급여하며 차별과 종교 강요를 하지 않아야 합니다.","시설의 장이 보고할 사항은 회계 및 예산·결산 / 후원금 조성 및 집행 / 시설운영 관련 사건·사고":"시설의 장은 회계와 예산과 결산, 후원금과 사건·사고를 운영위원회에 보고합니다.","시설의 장이 시설 운영에 관한 사항을 심의하기 위해 두어야 한다(심의기구이고 의결기구 아님)":"운영위원회는 시설 운영을 심의하려고 시설의 장이 두는 심의기구이고 의결기구가 아닙니다.","시설의 장이 정기 및 수시 안전점검을 실시하고 결과를 시장·군수·구청장에게 제출한다(법인의 대표·시장이 실시하는 것 아님)":"안전점검은 시설의 장이 정기적이고 수시로 실시해 결과를 시장·군수·구청장에게 내며 법인 대표나 시장이 하는 것이 아닙니다.","시설 평가는 보건복지부장관과 시·도지사가 정기적으로 평가하고 결과를 공표하거나 감독·지원에 반영할 수 있다":"평가는 장관과 시·도지사 두 곳이 정기적으로 하고 결과는 공표하거나 감독과 지원에 활용합니다.","시설 폐쇄는 시설 기준 미달 / 수탁 거부 / 보고 거부 시 사업 정지·폐지 명령이나 폐쇄":"시설기준에 미달하거나 수탁을 거부하거나 보고를 거부하면 사업 정지나 폐지 명령 또는 폐쇄를 합니다.","시장·군수·구청장도 정당한 이유 없이 설치를 지연시키거나 제한하는 조치를 하여서는 아니 된다":"단체장도 정당한 이유 없이 시설 설치를 늦추거나 제한하는 조치를 해서는 안 됩니다.","시장·군수·구청장은 10일 이내 송부 시·도지사는 15일 이내 검토":"단체장은 10일 안에 서류를 보내고 시·도지사는 15일 안에 검토합니다.","시장·군수·구청장은 10일 이내 의견서와 관계 서류를 시·도지사에게 송부":"이의신청을 받은 단체장은 열흘 안에 자기 의견서와 서류를 시·도지사에게 넘깁니다.","시장·군수·구청장은 ① 고의 또는 중대한 과실로 인한 범죄행위에 원인이 있거나 고의로 사고를 일으킨 경우 ② 정당한 이유 없이 법이나 진료 지시에 따르지 않은 경우 의료급여를 하지 아니한다, 보건복지부장관이 필요하다고 인정하면 예외":"고의나 중대한 과실로 범죄를 저지르거나 진료 지시에 따르지 않은 경우 의료급여를 하지 않으나 필요하면 예외입니다.","시장·군수·구청장은 국가·지방자치단체 외의 자가 서비스를 제공하게 하는 경우 보호대상자에게 사회복지서비스 이용권을 지급할 수 있다":"국가와 지방자치단체가 아닌 자가 서비스를 제공할 때 시장·군수·구청장이 보호대상자에게 이용권을 줄 수 있습니다.","시장·군수·구청장은 보완·개수·보수를 요구할 수 있다":"점검 결과가 미흡하면 시장·군수·구청장은 보완과 개수와 보수를 요구할 수 있습니다.","시장·군수·구청장은 신고 내용이 이 법에 적합하면 수리하여야 한다":"신고 내용이 법에 맞으면 시장·군수·구청장은 반드시 수리해야 합니다.","시장·군수·구청장은 신청자에게 급여 신청의 철회나 포기를 유도하는 행위를 하여서는 아니 된다":"시장·군수·구청장은 신청자가 신청을 철회하거나 포기하도록 유도해서는 안 됩니다.","시장·군수·구청장은 지원대상자 발굴 활동 비용을 지원할 수 있다":"민간의 발굴 활동에는 기초 지방자치단체장이 필요한 경비를 대 줄 수 있습니다.","시장·군수·구청장이 매년 연간조사계획을 세워 관할 수급자를 매년 1회 이상 정기 조사, 보건복지부장관이 정하는 사항은 분기마다 조사":"연간조사계획에 따라 수급자를 매년 1회 이상 정기 조사하고 장관이 정하는 사항은 분기마다 조사합니다.","시장·군수·구청장이 시·군·구에 둔다":"지역사회보장협의체는 시장·군수·구청장이 시·군·구에 설치합니다.","시장·군수·구청장이 조사 결과를 고려해 수급자 가구별로 수립하고 그에 따라 급여를 실시, 자활여건 변화와 급여 실시 결과를 정기적으로 평가해 변경 가능":"자활지원계획은 시장·군수·구청장이 가구별로 세워 급여에 반영하고 정기적으로 평가해 바꿀 수 있습니다.","시장·군수·구청장이 지역자활센터 직업안정기관 사회복지시설의 장 등과 상시 협의체계를 구축하여야 한다":"자활 기관들이 흩어져 일하지 않도록 단체장이 상시 협의 틀을 만들어 두어야 합니다.","시정 요구 후 15일이 지나도 응하지 않은 경우에 한함(중대한 비리는 시정요구 없이 가능)":"시정 요구를 한 뒤 15일이 지나도 따르지 않을 때가 원칙이고 중대한 비리는 시정 요구 없이도 해임할 수 있습니다.","시행계획과 전년도 추진실적은 관계 중앙행정기관의 장이 매년 보건복지부장관에게 제출하고, 보건복지부장관이 이를 종합해 성과를 평가한 뒤 사회보장위원회에 보고":"중앙행정기관은 시행계획과 지난해 실적을 보건복지부장관에게 내고 장관이 종합 평가해 위원회에 보고합니다.","시행계획은 매년 수립·시행하고 추진실적을 매년 평가하며 국회 소관 상임위원회에 보고":"시행계획은 매년 세워 실행하고 추진 실적을 평가해 국회 상임위원회에 보고합니다.","시행령은 대통령령이고 시행규칙은 총리령 또는 부령이다":"시행령은 대통령이 내는 대통령령이고 시행규칙은 총리령이나 부령의 형식입니다.","시효 3년은 보험료·연체금·가산금 징수권 / 과오납금 환급권 / 보험급여를 받을 권리 / 보험급여 비용을 받을 권리 / 과다 본인일부부담금 반환권 / 근로복지공단의 권리":"보험료 징수권과 환급권과 급여를 받을 권리와 급여 비용 청구권 등은 3년이 지나면 소멸합니다.","시효는 보험급여를 받을 권리 3년 / 장해급여 유족급여 장례비 진폐보상연금 진폐유족연금은 5년, 산재보험 의료기관·약국·보험가입자·국민건강보험공단 등의 권리도 3년":"급여를 받을 권리는 3년이 지나면 소멸하지만 장해급여와 유족급여와 장례비와 진폐연금은 5년입니다.","시효는 보험료 등 징수권 3년 / 급여를 받을 권리와 과오납금 반환 및 환수금 환수 5년 / 가입기간 10년 미만 60세 반환일시금 10년":"보험료 징수권은 3년, 급여를 받을 권리와 과오납금 반환은 5년, 60세 반환일시금은 10년이 지나면 소멸합니다.","시효는 환수금을 환수할 권리와 기초연금 수급권자의 권리는 5년간 행사하지 않으면 소멸 (3년 아님)":"환수금과 수급권자의 권리는 5년간 행사하지 않으면 소멸하며 3년이 아닙니다.","신고는 지급 정지 사유 소멸 / 수급권 상실 사유 / 소득·재산 변동 / 결혼·이혼·배우자 사망 / 그 밖의 사유를 30일 이내에 신고":"지급 정지나 상실 사유와 소득·재산 변동과 결혼·이혼·배우자 사망 등은 30일 이내에 신고해야 합니다.","신고를 고의로 회피하거나 부정한 방법으로 받은 경우 환수할 수 있고(임의) 수급권이 없는 자에게 제공했거나 과잉지급분이 있으면 반환을 명하여야 한다(필요적. 소비한 경우 등 면제 가능)":"부정한 방법으로 받은 급여는 환수할 수 있지만, 수급권이 없는 사람에게 준 급여는 반환을 명해야 합니다.","신고 불가 사유는 폐쇄명령 후 3년 미경과 / 임원 결격사유(제19조제1항 일부)에 해당하는 개인 또는 그 개인이 임원인 법인":"폐쇄명령 후 3년이 안 되었거나 임원 결격사유에 해당하는 개인이나 그런 임원이 있는 법인은 신고할 수 없습니다.","신분증명서로 자격 확인이 되면 증 제출 생략 가능":"신분증명서로 수급 자격을 알 수 있으면 증을 내는 일을 생략할 수 있습니다.","신청 대리는 가족·친족·이해관계인 / 사회복지전담공무원 / 치매안심센터의 장(치매환자) / 시장·군수·구청장이 지정하는 자":"가족과 친족과 이해관계인과 사회복지전담공무원과 치매안심센터의 장 등이 신청을 대신할 수 있습니다.","신청 시 수급권자와 부양의무자는 금융정보·신용정보·보험정보 제공에 동의한다는 서면을 제출":"신청할 때 수급권자와 부양의무자는 금융·신용·보험 정보 제공에 동의하는 서면을 냅니다.","신청 시 업무담당자는 근거 법령·조사의 목적·범위·이용방법 / 변동 신고의무 / 정보의 보유기간 및 파기를 고지하여야 한다":"신청을 받을 때 담당자는 근거 법령과 조사 목적과 변동 신고 의무와 정보 보유와 파기를 알려야 합니다.","신청에 의한 조사 사항은 부양의무자 유무·부양능력 / 수급권자·부양의무자의 소득·재산 / 근로능력 취업상태 자활욕구 / 건강상태 가구 특성 등 생활실태":"조사 사항에는 부양의무자 유무와 부양능력과 소득·재산과 근로능력과 자활욕구와 생활실태가 있습니다.","신청은 공단에 장기요양인정신청서에 의사 또는 한의사의 의사소견서를 첨부하여 제출(소견서는 등급판정위원회 자료 제출 전까지 제출 가능, 거동이 현저히 불편한 자 등은 생략 가능), 장기요양기관이 수급자를 대리하여 신청하는 것은 아님":"신청서에 의사나 한의사의 소견서를 붙여 공단에 내며 소견서는 등급판정위원회 자료 제출 전까지 낼 수 있습니다.","신청은 수급희망자 또는 대리인이 특별자치시장·특별자치도지사·시장·군수·구청장에게 신청, 수급희망자와 배우자는 금융·신용·보험 정보 제공 동의 서면 제출":"신청은 수급희망자나 대리인이 시장·군수·구청장 등에게 하며 본인과 배우자는 금융·신용·보험 정보 동의서를 냅니다.","신청은 지원대상자 또는 친족·이해관계인이 관할 시장·군수·구청장에게 신청하고 금융·신용·보험 정보 제공 동의 서면을 제출":"지원대상자나 친족과 이해관계인이 관할 단체장에게 신청하고 금융·신용·보험 정보 동의서를 냅니다.","신청일 기준 결격사유에 해당하면 발급 불가":"신청한 날을 기준으로 결격사유에 해당하면 자격증을 발급받을 수 없습니다.","신청 자격은 노인등으로서 장기요양보험가입자 또는 피부양자 / 의료급여수급권자":"장기요양 신청은 노인등으로서 보험가입자나 피부양자 또는 의료급여수급권자만 할 수 있습니다.","신체장애자 및 질병·노령 기타의 사유로 생활능력이 없는 국민은 법률이 정하는 바에 의하여 국가의 보호를 받는다(헌법이 정하는 바가 아니라 법률)":"생활능력이 없는 국민은 헌법이 아니라 법률이 정하는 바에 따라 국가의 보호를 받습니다.","신체적 장애는 주요 외부 신체 기능의 장애 내부기관의 장애 등 / 정신적 장애는 발달장애 또는 정신 질환으로 발생하는 장애":"신체적 장애는 외부 신체 기능과 내부기관의 장애이고 정신적 장애는 발달장애나 정신 질환으로 생기는 장애입니다.","실무위원회를 두고 실무위원회에 분야별 전문위원회를 둘 수 있다":"위원회 밑에 실무위원회를 두고 그 안에 분야별 전문위원회를 둘 수 있습니다.","실무위원회 의결 사항은 위원장에게 보고하고 위원회 심의를 거친다(경미한 사항은 실무위원회 의결로 갈음 가능)":"실무위원회 안건은 위원장 보고 후 위원회 심의가 원칙이고 가벼운 건 실무위원회가 끝냅니다.","실업급여를 받을 권리는 양도·압류하거나 담보로 제공할 수 없다, 실업급여수급계좌 예금 중 대통령령 금액 이하는 압류 불가":"실업급여를 받을 권리는 넘기거나 압류하거나 담보로 쓸 수 없고 수급계좌 예금도 일정 금액까지 압류가 안 됩니다.","실업급여 종류는 구직급여와 취업촉진 수당":"실업급여는 구직급여와 취업촉진 수당으로 나뉩니다.","실업은 근로의 의사와 능력이 있음에도 불구하고 취업하지 못한 상태에 있는 것 (근로의 의사와 능력이 없는 상태라는 선지는 오답)":"실업은 일할 뜻과 능력이 있는데도 일자리를 못 구한 상태이며 일할 의사나 능력이 없는 상태는 실업이 아닙니다.","실업의 신고는 구직급여를 지급받으려는 사람은 이직 후 지체 없이 직업안정기관에 출석하여 실업을 신고하여야 한다, 신고에는 구직 신청과 수급자격 인정신청 포함, 이직확인서 발급 요청 가능":"구직급여를 받으려면 이직 후 지체 없이 직업안정기관에 출석해 실업을 신고해야 하며 신고에는 구직 신청과 수급자격 인정신청이 들어갑니다.","실업의 예방 고용의 촉진 직업능력의 개발과 향상 직업지도·직업소개 기능 강화 실업 시 생활에 필요한 급여로 생활안정과 구직 활동을 촉진":"고용보험법은 실업 예방과 직업능력 개발과 실업급여를 통해 근로자의 생활안정과 구직 활동을 돕는 법입니다.","실업의 인정은 직업안정기관의 장이 수급자격자가 실업한 상태에서 적극적으로 직업을 구하기 위해 노력하고 있다고 인정하는 것":"실업의 인정은 직업안정기관의 장이 수급자격자가 적극적으로 구직 노력을 하고 있다고 판단하는 절차입니다.","실업자 특례(임의계속가입)는 사용관계가 끝난 사람 중 직장가입자 자격 유지기간이 통산 1년 이상이면 신청해 직장가입자 자격을 유지, 보수월액은 최근 12개월 평균, 보험료는 본인이 전액 부담":"퇴직 후에도 직장가입자 자격을 통산 1년 이상 유지한 사람은 신청하면 최근 12개월 평균 보수월액으로 자격을 이어 갑니다.","실업 크레딧은 18세 이상 60세 미만 가입자(였던 자)가 고용보험법상 구직급여를 받는 경우 신청하면 그 기간을 추가 산입, 1년을 초과할 수 없다, 인정소득은 구직급여 산정 기초 임금일액을 월액으로 환산한 금액의 절반":"실업 크레딧은 구직급여를 받는 가입자가 신청하면 1년을 넘지 않는 범위에서 그 기간을 가입기간에 더해 줍니다.","실태조사는 3년마다 실시·공표 (5년마다 시행계획은 오답)":"실태조사는 3년마다 실시하고 공표하며 5년마다 시행계획이라는 말은 틀립니다.","실태조사는 보건복지부장관이 3년마다 정기적으로 실시하고 결과를 공표":"보건복지부장관이 3년마다 실태조사를 정기적으로 하고 결과를 공표합니다.","실태조사는 성평등가족부장관이 3년마다 한부모가족 실태조사를 실시하고 공표 (5년마다는 오답, 2024 기출의 여성가족부는 현재 성평등가족부)":"성평등가족부장관이 3년마다 실태조사를 하고 공표하며 5년마다가 아니고 2024년 기출의 여성가족부는 지금의 성평등가족부입니다.","심사와 재심사는 피보험자격 취득·상실 확인 / 실업급여 / 육아휴직 급여 등에 이의가 있으면 고용보험심사관에게 심사를 청구하고 안 날부터 90일 이내, 결정에 이의가 있으면 고용보험심사위원회에 결정을 안 날부터 90일 이내 재심사 청구":"피보험자격이나 실업급여에 이의가 있으면 고용보험심사관에게 안 날부터 90일 이내에 심사를 청구하고 불복하면 심사위원회에 재심사합니다.","심사청구는 공단 또는 건강보험공단에 처분을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일 경과 시 제기 불가, 재심사청구는 결정통지를 받은 날부터 90일 이내에 국민연금재심사위원회(보건복지부 위원장 포함 20명 이내)":"심사청구는 처분을 안 날부터 90일 이내 문서로 하며 처분일부터 180일이 지나면 제기하지 못하고 재심사는 90일 이내 재심사위원회에 합니다.","심사 청구는 공단의 보험급여 결정 등에 불복하면 보험급여 결정 등을 한 공단 소속 기관을 거쳐 공단에 결정을 안 날부터 90일 이내 청구, 행정심판법에 따른 행정심판은 제기할 수 없다":"공단의 급여 결정에 불복하면 안 날부터 90일 이내에 공단에 심사를 청구해야 하고 행정심판법상 심판은 따로 못 합니다.","심사청구는 공단 처분을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일 경과 시 제기 불가, 장기요양심사위원회는 공단에 두며 위원장 포함 50명 이내":"공단 처분을 안 날부터 90일 이내 문서로 심사청구하고 처분일부터 180일이 지나면 못 하며 심사위원회는 50명 이내입니다.","심신미약·심신상실 등 대통령령으로 정하는 경우에는 동의 없이도 직권 신청할 수 있고 이 경우 직권 신청 사실을 보장기관의 장에게 지체 없이 보고":"심신미약 같은 대통령령 사유가 있으면 동의 없이 직권 신청하고 이를 보장기관의 장에게 곧바로 보고합니다.","심신장애자복지법(1981) → 1989 장애인복지법으로 전부개정":"1981년의 심신장애자복지법은 1989년에 전부개정되면서 장애인복지법이 되었습니다.","심의로 연장 시 한도는 생계·시설·그 밖의 지원은 총 6개월 초과 불가 / 주거지원은 총 12개월 초과 불가 / 의료지원은 총 2번 / 교육지원은 총 4번":"심의로 연장해도 생계·시설·그 밖의 지원은 총 6개월, 주거지원은 총 12개월을 넘지 못하고 의료는 2번, 교육은 4번이 한도입니다.","심의 사항은 시설운영계획 수립·평가 / 사회복지 프로그램 개발·평가 / 종사자 근무환경 개선 / 거주자 생활환경 개선 및 고충 처리 / 종사자·거주자 인권보호 및 권익증진 / 시설과 지역사회의 협력 / 그 밖에 시설의 장이 회의에 부치는 사항":"운영위원회는 운영계획과 프로그램, 근무환경과 거주자 생활환경과 인권보호, 지역사회 협력 등을 심의합니다.","심의 사항은 제도 및 재정 계산 / 급여 / 연금보험료 / 기금 / 보건복지부장관이 부의하는 사항":"위원회는 제도와 재정 계산과 급여와 보험료와 기금에 관한 사항을 심의합니다.","심의 사항은 종합계획 및 시행계획(의결 제외) / 요양급여의 기준 / 요양급여비용 / 직장가입자 보험료율 / 지역가입자 보험료율과 재산보험료부과점수당 금액 / 보험료 부과 제도 개선(의결 제외) / 그 밖의 주요 사항":"위원회는 종합계획과 요양급여 기준과 요양급여비용과 직장·지역가입자 보험료율 등을 심의하되 일부는 의결에서 제외됩니다.","심의 사항은 지원연장 결정 / 긴급지원의 적정성 심사 / 중단 또는 비용환수 결정 / 위원장이 부의하는 사항":"긴급지원심의위원회는 지원 연장과 적정성 심사와 중단 및 비용환수를 결정합니다.","심의·의결 사항은 기초생활보장 종합계획 수립 / 소득인정액 산정방식과 기준 중위소득 결정 / 급여 종류별 수급자 선정기준과 최저보장수준 결정 / 급여기준 적정성 평가 및 실태조사 / 급여 누락·중복 및 차상위계층 지원사업 조정 / 자활기금 적립·관리·사용 지침 / 위원장이 회의에 부치는 사항":"중앙생활보장위원회는 종합계획과 기준 중위소득과 수급자 선정기준과 최저보장수준 등을 심의하고 의결합니다.","심의·자문: 시·군·구 계획 수립·시행·평가 / 조사·지표 / 급여 제공 / 사회보장 추진 / 읍·면·동 협의체 구성·운영 / 그 밖의 사항 (국가와 지방자치단체의 역할 및 비용 부담은 포함되지 않는다)":"협의체는 시·군·구 계획과 조사와 급여 제공 등을 다루지만 국가와 지방자치단체의 역할 및 비용 부담은 포함하지 않습니다.","심의·자문: 시·도 지역사회보장계획 수립·시행·평가 / 조사·지표 / 급여 제공 / 사회보장 추진 중요 사항 / 특별자치시는 읍·면·동 협의체와 연계·협력":"시·도위원회는 지역사회보장계획과 조사와 급여 제공 등을 심의하고 자문하며 읍·면·동 협의체와 협력합니다.","심판청구는 이의신청 결정에 불복하면 보건복지부 건강보험분쟁조정위원회(위원장 포함 60명 이내)에 청구, 이후 행정소송":"이의신청 결정에 불복하면 건강보험분쟁조정위원회에 심판을 청구하고 그다음에 행정소송으로 갑니다.","아동권리보장원의 장은 아동학대가 종료된 이후에도 아동학대의 재발 여부를 확인하여야 한다":"학대 사건이 종결된 후에도 보장원장이 다시 학대가 일어나지 않았는지 점검하는 사후 의무입니다.","아동보호전문기관은 시·도 및 시·군·구에 1개소 이상 두며 지방자치단체가 설치(통합 설치 가능), 비영리법인에 위탁 운영 가능":"아동보호전문기관은 시·도와 시·군·구에 1개소 이상 두며 지방자치단체가 설치하고 비영리법인에 위탁할 수 있습니다.","아동복리법 → 1981 아동복지법으로 전부개정":"과거의 아동복리법이 1981년 전부개정을 통해 아동복지법이란 이름으로 바뀌었습니다.","아동복지법상 보호조치된 부양 대상 아동도 포함":"아동복지법에 따라 보호조치된 부양 대상 아동도 부양을 받을 수 없는 경우에 포함됩니다.","아동복지심의위원회는 시·도지사와 시장·군수·구청장이 소속으로 둔다, 심의 사항은 시행계획 / 보호조치 / 퇴소조치 / 보호기간 연장 및 종료 / 재보호조치 / 친권상실 선고 청구 / 후견인 선임·변경 청구 / 지원대상아동 선정 / 그 밖의 사항":"시·도지사와 시장·군수·구청장 소속으로 두며 시행계획과 보호조치와 퇴소와 재보호와 친권상실 청구 등을 심의합니다.","아동복지전담공무원은 시·도 및 시·군·구에 둘 수 있다, 사회복지사 자격을 가진 사람":"시·도와 시·군·구에 둘 수 있고 사회복지사 자격을 가진 사람이어야 합니다.","아동위원은 시·군·구에 둔다(시·도 아님), 명예직이되 수당을 지급할 수 있다":"아동위원은 시·군·구에 두며 시·도에는 두지 않고 명예직이지만 수당을 줄 수 있습니다.","아동은 18세 미만(취학 중이면 22세 미만, 병역의무를 이행하고 취학 중이면 이행한 기간을 가산한 연령 미만)":"이 법의 아동은 18세 미만이며 취학 중이면 22세 미만이고 병역을 이행했다면 그 기간을 더한 연령 미만입니다.","아동이 건강하게 출생하여 행복하고 안전하게 자랄 수 있도록 아동의 복지를 보장":"아동복지법은 아동이 건강하게 태어나 행복하고 안전하게 자라도록 복지를 보장하려는 법입니다.","아동전용시설은 국가와 지방자치단체는 아동이 항상 이용할 수 있는 아동전용시설을 설치하도록 노력하여야 한다":"아동이 언제든 드나들 수 있는 전용 공간을 마련하는 것은 공공의 노력 의무입니다.","아동정책기본계획은 보건복지부장관이 5년마다 수립하고 미리 관계 중앙행정기관의 장과 협의, 아동정책조정위원회 심의를 거쳐 확정":"아동정책기본계획은 장관이 5년마다 세우되 부처와 협의하고 아동정책조정위원회 심의를 거쳐 확정합니다.","아동정책조정위원회는 국무총리 소속(보건복지부장관 소속 아님), 위원장 포함 25명 이내이고 위원장은 국무총리, 당연직 위원은 교육부 법무부 행정안전부 문화체육관광부 산업통상부 보건복지부 고용노동부 성평등가족부 기획예산처 장관 + 위촉위원 15명 이내":"아동정책조정위원회는 국무총리 소속으로 위원장이 국무총리이며 보건복지부장관 소속이 아닙니다.","아동종합실태조사는 보건복지부장관이 3년마다 아동의 양육·생활환경 언어·인지 발달 정서적·신체적 건강 아동안전 아동학대 등을 조사해 공표":"보건복지부장관이 3년마다 아동의 양육과 생활과 발달과 건강과 안전 등을 조사해 공표합니다.","아동·청소년은 24세 이하인 사람":"이 법에서 아동·청소년은 24세 이하인 사람입니다.","아동학대관련범죄는 아동학대범죄의 처벌 등에 관한 특례법상 아동학대범죄 + 아동에 대한 형법 살인의 죄(제250조~제255조)":"아동학대범죄처벌특례법의 아동학대범죄와 아동에 대한 형법상 살인의 죄가 아동학대관련범죄입니다.","아동학대 예방과 방지는 국가와 지방자치단체가 정책 수립 / 연구·교육·홍보·실태조사 / 신고체제 / 피해아동 보호·치료 / 가정 지원, 시·도지사 또는 시장·군수·구청장이 아동학대 신고접수·현장조사·응급보호 업무를 수행":"국가와 지방자치단체가 정책 수립과 연구와 교육과 홍보와 신고체제와 피해아동 보호 등을 해야 합니다.","아동학대예방의 날은 매년 11월 19일(예방주간은 그날부터 1주일)":"학대 예방을 위한 기념일은 11월 19일이며 그날로부터 일주일이 예방주간입니다.","양도하거나 담보로 제공할 수 없고 압류 대상으로 할 수 없다, 기초연금으로 지급받은 금품은 압류할 수 없다":"기초연금은 넘기거나 담보로 쓰거나 압류할 수 없고 이미 받은 금품도 압류할 수 없습니다.","어린이날은 매년 5월 5일 / 어린이주간은 5월 1일~7일":"어린이날은 매년 5월 5일이고 어린이주간은 5월 1일부터 7일까지입니다.","업무는 가입자 기록 관리 / 연금보험료 부과 / 급여 결정 및 지급 / 복지사업 / 자금 대여 / 노후준비서비스 / 조사연구 / 기금운용 인력 양성 / 국제협력 등":"공단은 가입자 기록 관리와 보험료 부과와 급여 결정 및 지급과 복지사업과 노후준비서비스 등을 맡습니다.","업무는 시스템 구축·유지 / 자료·정보 처리 / 급여 업무 전자적 처리지원 / 사회서비스이용권 정보시스템 / 민간 전자화 지원 / 정책·통계정보 생산·분석 / 대국민 포털 운영 등":"정보원은 시스템 구축과 자료 처리와 급여 업무 전자 지원과 통계 분석과 포털 운영 등을 합니다.","업무는 요양급여비용의 심사 / 요양급여의 적정성 평가 / 심사기준 및 평가기준 개발 / 관련 조사연구 및 국제협력 / 다른 법률에 따른 급여비용 심사·평가 위탁 업무":"심사평가원은 비용 심사와 적정성 평가와 기준 개발과 조사연구와 위탁 업무를 맡습니다.","업무는 피해아동·가족·아동학대행위자·사례관리대상자를 위한 상담·치료 및 교육 / 아동학대예방 교육 및 홍보 / 피해아동 가정의 사후관리 / 그 밖의 대통령령 사항, 아동학대 신고접수·현장조사·응급보호는 시·도지사 또는 시장·군수·구청장의 업무":"기관은 피해아동과 가족과 행위자에 대한 상담·치료·교육과 예방 교육과 홍보와 사후관리 등을 합니다.","업무 또는 공무로 생긴 질병·부상·재해로 다른 법령에 따른 급여나 보상을 받게 되면 의료급여를 하지 아니한다":"업무나 공무 때문에 생긴 질병이나 재해로 다른 법에 따른 급여나 보상을 받게 되면 의료급여를 하지 않습니다.","업무상 사고는 근로계약에 따른 업무나 그에 따르는 행위를 하던 중 발생한 사고 / 사업주가 제공한 시설물 등을 이용하던 중 결함이나 관리소홀로 발생한 사고 / 사업주가 주관하거나 지시에 따라 참여한 행사나 준비 중 발생한 사고 / 휴게시간 중 사업주의 지배관리하에 있다고 볼 수 있는 행위로 발생한 사고 / 그 밖에 업무와 관련하여 발생한 사고":"근로계약에 따른 업무 중이거나 사업주가 제공한 시설 결함으로 생기거나 행사 중에 생긴 사고가 업무상 사고입니다.","업무상의 재해는 업무상의 사유에 따른 근로자의 부상·질병·장해 또는 사망":"업무상 재해는 업무상 사유로 근로자가 입은 부상과 질병과 장해와 사망을 말합니다.","업무상 재해를 신속하고 공정하게 보상하고 재해근로자의 재활 및 사회 복귀를 촉진하며 재해 예방과 복지 증진 사업을 시행해 근로자 보호에 이바지":"산재보험법은 업무상 재해를 신속하고 공정하게 보상하고 재활과 복귀를 돕고 예방 사업을 하는 법입니다.","업무상 질병은 물리적 인자 화학물질 분진 병원체 신체에 부담을 주는 업무 등 건강장해 요인에 노출되어 발생한 질병 / 업무상 부상이 원인이 된 질병 / 직장 내 괴롭힘 고객의 폭언 등 업무상 정신적 스트레스가 원인인 질병 / 그 밖에 업무와 관련하여 발생한 질병":"유해한 물리 화학 인자와 분진과 병원체 등에 노출되어 생긴 질병이나 업무상 부상이 원인이 된 질병 등이 업무상 질병입니다.","업무상질병판정위원회는 업무상 질병의 인정 여부를 심의하기 위해 공단 소속 기관에 둔다":"업무상 질병이 맞는지 가리려고 공단 소속 기관에 두는 위원회입니다.","업무와 재해 사이에 상당인과관계가 없으면 업무상 재해가 아니다":"업무와 재해 사이에 상당한 인과관계가 있어야 업무상 재해로 인정됩니다.","업무 위탁은 신청 접수 / 조사·질문 지원 / 기초연금 지급 / 미지급 청구 접수 / 신고 접수 / 환수금 고지·독촉·징수 / 이의신청 접수 / 정보시스템 운영을 국민연금공단에 위탁할 수 있다":"신청 접수와 조사 지원과 연금 지급과 환수금 징수 등은 국민연금공단에 위탁할 수 있습니다.","업무·일상생활에 지장 없는 질환 등은 대상에서 제외할 수 있다":"의료급여가 필요한 정도에 이르지 않는 가벼운 질환은 대상에서 빼도록 허용합니다.","업무정지는 보건복지부장관이 의료급여기관에 1년의 범위에서 업무정지 명령(속임수 급여비용 부담 / 본인부담금 미리 청구 및 다른 명목 비용 청구 / 보고·서류제출 거부 등), 제3차 의료급여기관은 지정 취소 가능하고 취소일부터 1년 내 재지정 불가":"속임수 청구나 본인부담금 미리 청구 같은 위반이 있으면 장관이 1년 범위에서 급여기관의 업무를 정지시킬 수 있습니다.","업무 종사자였던 사람도 알게 된 정보를 다른 용도로 사용 금지":"업무에서 물러난 사람도 알게 된 정보를 다른 용도로 쓰는 것은 금지됩니다.","연금보험료는 사업장가입자의 기여금과 부담금은 각각 기준소득월액의 1천분의 65(합계 1천분의 130), 지역가입자·임의가입자·임의계속가입자는 본인이 기준소득월액의 1천분의 130 부담":"사업장가입자는 본인과 사용자가 각각 기준소득월액의 1천분의 65를 내 합계 1천분의 130이고 지역가입자 등은 혼자 1천분의 130입니다.","연금보험료를 내지 않은 기간은 산입하지 않는다":"보험료를 납부하지 않은 기간은 가입기간으로 인정되지 않습니다.","연금보험료 징수는 건강보험공단에 위탁":"연금보험료를 걷는 일은 공단이 아니라 건강보험공단에 위탁합니다.","연금액은 매년 전국소비자물가변동률에 따라 조정(국민연금심의위원회 심의)하고 적용기간은 해당 연도 1월부터 12월까지":"연금액은 매년 물가변동률에 맞춰 조정하며 국민연금심의위원회가 심의하고 적용은 1월부터 12월까지입니다.","연금액은 지급사유에 따라 기본연금액과 부양가족연금액을 기초로 산정":"연금액은 지급 사유에 따라 정한 기본연금액에 부양가족연금액을 얹어 계산합니다.","연금 지급은 지급 사유가 생긴 날이 속하는 달의 다음 달부터 수급권 소멸일이 속하는 달까지, 매월 25일 지급(지급일이 토요일이나 공휴일이면 그 전날)":"지급 사유가 생긴 다음 달부터 소멸한 달까지 매월 25일에 주고 그날이 토요일이나 공휴일이면 그 전날 줍니다.","연도별 시행계획은 보건복지부장관 관계 중앙행정기관의 장 시·도지사가 매년 수립·시행":"시행계획은 보건복지부장관과 관계 기관의 장과 시·도지사가 매년 세워 시행합니다.","연장급여 3가지는 훈련연장급여(직업능력개발 훈련 중 소정급여일수 초과 지급) / 개별연장급여(취업이 특히 곤란하고 생활이 어려운 자에게 60일 범위) / 특별연장급여(고용노동부장관이 실업 급증 등 사유로 60일 범위에서 기간을 정해 실시)":"연장급여에는 훈련연장급여와 개별연장급여와 특별연장급여 세 가지가 있습니다.","연체금은 납부기한이 지난 날부터 매 1일마다 체납금액의 1천500분의 1(상한 1천분의 20), 30일이 지나면 6천분의 1을 더 징수(합계 상한 1천분의 50)":"납부기한이 지난 날마다 체납액의 1천500분의 1을 더하고 30일이 지나면 6천분의 1을 더해 합계 1천분의 50까지 부과합니다.","영역별 사회복지사는 1급 자격자 중 보건복지부령으로 정하는 수련기관에서 수련을 받은 사람에게 부여한다":"영역별 사회복지사는 1급 자격자가 보건복지부령으로 정한 수련기관에서 수련을 받아야 얻습니다.","영유아보육법(1991) / 고용보험법(1993) / 사회보장기본법(1995) / 정신보건법(1995)":"영유아보육법은 1991년, 고용보험법은 1993년, 사회보장기본법과 정신보건법은 1995년에 제정됐습니다.","외국인도 당연히 사업장가입자 또는 지역가입자가 된다(본국 법이 상호주의에 맞지 않으면 제외), 사회보장협정이 있으면 그 협정에 따른다":"외국인도 원칙적으로 사업장가입자나 지역가입자가 되며 본국 법이 상호주의에 맞지 않으면 제외하고 사회보장협정이 있으면 그것을 따릅니다.","외국인에 대한 사회보장제도 적용은 국내에 거주하는 외국인에게는 상호주의 원칙에 따르되 관계 법령에서 정하는 바에 따른다":"국내 거주 외국인에게 사회보장 제도를 적용할 때는 상호주의를 원칙으로 하고 관계 법령의 규정을 따릅니다.","외국인 이사는 이사 현원의 2분의 1 미만":"외국인이 이사회의 절반 이상을 차지하지 못하게 2분의 1 미만만 허용하는 제한입니다.","외국인 특례: 국내 체류 외국인 중 대통령령으로 정하는 사람이 긴급지원대상자가 될 수 있다":"국내 체류 외국인 가운데 대통령령이 정하는 사람은 긴급지원대상자가 될 수 있다는 특례입니다.","외국인 특례는 국내체류 재외국민·외국인도 일정 요건을 갖추면 직장가입자 지역가입자 피부양자가 될 수 있다":"재외국민과 외국인에게도 문을 열어 두어 요건만 맞으면 내국인처럼 가입자나 피부양자가 되게 하는 특례입니다.","요양급여 7가지는 진찰·검사 / 약제·치료재료의 지급 / 처치·수술 및 그 밖의 치료 / 예방·재활 / 입원 / 간호 / 이송":"요양급여는 진찰과 약제와 처치와 예방·재활과 입원과 간호와 이송 일곱 가지입니다.","요양급여는 근로자가 업무상 사유로 부상을 당하거나 질병에 걸린 경우에 지급, 산재보험 의료기관에서 요양하고 부득이하면 요양비로 갈음, 3일 이내 요양으로 치유되면 지급하지 않는다":"요양급여는 산재보험 의료기관에서 요양하는 것이 원칙이고 부득이하면 요양비로 대신하며 3일 이내에 낫는 경우는 주지 않습니다.","요양급여 범위 8가지는 진찰 및 검사 / 약제·진료재료와 의지·보조기 지급 / 처치·수술·그 밖의 치료 / 재활치료 / 입원 / 간호 및 간병 / 이송 / 그 밖에 고용노동부령 사항":"요양급여는 진찰과 약제와 치료와 재활치료와 입원과 간호·간병과 이송 등 여덟 가지입니다.","요양급여비용 심사는 공단이 아니라 심사평가원 업무이다, 의료시설의 운영은 공단 업무":"급여비용을 심사하는 일은 공단이 아니라 심사평가원 업무이고 의료시설의 운영은 공단이 합니다.","요양급여비용은 공단 이사장과 대통령령이 정하는 의약계 대표의 계약으로 정한다(계약기간 1년)":"급여 비용은 공단 이사장과 의약계 대표가 계약해 정하며 계약 기간은 1년입니다.","요양급여비용을 심사하고 요양급여의 적정성을 평가하기 위해 설립":"심사평가원은 급여 비용을 심사하고 요양급여가 알맞은지 평가하려고 설립한 기관입니다.","요양기관(간호와 이송은 제외)은 의료기관 / 약국 / 한국희귀·필수의약품센터 / 보건소·보건의료원·보건지소 / 보건진료소, 정당한 이유 없이 요양급여를 거부하지 못한다":"요양기관은 의료기관과 약국과 희귀·필수의약품센터와 보건소 등이며 정당한 이유 없이 급여를 거부할 수 없습니다.","요양기관 업무정지는 보건복지부장관이 1년의 범위에서 명할 수 있다, 업무정지에 갈음해 부당 부담금액의 5배 이하 과징금(12개월 분할납부)":"장관은 요양기관에 1년 범위에서 업무정지를 명할 수 있고 대신 부당 부담금액의 5배 이하 과징금을 낼 수 있게 합니다.","요양비는 긴급하거나 부득이한 사유로 의료급여기관이 아닌 곳에서 의료급여를 받거나 의료급여기관이 아닌 장소에서 출산한 경우 시장·군수·구청장이 수급권자에게 지급":"긴급할 때 급여기관이 아닌 곳에서 의료급여를 받거나 출산한 경우 시장·군수·구청장이 수급권자에게 요양비를 줍니다.","요양비는 긴급하거나 부득이한 사유로 준요양기관에서 요양을 받거나 요양기관이 아닌 장소에서 출산한 경우 공단이 요양비로 지급":"긴급하거나 부득이하게 준요양기관에서 요양하거나 기관이 아닌 곳에서 출산하면 공단이 요양비로 지급합니다.","우선 제공 대상은 기초생활보장 수급자 및 차상위계층 / 장애인·노인·한부모가족·다문화가족 / 직업 및 취업 알선이 필요한 사람 / 보호와 교육이 필요한 유아·아동·청소년 / 그 밖에 필요하다고 인정되는 사람":"수급자와 차상위계층과 장애인, 노인, 한부모가족, 다문화가족, 취업이 필요한 사람 등이 우선 대상입니다.","우선 필요한 지원을 하게 할 수 있다":"결정 전이라도 급한 지원을 먼저 하게 할 수 있다는 재량 규정입니다.","위기상황에 처한 사람에게 일시적으로 신속하게 지원":"이 법의 지원은 오래 이어지는 보호가 아니라 위기를 넘기도록 한시적으로 신속하게 주는 것이 원칙입니다.","위반 시 1년 이하의 징역 또는 1천만원 이하의 벌금(10년·1억원 아님)":"자격증 대여 금지를 어기면 1년 이하의 징역이나 1천만원 이하의 벌금이며 10년이나 1억원이 아닙니다.","위법·부당한 처분을 받거나 필요한 처분을 받지 못한 국민은 행정심판법에 따른 행정심판 또는 행정소송법에 따른 행정소송을 청구할 수 있다":"위법하거나 부당한 처분을 받은 국민은 행정심판이나 행정소송으로 권리를 구제받을 수 있습니다.","위원 구성은 대통령령으로 정하는 관계 중앙행정기관의 장 + 대통령이 위촉하는 근로자 대표·사용자 대표·사회보장 등 관련 분야 학식 경험자·변호사 자격이 있는 사람":"위원은 관계 중앙행정기관의 장과 대통령이 위촉하는 근로자 대표와 사용자 대표와 전문가와 변호사 등입니다.","위원장 1명, 부위원장 3명, 행정안전부장관·고용노동부장관·성평등가족부장관·국토교통부장관을 포함한 30명 이내의 위원 (2023 기출 당시 부위원장 2명, 40명 이내)":"위원회는 위원장 1명과 부위원장 3명 등 30명 이내로 구성되며 2023년에는 부위원장 2명에 40명 이내였습니다.","위원장 1명 포함 15명 이내이고 위원장은 시장·군수·구청장":"이 위원회는 15명까지 두며 위원장은 지역 단체장이 맡는 지방 단위 기구입니다.","위원장은 국무총리, 부위원장은 교육부장관·보건복지부장관·기획예산처장관":"위원회 대표는 국무총리이고 부위원장 세 명은 교육, 보건복지, 기획예산 부처의 장관들입니다.","위원장 포함 15명 이내이고 위원장은 보건복지부차관":"의료급여심의위원회는 15명 이내의 규모이고 보건복지부 차관이 위원장을 맡습니다.","위원장 포함 16명 이내로 구성하고 위원장은 보건복지부장관, 위원은 공공부조·사회복지 전문가(조교수 이상 또는 연구원) 5명 이내 + 공익대표 5명 이내 + 관계 행정기관 3급 이상 공무원 등 5명 이내":"중앙위원회는 위원장 포함 16명 이내로 위원장은 보건복지부장관이고 전문가와 공익대표와 공무원이 각각 5명 이내입니다.","유류금품: 장제급여 시 사망자에게 부양의무자가 없으면 시장·군수·구청장이 유류 금전·유가증권으로 비용에 충당하고 부족액은 유류물품 매각대금으로 충당할 수 있다":"장제급여를 받는 사망자에게 부양의무자가 없으면 남긴 금전으로 비용을 충당하고 모자라면 물품 매각대금을 씁니다.","유족급여는 근로자가 업무상 사유로 사망한 경우 유족에게 지급, 유족보상연금 또는 유족보상일시금(연금 수급 자격자가 없을 때)":"근로자가 업무상 사유로 사망하면 유족에게 유족보상연금을 주고 연금 수급 자격자가 없으면 일시금을 줍니다.","유족급여 일시금 선택은 연금 수급 자격자가 원하면 일시금의 100분의 50을 일시금으로 받고 연금은 100분의 50 감액, 연금 수급자격 상실 시 이미 지급한 연금액을 평균임금으로 나눈 일수가 1,300일에 못 미치면 차액을 일시금으로 지급":"연금 수급자가 원하면 일시금의 100분의 50을 일시금으로 받고 연금은 100분의 50을 줄여 받을 수 있습니다.","유족연금액은 가입기간 10년 미만 기본연금액의 1천분의 400 / 10년 이상 20년 미만 1천분의 500 / 20년 이상 1천분의 600 + 부양가족연금액, 노령연금 수급권자가 사망한 경우 그가 받던 노령연금액 초과 불가":"유족연금은 가입기간이 길수록 비율이 1천분의 400에서 1천분의 600까지 커지고 노령연금 수급자의 사망이면 그 연금액을 못 넘습니다.","유족은 사망한 사람의 배우자(사실상 혼인 관계 포함)·자녀·부모·손자녀·조부모 또는 형제자매":"산재보험의 유족은 사망한 사람의 배우자와 자녀와 부모와 손자녀와 조부모와 형제자매이며 사실혼도 포함합니다.","유족의 범위는 사망자에 의하여 생계를 유지하던 ① 배우자 ② 자녀(25세 미만 또는 장애상태) ③ 부모(배우자의 부모 포함 60세 이상 또는 장애상태) ④ 손자녀(19세 미만 또는 장애상태) ⑤ 조부모(배우자의 조부모 포함 60세 이상 또는 장애상태), 순위에 따라 최우선 순위자에게만 지급":"유족은 사망자가 생계를 유지해 주던 배우자와 25세 미만 자녀와 60세 이상 부모와 19세 미만 손자녀와 조부모입니다.","육아휴직 급여는 육아휴직을 30일 이상(분할 사용 시 7일) 부여받은 피보험자 중 육아휴직 시작일 이전 피보험 단위기간이 합산 180일 이상인 사람에게 지급, 육아휴직 시작일 이후 1개월부터 종료일 이후 12개월 이내 신청":"육아휴직을 30일 이상 받은 피보험자 중 180일 이상 피보험 단위기간이 있는 사람에게 지급합니다.","육아휴직 급여 제한은 육아휴직 중 이직하면 이직한 때부터 지급하지 않음, 중 취업한 기간 지급하지 않음, 부정 수령 시 지급 제한":"육아휴직 중 이직하면 그때부터, 일을 한 기간에는 지급하지 않고 부정 수령도 제한합니다.","읍·면·동 단위 협의체는 특별자치시장·시장·군수·구청장이 둔다":"읍·면·동 단위 협의체는 시장·군수·구청장이 설치하고 특별자치시장도 둘 수 있습니다.","의결된 날부터 5일 이내에 지방의회 의장이 지방자치단체의 장에게 이송 → 이송받은 날부터 20일 이내 공포":"의결 후 5일 안에 지방의회 의장이 단체장에게 보내고 단체장은 받은 날부터 20일 안에 공포합니다.","의료급여(이 법)는 각종 검사 및 치료 등을 지급, 선정기준은 기준 중위소득의 100분의 40 이상, 필요한 사항은 따로 법률(의료급여법)에서 정함":"국민기초생활보장법상 의료급여는 검사와 치료 등을 지급하고 선정기준이 기준 중위소득 100분의 40 이상이며 세부는 의료급여법이 정합니다.","의료급여기관은 수급권자에 대한 진료·조제 또는 투약 등을 담당하는 의료기관 및 약국 등":"의료급여기관은 수급권자의 진료와 조제와 투약을 담당하는 의료기관과 약국 등입니다.","의료급여기관은 의료법에 따른 의료기관 / 보건소·보건의료원·보건지소 / 보건진료소 / 약국 및 한국희귀·필수의약품센터, 보건소도 의료급여기관이 될 수 있다":"의료급여기관에는 의료기관과 보건소와 보건진료소와 약국 등이 있고 보건소도 해당합니다.","의료급여를 받을 권리는 양도하거나 압류할 수 없다":"의료급여를 받을 권리는 양도할 수 없고 압류도 할 수 없습니다.","의료급여법(2001) / 긴급복지지원법(2005) / 자원봉사활동기본법(2005)":"의료급여법은 2001년, 긴급복지지원법과 자원봉사활동기본법은 2005년에 제정되었습니다.","의료급여법 목적은 생활이 어려운 사람에게 의료급여를 함으로써 국민보건의 향상과 사회복지의 증진에 이바지":"의료급여법은 생활이 어려운 사람에게 의료급여를 해서 국민보건과 사회복지 증진에 이바지하려는 법입니다.","의료급여법에 따라 의료급여를 받는 사람(수급권자)과 의료보호를 받는 유공자등 의료보호대상자는 제외(유공자는 신청 시 가입)":"의료급여 수급권자와 의료보호를 받는 유공자는 건강보험 가입 대상에서 제외되며 유공자는 신청하면 가입합니다.","의료급여의 기준은 보건복지부령 수가기준은 보건복지부장관이 정한다":"급여 범위는 부령으로, 의료 행위의 가격을 정하는 수가는 장관이 정하는 것으로 나뉩니다.","의료급여증은 시장·군수·구청장이 수급권자 신청 시 발급하여야 한다(시·도지사 아님)":"의료급여증은 수급권자가 신청하면 시장·군수·구청장이 발급하며 시·도지사가 발급하는 것은 아닙니다.","의료지원과 교육지원은 각각 한 번 실시":"의료지원과 교육지원은 각각 한 번씩만 실시하는 것이 기본입니다.","의복 음식물 연료비 등 일상생활에 기본적으로 필요한 금품을 지급해 생계를 유지하게 함":"생계급여는 의복과 음식과 연료비처럼 일상생활에 기본적으로 필요한 금품을 주어 생계를 유지하게 합니다.","이 경우 지원대상자의 동의를 받아야 하며 동의를 받으면 지원대상자가 신청한 것으로 본다":"직권 신청에는 지원대상자의 동의가 필요하며 동의를 얻으면 본인이 신청한 것으로 봅니다.","이 법과 관련 법률에 따라 지급된 금품과 받을 권리는 압류 불가":"이 법에 따라 지급된 금품과 받을 권리는 압류할 수 없습니다.","이 법에 따라 장애인에게 지급되는 금품은 압류할 수 없다":"장애인에게 지급된 금품은 압류로부터 보호됩니다.","이 법에 따라 지급된 금품과 받을 권리는 압류하지 못한다":"이 법의 급여로 받은 돈과 받을 권리는 채권자가 압류할 수 없게 보호됩니다.","이 법은 제2조제1호 각 목의 법률에 특별한 규정이 없는 사회복지사업의 내용·절차에 적용되고 그 법률을 개정할 때는 이 법에 부합하도록 하여야 한다":"이 법은 다른 개별 법률에 특별한 규정이 없는 사회복지사업의 내용과 절차에 적용되며 그 법률을 고칠 때는 이 법에 맞춰야 합니다.","이사 3년 감사 2년 각각 연임할 수 있다(이사·감사 모두 3년이라는 선지는 오답)":"이사는 3년, 감사는 2년의 임기이고 모두 연임할 수 있으며 이사와 감사가 똑같이 3년인 것은 아닙니다.","이사는 법인이 설치한 시설의 장을 제외한 그 시설의 직원을 겸할 수 없다(시설의 장은 겸할 수 있음)":"이사는 시설의 장은 겸할 수 있지만 그 시설의 직원은 겸할 수 없습니다.","이사 또는 감사 중 결원이 생기면 2개월 이내에 보충(3개월 아님)":"이사나 감사에 결원이 생기면 2개월 안에 채우며 3개월이 아닙니다.","이사 선임은 경제계·언론계·법조계·의료계 종사자 / 노동계·종교계·시민단체 종사자 / 사회복지전문가가 각각 4명 이상 포함":"이사는 경제·언론·법조·의료계와 노동·종교·시민단체와 사회복지 전문가가 각각 4명 이상 포함되도록 선임합니다.","이사장은 재정운영위원회 의결을 거쳐 계약":"이사장은 계약을 맺으려면 재정운영위원회의 의결을 먼저 거쳐야 합니다.","이사 정수의 3분의 1 이상은 시·도사회보장위원회 또는 지역사회보장협의체가 3배수로 추천한 사람 중에서 선임":"이사 정수의 3분의 1 이상은 사회보장위원회나 협의체가 3배수로 추천한 사람 가운데에서 뽑습니다.","이의가 있으면 15일 이내 이의서를 붙여 국회에 환부하고 재의를 요구할 수 있으나 법률안의 일부에 대하여 또는 수정하여 재의를 요구할 수 없다":"대통령은 이의가 있으면 15일 안에 국회에 돌려보내 다시 의결하게 할 수 있지만 일부나 수정은 안 됩니다.","이의가 있으면 20일 이내 재의 요구(일부·수정 재의 요구 불가) → 재적 과반수 출석과 출석 3분의 2 이상 찬성이면 확정":"단체장은 20일 안에 재의를 요구할 수 있으나 일부나 수정은 안 되고 출석 3분의 2 이상 찬성이면 확정됩니다.","이의신청은 공단 처분은 공단에 심사평가원 처분은 심사평가원에 처분을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일 경과 시 제기 불가":"공단의 처분은 공단에, 심사평가원의 처분은 그 원에 안 날부터 90일 이내 이의신청하며 처분일부터 180일이 지나면 못 합니다.","이의신청은 복지조치가 있음을 안 날부터 90일 이내 문서로 장애인복지실시기관에 하고 기관은 30일 이내 심사·결정, 불복 시 행정심판":"복지조치를 안 날부터 90일 이내 문서로 실시기관에 이의하면 기관은 30일 이내에 결정하고 불복하면 행정심판을 합니다.","이의신청은 시장·군수·구청장에게 처분이 있음을 안 날부터 90일 이내 문서로 하고 처분이 있은 날부터 180일이 지나면 제기 불가":"처분을 안 날부터 90일 이내 문서로 해야 하며 처분일로부터 180일이 지나면 제기하지 못합니다.","이의신청은 처분이 있음을 안 날부터 90일 이내 서면, 정당한 사유가 있으면 사유 소멸 후 60일 이내":"이의신청은 처분을 안 날부터 90일 이내 서면으로 하고 정당한 사유가 있으면 소멸 후 60일 이내에 할 수 있습니다.","이주비는 취업 또는 훈련을 위해 주거를 이전하는 경우 필요하다고 인정하면 지급":"취업이나 훈련 때문에 이사해야 하는 경우 필요하다고 인정하면 주는 비용입니다.","이 중 주거·시설·그 밖의 지원은 위기상황이 계속되면 1개월씩 두 번 연장 가능":"위기가 이어지면 이 지원들은 1개월씩 두 번 연장할 수 있습니다.","이직 사유에 따른 수급자격 제한은 ① 중대한 귀책사유로 해고된 피보험자(형법 또는 직무 관련 법률 위반으로 금고 이상 형 선고 / 사업에 막대한 지장을 초래하거나 재산상 손해를 끼침 / 정당한 사유 없이 장기간 무단 결근) ② 자기 사정으로 이직한 피보험자(전직·자영업 이직 / 귀책사유가 있는데 해고되지 않고 사업주 권고로 이직 / 정당하지 않은 사유 이직)":"중대한 귀책사유로 해고되었거나 정당한 사유 없이 자기 사정으로 이직한 경우 등은 수급자격이 제한됩니다.","이직은 피보험자와 사업주 사이의 고용관계가 끝나게 되는 것":"근로자가 일자리를 떠나 사업주와의 고용 관계가 사라지는 사건을 뜻하며 실업급여의 출발점입니다.","인간다운 생활을 할 권리는 헌법재판소가 최소한의 물질적 생활 보장을 요구할 수 있는 한도에서 구체적 권리로 보되 입법 형성의 자유를 넓게 인정한다는 취지":"헌법재판소는 최소한의 물질생활 보장을 요구하는 범위에서 구체적 권리로 보되 입법자의 형성 자유를 넓게 인정합니다.","인권침해 행위가 있으면 국가와 지방자치단체가 처분하고 사실을 공표하는 등 조치":"시설 등의 인권침해는 국가와 지방자치단체가 직접 처분하고 사실을 알리는 조치까지 합니다.","인정 유효기간은 최소 1년 이상으로 대통령령으로 정한다, 갱신은 유효기간 만료 전 30일까지 신청 완료":"인정의 유효기간은 최소 1년 이상으로 정하고 갱신은 유효기간 만료 전 30일까지 신청을 마쳐야 합니다.","일반회계와 구분해 별도 계정으로 관리":"기금은 일반 예산과 섞이지 않게 별도 계정으로 따로 관리합니다.","일반 효과는 양 국가에서 이중으로 보험료를 내는 이중가입 방지(가입 면제) / 양국 가입기간 합산으로 수급 요건 충족(가입기간 합산) / 연금 수급권자의 해외 송금 등":"협정의 효과 세 가지로, 보험료 중복 납부를 막고 가입기간을 합쳐 주며 연금을 해외로 보내게 해 줍니다.","일시보호조치는 아동일시보호시설 학대피해아동쉼터 위탁가정 등에서 보호":"급한 경우 아동일시보호시설이나 학대피해아동쉼터나 위탁가정 등에서 임시로 보호합니다.","일용근로자는 1개월 미만 동안 고용되는 사람 (3개월·6개월 미만이라는 선지는 오답)":"고용보험법에서 일용근로자는 1개월 미만 동안 고용되는 사람이며 3개월이나 6개월 미만이 아닙니다.","임신한 수급권자의 진료비(출산비용 포함)에 추가급여 가능":"임신한 수급권자의 진료비에는 출산 비용까지 포함해 추가 급여를 줄 수 있습니다.","임원 결격은 사회복지사업법 제19조 해당자 일부 / 해임 후 5년 미경과 / 사기·공갈 등 300만원 이상 벌금형 확정 후 2년 미경과":"사회복지사업법 결격자와 해임 후 5년이 안 된 사람과 300만원 이상 벌금형 확정 후 2년이 안 된 사람은 임원이 될 수 없습니다.","임원은 이사장 1명 이사 14명 감사 1명(이사장·이사 5명·감사는 상임), 이사장 임기 3년 이사와 감사 임기 각 2년":"임원은 이사장 1명과 이사 14명과 감사 1명이며 이사장은 임기 3년, 이사와 감사는 각 2년입니다.","임원은 회장 1명 / 부회장 3명 / 이사(회장·부회장·사무총장 포함) 15명 이상 20명 이하 / 감사 2명, 임기 3년 한 차례만 연임 가능, 이사회는 회장이 소집하고 의장":"임원은 회장 1명과 부회장 3명과 이사 15명 이상 20명 이하와 감사 2명이고 임기 3년에 한 차례만 연임합니다.","임원을 임면하면 지체 없이 시·도지사에게 보고하여야 한다":"임원을 임명하거나 해임하면 지체 없이 시·도지사에게 보고해야 합니다.","임원이 결격사유에 해당하게 되면 자격을 상실한다":"재직 중에 결격사유가 생기면 별도 처분 없이 임원 자격이 당연히 사라집니다.","임의가입자는 사업장가입자·지역가입자 외의 18세 이상 60세 미만이 공단에 신청해 가입, 신청으로 탈퇴 가능":"임의가입자는 사업장·지역가입자가 아닌 18세 이상 60세 미만이 신청해 가입하고 신청으로 탈퇴도 할 수 있습니다.","임의계속가입자는 60세가 된 가입자 또는 가입자였던 자가 65세가 될 때까지 신청해 가입(연금보험료 납부 사실 없는 자 / 노령연금 수급 중인 자 / 반환일시금 수령자는 제외), 특수직종근로자 특례 있음":"60세가 된 뒤에도 65세가 될 때까지 신청해 가입할 수 있으나 노령연금 수급 중이거나 반환일시금을 받았으면 제외입니다.","임의적 취소·시정명령 사유는 설립허가 조건 위반 / 목적 달성 불가능 / 목적사업 외의 사업 / 허가일부터 6개월 이내 미시작 또는 1년 이상 사업실적 없음 / 시설에서 반복적·집단적 성폭력범죄·학대관련범죄 / 중대하고 반복적인 회계부정·불법행위 / 임원정수 위반 / 제18조제2항 위반 이사 선임 / 해임명령 불이행 / 그 밖의 법령·정관 위반":"허가 조건 위반이나 목적 달성 불가능이나 6개월 이내 미시작 등은 재량으로 취소나 시정명령을 하는 사유입니다.","자격 변동은 지역가입자가 적용대상사업장의 사용자·근로자가 된 날 / 직장가입자가 다른 사업장의 사용자·근로자가 된 날 / 사용관계가 끝난 날의 다음 날 / 지역가입자가 다른 세대로 전입한 날, 변동일부터 14일 이내 신고":"직장과 지역 사이를 옮기거나 다른 사업장으로 가거나 세대를 옮기는 때 변동되며 사용관계가 끝난 날의 다음 날이 변동일입니다.","자격 상실은 사망 / 사망 근로자의 배우자 재혼(사실혼 포함) / 친족 관계 종료 / 자녀·손자녀 25세 도달 / 형제자매 19세 도달 / 장애 상태 해소 / 국적 상실 후 외국 거주·출국, 3개월 이상 행방불명이면 지급 정지, 자격 상실 시 같은 순위자 → 다음 순위자로 이전":"유족보상연금은 수급자가 사망하거나 재혼하거나 자녀가 25세, 형제자매가 19세에 이르거나 장애가 사라지면 자격을 잃습니다.","자격 상실은 사망한 날의 다음 날 / 국적을 잃은 날의 다음 날 / 국내에 거주하지 아니하게 된 날의 다음 날(당일 아님) / 직장가입자의 피부양자가 된 날 / 수급권자가 된 날 / 유공자등 의료보호대상자가 되어 적용배제신청을 한 날":"사망이나 국적 상실이나 국내 비거주가 된 날의 다음 날 자격을 잃으며 당일이 아닙니다.","자격을 상실한 뒤 다시 취득하면 전후 가입기간을 합산한다, 가입 종류가 변동되면 각 종류별 가입기간을 합산":"자격을 잃었다가 다시 얻으면 앞뒤 기간을 합치고 종류가 바뀌면 각 종류의 기간을 합산합니다.","자격을 취득한 날이 속하는 달의 다음 달부터 자격 상실일의 전날이 속하는 달까지, 취득일이 초일이거나 임의계속가입자이거나 가입자가 희망하면 취득한 달부터 산입":"원칙은 취득한 달의 다음 달부터 상실일 전날이 속한 달까지이고 취득일이 초일이거나 희망하면 취득한 달부터 셉니다.","자격증을 다른 사람에게 빌려주거나 빌리면 안 되고 알선도 금지":"자격증을 남에게 빌려주거나 빌리는 일과 이를 알선하는 일은 모두 금지됩니다.","자격 취득은 국내에 거주하게 된 날, 수급권자이었던 사람은 그 대상자에서 제외된 날 / 피부양자이었던 사람은 그 자격을 잃은 날 / 유공자등 의료보호대상자이었던 사람은 제외된 날, 사용자·세대주는 취득일부터 14일 이내 보험자에게 신고":"국내에 거주하게 된 날부터 자격을 얻고 수급권자나 피부양자였던 사람은 그 자격이 끝난 날부터 얻습니다.","자격 취소(시·도지사)는 결격사유 해당 / 금지행위 위반 처벌 / 거짓·부정 취득은 반드시 취소, 영리 목적 불필요 요양서비스 알선·유인 / 자격증 대여·양도·위조는 임의 취소(청문 필수)":"결격사유나 거짓 취득은 반드시 취소하고 알선·유인이나 자격증 대여 등은 재량으로 취소합니다.","자립·자활 노력, 보호가 필요한 사람에게 지속적 관심과 사회환경 조성 협력, 관계 법령에 따른 비용 부담·정보 제공 등 정책 협력":"국민은 자립과 자활에 힘쓰고 도움이 필요한 사람에게 관심을 두며 비용 부담과 정보 제공 등으로 협력할 책임이 있습니다.","자립 지원, 사회참여·자아실현에 필요한 제도와 여건 조성으로 사회통합과 행복한 복지사회 실현":"자립을 돕고 사회참여와 자아실현에 필요한 제도와 여건을 마련해 사회통합과 행복한 복지사회를 이루는 것이 이념입니다.","자립지원계획은 보장원장 가정위탁지원센터장 아동복지시설의 장이 보호하고 있는 15세 이상의 아동을 대상으로 매년 개별 자립지원계획을 수립":"보장원장 등은 보호하고 있는 15세 이상의 아동을 대상으로 매년 개별 자립지원계획을 세웁니다.","자립지원 대상은 가정위탁보호 중인 사람 / 아동복지시설 보호 중인 사람 / 보호조치 종료·퇴소 후 5년이 지나지 않은 사람 / 18세 전 종료·퇴소자로 보건복지부장관이 인정한 사람":"가정위탁이나 시설에서 보호 중인 사람과 보호 종료 후 5년이 안 된 사람 등이 자립지원 대상입니다.","자립지원 조치는 교육·주거·생활·의료 지원 / 자립정착금·자립수당 / 진로·직업 상담 및 취업 지원 / 자산형성지원 / 실태조사·연구 / 사후관리체계 / 심리 상담":"교육과 주거와 생활과 의료 지원과 자립정착금과 자립수당과 취업 지원과 자산형성 지원 등이 있습니다.","자원봉사센터는 최저기준 마련 대상이 아님":"자원봉사센터는 서비스 최저기준 마련 대상이 되는 시설이 아닙니다.","자원봉사자 보호는 안전한 환경 노력 / 보험 가입 등, 자원봉사센터는 국가기관·지방자치단체가 설치할 수 있고 법인으로 운영하거나 비영리법인에 위탁":"안전한 환경을 만들고 보험에 가입하는 방법으로 자원봉사자를 보호하며 센터는 공공이 설치하거나 위탁할 수 있습니다.","자원봉사자의 날은 매년 12월 5일, 그날부터 1주일간이 자원봉사주간":"자원봉사자를 기리는 날이 12월 5일이고 그날에서 일주일이 활동 주간입니다.","자원봉사진흥위원회는 행정안전부장관 소속, 정책 방향 / 국가기본계획과 연도별 시행계획 / 제도 개선을 심의":"행정안전부장관 소속 위원회로 정책 방향과 국가기본계획과 제도 개선을 심의합니다.","자원봉사활동에 관한 기본적인 사항을 규정해 자원봉사활동을 진흥하고 행복한 공동체 건설에 이바지":"자원봉사활동기본법은 기본 사항을 정해 자원봉사를 진흥하고 행복한 공동체를 만드는 데 이바지하려는 법입니다.","자원봉사활동은 개인 또는 단체가 지역사회·국가 및 인류사회를 위하여 대가 없이 자발적으로 시간과 노력을 제공하는 행위, 자원봉사센터는 개발·장려·연계·협력 사업을 수행하는 기관·법인·단체":"자원봉사는 대가 없이 자발적으로 시간과 노력을 제공하는 행위이고 자원봉사센터는 개발·장려·연계 사업을 합니다.","자원봉사활동의 범위 15가지는 사회복지·보건 증진 / 지역사회 개발 / 환경보전 / 취약계층 권익·청소년 육성 / 교육·상담 / 인권 옹호·평화 / 범죄 예방·선도 / 교통질서·기초질서 / 재난 관리·재해 구호 / 문화·관광·예술·체육 / 부패 방지·소비자 보호 / 공명선거 / 국제협력·국외봉사 / 공공행정 사무 지원 / 그 밖의 공익사업":"자원봉사 범위는 사회복지와 보건과 지역개발과 환경과 교육과 인권과 범죄 예방 등 열다섯 가지입니다.","자의입원등은 정신질환자 등이 신청서를 제출해 입원등을 할 수 있고 퇴원 신청 시 지체 없이 퇴원시켜야 하며 입원일부터 2개월마다 퇴원 의사를 확인":"정신질환자가 직접 신청해 입원하고 퇴원 신청 시 지체 없이 퇴원시키며 입원일부터 2개월마다 퇴원 의사를 확인합니다.","자활기업은 수급자 및 차상위자가 상호 협력하여 설립, 요건은 조합 또는 부가가치세법상 사업자 형태 / 수급자 또는 차상위자를 2인 이상 포함 / 보건복지부장관이 정하는 운영기준, 보장기관의 인정을 받아야 함":"자활기업은 수급자와 차상위자가 협력해 설립하며 조합이나 사업자 형태에 2인 이상이 포함되어야 하고 보장기관의 인정을 받습니다.","자활기업 지원은 자활을 위한 사업자금 융자 / 국유지·공유지 우선 임대 / 국가·지방자치단체 사업 우선 위탁 / 경영·세무 교육 및 컨설팅 / 그 밖의 사업":"자활기업에는 사업자금 융자와 국유지·공유지 우선 임대와 사업 우선 위탁과 경영·세무 교육 등을 지원합니다.","자활에 필요한 금품의 지급 또는 대여 / 근로능력 향상 및 기능습득 지원 / 취업알선 등 정보 제공 / 자활을 위한 근로기회 제공 / 시설 및 장비의 대여 / 창업교육 기능훈련 기술·경영 지도 등 창업지원 / 자산형성 지원 / 그 밖에 대통령령으로 정하는 지원":"자활급여는 금품 지급과 기능습득 지원과 취업알선과 근로기회 제공과 장비 대여와 창업지원과 자산형성 지원 등 여러 가지입니다.","자활지원사업 통합정보전산망 사용 시 수행기관은 보건복지부장관에게 사용을 요청하고 개인정보 보호대책(보안교육 등)을 마련하여야 한다":"전산망을 쓰려는 수행기관은 보건복지부장관에게 요청하고 보안교육 같은 개인정보 보호대책을 마련해야 합니다.","장기요양급여는 6개월 이상 동안 혼자서 일상생활을 수행하기 어렵다고 인정되는 자에게 신체활동·가사활동 지원 또는 간병 등의 서비스나 이에 갈음하는 현금 등 (1개월 이상은 오답)":"장기요양급여는 6개월 이상 혼자 일상생활이 어려운 사람에게 활동 지원이나 간병 또는 이에 갈음하는 현금을 주는 급여입니다.","장기요양급여심사위원회는 공단에 두며 위원장 포함 10명 이하":"급여 심사를 위한 위원회로 공단에 두며 위원장 포함 10명 이하입니다.","장기요양기관은 지정을 받아 장기요양급여를 제공하는 기관, 장기요양요원은 기관에 소속되어 신체활동·가사활동 지원 등을 수행하는 자":"지정을 받아 급여를 제공하는 곳이 장기요양기관이고 그 기관에 속해 일하는 사람이 장기요양요원입니다.","장기요양기관 의무는 급여 제공 거부 금지(정원 여유 없음 등 정당한 사유 예외) / 제공 기준에 따른 제공 / 명세서 교부 / 자료 기록·관리 / 영리 목적 본인부담금 면제·감경 금지 / 영리 목적 수급자 소개·알선·유인 금지":"기관은 급여 제공을 거부할 수 없고 제공 기준을 지키며 명세서를 교부하고 영리 목적의 본인부담금 면제를 해서는 안 됩니다.","장기요양기관 지정은 재가급여 또는 시설급여를 제공하려는 자는 시설·인력을 갖춰 소재지 관할 시장·군수·구청장의 지정을 받아야 한다, 지정 유효기간은 6년":"재가급여나 시설급여를 하려는 자는 시설과 인력을 갖춰 시장·군수·구청장의 지정을 받아야 하며 유효기간은 6년입니다.","장기요양기본계획은 보건복지부장관이 5년 단위로 수립·시행, 연도별 급여 대상인원 및 재원조달 계획 / 장기요양기관·전문인력 관리 방안 / 장기요양요원 처우 / 그 밖의 사항, 지방자치단체의 장은 세부시행계획 수립":"장관이 5년 단위로 수립하며 연도별 대상 인원과 재원 계획과 기관 및 전문인력 관리 방안 등을 담습니다.","장기요양보험료는 건강보험료와 통합 징수(구분하여 고지)하고 각각 독립회계로 관리, 보험료율은 장기요양위원회 심의를 거쳐 대통령령으로 정함":"장기요양보험료는 건강보험료와 합쳐 걷되 따로 고지하고 회계는 각각 독립적으로 관리합니다.","장기요양보험사업은 보건복지부장관이 관장하고 보험자는 국민건강보험공단, 가입자는 국민건강보험법상 가입자":"주무 부처는 보건복지부이고 운영 주체인 보험자는 건강보험공단이며 가입자도 건강보험과 같은 사람들입니다.","장기요양사업은 장기요양보험료·국가 및 지방자치단체 부담금 등을 재원으로 노인등에게 장기요양급여를 제공하는 사업":"돈은 보험료와 공공 부담금에서 나오고 그 재원으로 서비스를 대는 일 전체를 장기요양사업이라 부릅니다.","장기요양요원지원센터는 국가와 지방자치단체가 설치·운영할 수 있다, 업무는 요원의 권리 침해에 관한 상담 및 지원 / 역량강화 교육지원 / 건강검진 등 건강관리 사업 / 그 밖의 대통령령 사항":"요원의 권리 침해 상담과 역량강화 교육과 건강관리 지원을 하는 센터로 국가나 지방자치단체가 설치합니다.","장기요양위원회는 보건복지부장관 소속, 심의 사항은 보험료율 / 가족요양비·특례요양비·요양병원간병비 지급기준 / 재가 및 시설 급여비용 / 그 밖의 주요 사항, 위원장 1인 부위원장 1인 포함 16~22인, 위원장은 보건복지부차관, 임기 3년":"장기요양위원회는 보건복지부장관 소속으로 보험료율과 특별현금급여 지급기준과 급여비용을 심의합니다.","장기요양인정서는 등급판정위원회가 심의를 완료하면 공단이 지체 없이 장기요양등급 / 급여의 종류 및 내용 등을 포함한 인정서를 작성해 수급자에게 송부하고 월 한도액 범위 안에서 개인별장기요양이용계획서를 함께 송부":"판정이 끝나면 공단이 지체 없이 등급과 급여 종류와 내용을 담은 인정서를 만들어 수급자에게 보냅니다.","장례비는 업무상 사유로 사망한 경우 평균임금의 120일분을 장례를 지낸 유족에게 지급(고시 최고·최저 금액 범위), 유족이 없으면 실제 장례를 지낸 사람에게 실비":"장례비는 평균임금의 120일분을 장례를 지낸 유족에게 주고 유족이 없으면 실제 장례를 지낸 사람에게 실비를 줍니다.","장애결정 기준일은 초진일부터 1년 6개월이 지나기 전에 완치일이 있으면 완치일, 1년 6개월까지 완치일이 없으면 1년 6개월이 되는 날의 다음 날":"초진일부터 1년 6개월 안에 완치되면 완치일, 아니면 1년 6개월이 되는 날의 다음 날을 장애 결정 기준일로 삼습니다.","장애상태는 장애등급 1급 또는 2급에 해당하는 상태이거나 장애인복지법상 장애의 정도가 심한 장애인으로 대통령령이 정하는 상태":"장애상태는 장애등급 1급이나 2급이거나 장애인복지법상 장애 정도가 심한 사람으로 대통령령이 정하는 상태입니다.","장애수당은 장애 정도와 경제적 수준을 고려해 지급할 수 있다, 기초생활보장법상 생계급여·의료급여 수급 장애인에게는 반드시 지급, 장애인연금법상 중증장애인에게는 지급하지 않는다":"장애수당은 장애 정도와 경제 수준을 보아 줄 수 있고 생계·의료급여 수급 장애인에게는 반드시 지급합니다.","장애실태조사는 보건복지부장관이 3년마다 실시(5년 아님)":"실태조사의 주기는 3년이고 조사 주체는 보건복지부장관이라는 내용입니다.","장애아동수당과 보호수당은 국가와 지방자치단체가 지급할 수 있다, 생계·의료급여 수급 장애아동에게는 장애아동수당을 지급하여야 한다":"장애아동수당과 보호수당은 공공이 지급할 수 있고 생계·의료급여 수급 장애아동에게는 장애아동수당을 줘야 합니다.","장애인 거주시설의 서비스 최저기준은 보건복지부장관이 마련하여야 하고 시설 운영자는 최저기준 이상으로 유지하여야 한다(시설의 장이 마련하는 것 아님)":"거주시설의 최저기준은 보건복지부장관이 마련하고 운영자는 그 이상을 유지해야 하며 시설의 장이 만드는 것이 아닙니다.","장애인권익옹호기관은 중앙은 국가가 설치·운영하여야 하고 지역은 시·도에 1개소 이상 둔다, 지역기관은 학대 신고접수·현장조사·응급보호 / 상담·사후관리 / 예방교육·홍보 / 장애인학대사례판정위원회 운영":"중앙기관은 국가가 설치하고 지역기관은 시·도에 1개소 이상 두며 학대 신고접수와 현장조사와 응급보호를 합니다.","장애인 등록은 장애인·법정대리인 등이 시장·군수·구청장에게 등록하면 장애인등록증을 교부, 등록증은 양도·대여 금지":"장애인이나 법정대리인이 시장·군수·구청장에게 등록하면 등록증을 받으며 등록증은 양도하거나 빌려줄 수 없습니다.","장애인복지상담원은 시·군·구에 둔다":"상담원이 배치되는 곳은 광역이 아니라 시·군·구 단위의 기초 지방자치단체입니다.","장애인복지시설 5가지는 장애인 거주시설 / 장애인 지역사회재활시설 / 장애인 자립생활지원시설 / 장애인 직업재활시설 / 장애인 의료재활시설 / 그 밖의 대통령령 시설":"장애인복지시설은 거주시설과 지역사회재활시설과 자립생활지원시설과 직업재활시설과 의료재활시설입니다.","장애인연금법(2010) / 기초연금법(2014)":"2010년대에는 장애인연금법이 2010년, 기초연금법이 2014년에 제정되었습니다.","장애인은 신체적·정신적 장애로 오랫동안 일상생활이나 사회생활에서 상당한 제약을 받는 자, 이 법 적용 장애인은 대통령령이 정하는 종류·기준에 해당하는 자":"장애인은 신체적 또는 정신적 장애로 오랫동안 일상생활에 상당한 제약을 받는 사람이며 대통령령이 정한 종류와 기준에 맞아야 합니다.","장애인의 권리는 인간으로서 존엄과 가치 존중 / 모든 분야의 활동 참여 / 장애인 관련 정책결정과정에 우선적으로 참여":"장애인은 존엄과 가치를 존중받고 모든 분야에 참여하며 정책 결정 과정에 우선적으로 참여할 권리가 있습니다.","장애인의 날은 매년 4월 20일(5월 20일 아님) / 장애인 주간은 그날부터 1주간":"장애인의 날은 매년 4월 20일이고 5월 20일이 아니며 그날부터 1주간이 장애인 주간입니다.","장애인의 인간다운 삶과 권리보장을 위한 국가와 지방자치단체 등의 책임을 명백히 하고 의료·교육·직업재활·생활환경 개선 등 사업을 정해 사회통합에 이바지":"장애인복지법은 장애인의 인간다운 삶을 위한 공공의 책임을 밝히고 의료·교육·직업재활 사업을 정해 사회통합을 이루려는 법입니다.","장애인정책조정위원회는 국무총리 소속(보건복지부장관 소속 아님)":"장애인 정책을 조정하는 위원회의 소속은 국무총리실 쪽이고 보건복지부가 아니라는 구분입니다.","장애인정책종합계획은 보건복지부장관이 관계 중앙행정기관의 장과 협의하여 5년마다 수립·시행(3년 아님), 장애인정책조정위원회 심의를 미리 거쳐야 하고 추진성과를 매년 평가":"종합계획은 장관이 관계 기관과 협의해 5년마다 세우며 3년이 아니고 정책조정위원회 심의를 미리 거쳐야 합니다.","장애인 지원 시책은 장애발생 예방 / 의료와 재활치료 / 사회적응 훈련 / 교육 / 직업 / 정보 접근 / 편의시설 / 경제적 부담 경감(세제 조치 이용료 감면) 등":"장애 예방과 의료·재활과 교육과 직업과 정보 접근과 편의시설과 경제적 부담 경감 등의 시책을 둡니다.","장애인 특례는 등록장애인인 가입자 및 피부양자에게 보조기기에 대해 보험급여를 할 수 있다":"등록장애인 가입자와 피부양자에게는 보조기기에 대해서도 보험급여를 할 수 있습니다.","장애인학대는 신체적·정신적·정서적·언어적·성적 폭력이나 가혹행위 경제적 착취 유기 또는 방임 (경제적 착취도 학대에 포함)":"장애인학대는 신체적·정신적·정서적·언어적·성적 폭력과 가혹행위와 경제적 착취와 유기·방임을 포함합니다.","장애인학대 신고는 누구든지 신고할 수 있다, 직무상 알게 된 신고의무자(사회복지전담공무원 사회복지시설 종사자 활동지원인력 의료인 119구급대원 어린이집 교직원 학교 종사자 등 25종)는 지체 없이 장애인권익옹호기관 또는 수사기관에 신고":"누구든 장애인학대를 신고할 수 있고 직무상 알게 된 사회복지전담공무원 등은 신고해야 합니다.","장애 정도가 심한 장애인 등 필요한 경우 개인 단위로 실시할 수 있다":"장애 정도가 심한 사람처럼 필요한 경우에는 개인 단위로 실시할 수 있습니다.","장제급여는 생계·주거·의료급여 중 하나 이상을 받는 수급자가 사망한 경우 검안 운반 화장 또는 매장 등 장제조치를 실시(자활급여 수급자 사망 아님), 실제 장제를 실시하는 사람에게 비용 지급":"장제급여는 생계·주거·의료급여 수급자가 사망했을 때 검안과 운반과 화장 등을 하며 자활급여 수급자의 사망은 아닙니다.","장해급여는 업무상 사유로 부상·질병에 걸려 치유된 후 장해가 있는 경우, 장해등급에 따라 장해보상연금 또는 장해보상일시금(수급권자 선택), 노동력 완전상실 등급은 연금 지급 / 외국 거주 외국인은 일시금":"치유 뒤 장해가 남으면 장해등급에 따라 연금이나 일시금을 선택하고 노동력을 완전히 잃은 등급은 연금으로 줍니다.","장해는 부상 또는 질병이 치유되었으나 정신적 또는 육체적 훼손으로 노동능력이 상실되거나 감소된 상태":"치유된 뒤에도 정신적 또는 육체적 훼손이 남아 노동능력이 없어지거나 줄어든 상태입니다.","장해보상연금은 신청하면 최초 1년분 또는 2년분의 2분의 1을 미리 지급할 수 있다(100분의 5 범위 이자 공제)":"연금을 신청하면 처음 1년분이나 2년분의 2분의 1을 먼저 받을 수 있고 100분의 5 범위 이자를 뺍니다.","장해특별급여·유족특별급여는 보험가입자의 고의 또는 과실로 발생한 재해에서 수급권자가 민법상 손해배상 청구에 갈음하여 청구하면 지급, 근로자와 보험가입자 사이 합의가 있어야 하며 지급 후 동일 사유로 손해배상 청구 불가, 공단이 급여액 모두를 보험가입자에게서 징수":"사업주의 잘못으로 생긴 재해는 민법상 손해배상 대신 특별급여를 청구할 수 있고 근로자와 사업주 합의가 필요합니다.","재가급여 6가지는 ① 방문요양 ② 방문목욕 ③ 방문간호 ④ 주·야간보호 ⑤ 단기보호 ⑥ 기타재가급여(일상생활·신체활동 지원 및 인지기능 유지·향상에 필요한 용구 제공이나 가정 방문 재활 지원 등) (특별현금급여는 재가급여가 아님)":"재가급여는 방문요양과 방문목욕과 방문간호와 주·야간보호와 단기보호와 기타재가급여입니다.","재가노인복지시설 서비스는 방문요양서비스 / 주·야간보호서비스 / 단기보호서비스 / 방문 목욕서비스 / 그 밖의 서비스":"재가노인복지시설은 방문요양과 주·야간보호와 단기보호와 방문목욕 같은 서비스를 합니다.","재가복지서비스는 가정봉사서비스(가사·개인활동 지원·정서활동 지원)와 주간·단기 보호서비스, 시설 입소에 우선하여 제공하여야 한다":"재가복지서비스는 가정봉사와 주간·단기 보호서비스로 구성되며 시설 입소보다 먼저 제공해야 합니다.","재산을 취득하면 지체 없이 법인 재산으로 편입하고 취득 사유·종류·수량·가액을 매년 시·도지사에게 보고":"재산을 얻으면 지체 없이 법인 재산으로 편입하고 취득 내용을 매년 시·도지사에게 보고합니다.","재산의 소득환산액은 (재산가액 - 기본재산액 - 부채) x 소득환산율, 재산 범위는 일반재산 금융재산 자동차":"재산의 소득환산액은 재산가액에서 기본재산액과 부채를 빼고 소득환산율을 곱해 구합니다.","재심사청구는 결정통지를 받은 날부터 90일 이내 보건복지부장관 소속 장기요양재심사위원회(위원장 포함 20인 이내 공무원 아닌 위원이 과반수)":"결정 통지를 받은 날부터 90일 이내에 보건복지부장관 소속 재심사위원회에 청구하며 공무원이 아닌 위원이 과반수입니다.","재심사 청구는 심사 청구 결정에 불복하면 고용노동부 산업재해보상보험재심사위원회(위원장 포함 90명 이내)에 결정을 안 날부터 90일 이내, 판정위원회 심의를 거친 결정은 심사 청구 없이 곧바로 재심사 청구 가능":"심사 결정에 불복하면 90일 이내에 재심사위원회에 청구하며 판정위원회를 거친 결정은 일부 특례가 있습니다.","재외동포 및 외국인 중 국내거소신고자 / 재외국민 주민등록자 / 영주 체류자격 외국인등록자 / 결혼이민자 / 난민인정자는 장애인 등록 가능 (난민인정자 포함)":"국내거소신고자와 재외국민 주민등록자와 영주권 외국인과 결혼이민자와 난민인정자도 장애인으로 등록할 수 있습니다.","재원 사용은 해당 회계연도 지출이 원칙이고 재난·긴급구호 대비 적립과 이사회 의결 이월 가능, 모금 및 관리·운영 비용은 직전 회계연도 모금총액의 100분의 10 범위에서 이사회 의결로 사용":"원칙은 그해 안에 지출하는 것이나 긴급구호 적립이나 이사회 의결이 있으면 이월이 가능하고 운영비는 모금총액의 100분의 10 범위입니다.","재원은 국고보조금 / 지방자치단체 출연금 / 상환받은 대지급금 / 부당이득금 / 과징금 / 결산상 잉여금 및 그 밖의 수입금":"기금의 재원에는 국고보조금과 지자체 출연금과 상환받은 대지급금과 부당이득금과 과징금 등이 모입니다.","재원은 사회복지공동모금 기부금품 / 법인·단체 출연 현금·물품 / 복권수익금 / 그 밖의 수입금":"재원은 기부금품과 법인·단체 출연금과 복권수익금과 그 밖의 수입금입니다.","재의 요구 후 재적의원 과반수 출석과 출석의원 3분의 2 이상의 찬성으로 전과 같이 의결하면 법률로 확정된다":"다시 의결할 때 재적 과반수 출석에 출석의원 3분의 2 이상이 찬성하면 법률로 확정됩니다.","재정운영위원회는 공단에 두고 요양급여비용 계약 결손처분 등 보험재정 사항을 심의·의결, 직장가입자 대표 10명 / 지역가입자 대표 10명 / 공익대표 10명, 위원 임기 2년":"재정운영위원회는 공단에 두고 직장가입자·지역가입자·공익 대표 각 10명으로 구성해 보험재정 사항을 심의·의결합니다.","재정 형편 등을 고려해 협의·조정 가능":"국가와 지방자치단체는 재정 사정을 보아 책임 분담을 협의하고 조정할 수 있습니다.","저소득 근로자 휴업급여는 1일당 지급액이 최저 보상기준 금액의 100분의 80 이하이면 평균임금의 100분의 90(상한 최저 보상기준 금액의 100분의 80), 최저임금액 미만이면 최저임금액":"저소득자는 휴업급여가 너무 낮지 않도록 평균임금의 100분의 90까지 올리고 최저임금액 미만이면 최저임금액을 줍니다.","적용 제외는 소정근로시간이 대통령령 시간 미만인 근로자 / 국가공무원·지방공무원(별정직·임기제는 본인 의사로 가입 가능) / 사립학교교직원 연금법 적용자 / 그 밖의 대통령령 정하는 사람, 65세 이후 고용되거나 자영업을 개시한 사람에게는 실업급여 규정을 적용하지 않음":"정해진 시간 미만으로 일하는 근로자와 공무원과 사립학교교직원연금 적용자 등은 적용에서 제외되며 별정직 등은 원하면 가입합니다.","적정성 심사 후 부정한 방법이면 지체 없이 지원 중단 및 비용 환수(필요적)":"심사 결과 부정한 방법이 드러나면 반드시 지원을 중단하고 비용을 환수해야 합니다.","적정성 평가는 보건복지부장관이 5년마다 기초연금 수급권자의 생활수준 소득재분배급여 변동률 물가변동률 등을 종합 고려해 평가하고 기준연금액을 조정, 노인 빈곤 실태조사와 재정 소요 전망을 함께 실시":"장관이 5년마다 수급권자의 생활수준과 물가 등을 종합해 평가하고 기준연금액을 조정하며 노인 빈곤 실태조사도 함께 합니다.","적정성 확인조사와 변동신고에 따라 직권 또는 신청으로 종류·지급방법을 변경할 수 있고 급여가 필요 없게 되면 중지·변경하여야 한다":"조사와 신고 결과에 따라 급여의 종류나 지급방법을 바꿀 수 있고 급여가 필요 없어지면 중지하거나 변경해야 합니다.","적정하지 않으면 중단·환수 가능(임의적)":"부정은 아니어도 지원이 적정하지 않으면 중단하거나 환수할 수 있습니다.","전담기구는 특별자치시장·시장·군수·구청장이 업무 효율을 위해 별도 설치할 수 있고 사회보장정보시스템을 활용해 종합 안내":"시장·군수·구청장은 업무 효율을 위해 별도 전담기구를 둘 수 있고 시스템으로 종합 안내를 합니다.","전문인력 양성, 학술 조사·연구, 국제 교류 증진에 노력":"센터는 전문인력을 길러 내고 조사와 연구를 하며 국제 교류를 늘리도록 노력합니다.","정관 변경은 시·도지사의 인가(경미한 사항은 제외)":"정관을 바꿀 때는 시·도지사의 인가를 받으며 경미한 사항은 제외합니다.","정관 필수 기재 10가지는 목적 / 명칭 / 주된 사무소 소재지 / 사업 / 임원 및 직원 / 이사회 / 지회의 구성 및 운영 / 재산 및 회계 / 공고 / 정관 변경":"정관에는 목적과 명칭과 사무소와 사업과 임원과 이사회와 지회와 재산과 공고와 변경이 들어갑니다.","정기 또는 기간을 정해 급여를 받는 수급자는 거주지·세대원·소득·재산·근로능력·다른 급여 수급이력 등이 변동되면 지체 없이 신고":"정기적으로 급여를 받는 수급자는 거주지와 소득, 재산 등이 달라지면 지체 없이 신고해야 합니다.","정기 평가 후 자활촉진을 달성하지 못하면 지정 취소 가능":"정기 평가에서 자활촉진을 달성하지 못하면 센터의 지정을 취소할 수 있습니다.","정당한 권한이 있는 기관에 서면으로 통지하여 포기할 수 있다(구두 통지는 안 됨)":"수급권을 포기하려면 권한 있는 기관에 서면으로 알려야 하며 구두 통지만으로는 안 됩니다.","정당한 사유로 기간 내 못한 경우 사유가 소멸한 때부터 60일 이내":"정당한 사유로 기간을 놓쳤다면 그 사유가 없어진 날부터 60일 안에 이의신청을 할 수 있습니다.","정당한 이유 없이 의료급여를 거부하지 못한다":"의료급여기관은 정당한 이유 없이 의료급여를 거부할 수 없습니다.","정보주체의 사전 동의를 받아야 한다":"정보를 쓰려면 당사자인 정보주체의 사전 동의를 받아야 합니다.","정부는 설립·운영에 필요한 비용을 출연하거나 지원할 수 있다":"정부는 정보원을 세우고 운영하는 데 드는 비용을 출연하거나 지원할 수 있습니다.","정부지원은 국가는 매년 보험료 예상 수입액의 100분의 14에 상당하는 금액을 국고에서 공단에 지원, 국민건강증진기금에서도 지원받을 수 있다":"국가는 매년 보험료 예상 수입의 100분의 14에 해당하는 돈을 공단에 지원하고 국민건강증진기금에서도 받을 수 있습니다.","정신건강복지센터는 정신건강증진시설·사회복지시설·학교·사업장과 연계해 지역사회 정신건강증진사업을 하는 국가·지방자치단체 설치 기관이나 위탁 기관":"센터는 시설과 학교와 사업장 등과 연계해 지역사회 정신건강증진사업을 하는 공공 또는 위탁 기관입니다.","정신건강증진시설은 정신의료기관 / 정신요양시설 / 정신재활시설":"의료를 맡는 곳과 요양을 맡는 곳과 사회복귀를 돕는 곳 세 가지가 정신건강증진시설입니다.","정신질환자는 망상·환각·사고나 기분의 장애 등으로 독립적으로 일상생활을 영위하는 데 중대한 제약이 있는 사람":"정신질환자의 정의는 증상의 이름보다 독립적으로 일상을 꾸리기 어려운 정도에 무게를 둡니다.","제1차(개설신고 의료기관 + 보건소 등 + 약국) / 제2차(개설허가 의료기관) / 제3차(제2차 중 보건복지부장관이 지정)":"의료급여기관은 1차는 신고 의료기관과 보건소와 약국, 2차는 허가 의료기관, 3차는 2차 중 장관이 지정한 곳입니다.","제1호(거짓·부정한 방법으로 허가)와 제7호(설립 후 기본재산 미출연)는 반드시 취소":"거짓으로 허가를 받은 경우와 설립 후 기본재산을 내지 않은 경우는 반드시 취소하는 사유입니다.","제1호~제3호는 반드시 취소":"앞의 세 사유에 해당하면 재량 없이 반드시 취소해야 합니다.","제3자의 불법행위로 피해를 입은 국민이 수급권을 가지게 된 경우, 사회보장제도를 운영하는 자는 책임 있는 자에게 관계 법령에 따라 구상권을 행사할 수 있다":"제3자의 잘못으로 다친 국민에게 급여를 준 제도 운영자는 책임 있는 제3자에게 비용을 청구할 수 있습니다.","제공 여부와 유형을 결정하되 이미 제공받는 급여와 보장내용이 중복되지 않게 하고 서면으로 통지":"급여 제공 여부와 종류를 정하되 이미 받는 급여와 겹치지 않게 하며 서면으로 알립니다.","제외 대상은 고용 기간 1개월 미만 일용근로자 / 현역병·전환복무자·군간부후보생 / 선거로 취임하는 무보수 공무원 / 대통령령이 정하는 사업장의 근로자 등":"고용 기간이 1개월 미만인 일용근로자와 현역병과 무보수 선출직 공무원 등은 직장가입자에서 제외됩니다.","제외 대상은 별도 소득 없는 배우자(가입 제외자 사업장·지역·임의계속가입자 노령연금 수급권자 퇴직연금등수급권자의 배우자) / 퇴직연금등수급권자 / 18세 이상 27세 미만 학생·군 복무 등 소득 없는 자 / 생계급여·의료급여 수급자 / 1년 이상 행방불명자":"별도 소득이 없는 배우자와 퇴직연금 수급권자와 소득 없는 학생과 군 복무자 등은 지역가입자에서 제외됩니다.","제한·정지하는 경우에도 그 목적에 필요한 최소한의 범위에 그쳐야 한다":"제한하거나 정지할 때도 목적에 필요한 최소한의 범위를 넘어서는 안 됩니다.","조기노령연금액 비율은 55세 1천분의 700 / 56세 760 / 57세 820 / 58세 880 / 59세 940 (청구가 연령 도달 다음 달 이후이면 1개월마다 1천분의 5 가산)":"조기노령연금은 55세부터 59세까지 나이가 낮을수록 비율이 줄어 55세는 1천분의 700이고 청구가 늦으면 1개월마다 1천분의 5를 더합니다.","조기노령연금은 가입기간 10년 이상 55세 이상인 자가 소득 있는 업무에 종사하지 않으면 본인이 희망하는 경우 60세 전에 청구해 받을 수 있다":"10년 이상 가입하고 55세 이상이면서 소득 업무에 종사하지 않을 때 원하면 60세 전에도 미리 받을 수 있습니다.","조기노령연금 지급 정지는 60세 미만 수급자가 소득 있는 업무에 종사하거나 본인이 정지를 신청하면 정지, 60세 도달 시 등 재지급":"60세 미만 수급자가 소득 업무에 종사하거나 정지를 신청하면 지급이 멈추고 60세 도달 시 등 다시 지급합니다.","조기재취업 수당은 수급자격자가 안정된 직업에 재취직하거나 스스로 영리 사업을 영위하는 경우 대통령령 기준에 해당하면 지급, 금액은 소정급여일수 중 미지급일수 비율에 따라 산정":"안정된 직업에 재취직하거나 스스로 사업을 시작하면 지급하며 미지급 일수 비율에 따라 금액을 정합니다.","조례는 규칙보다 상위 법규범이다":"조례는 지방의회가 만들어 규칙보다 한 단계 위에 놓이는 법규범입니다.","조례와 규칙은 특별한 규정이 없으면 공포한 날부터 20일이 지나면 효력이 발생한다":"시행일을 따로 두지 않았다면 지방자치단체의 규범도 공포 뒤 20일째에 효력이 생깁니다.","조사는 공단이 신청서를 접수하면 소속 직원으로 하여금 신청인의 심신상태와 필요한 급여 종류·내용 등을 조사하게 하여야 한다, 2명 이상이 조사하도록 노력":"공단은 신청을 받으면 직원이 신청인의 심신 상태와 필요한 급여를 조사하게 하며 2명 이상이 조사하도록 노력합니다.","조사·자료제출 요구를 2회 이상 거부·방해·기피하면 급여신청을 각하할 수 있다":"두 번 이상 조사에 협조하지 않으면 심사를 이어 가지 않고 신청을 각하할 수 있습니다.","조사 후 지체 없이 급여 실시 여부와 내용을 결정, 신청일부터 30일 이내 서면 통지, 부양의무자 조사에 시일이 걸리는 특별 사유나 조사 거부 시 60일 이내 통지 가능":"조사 뒤 신청일부터 30일 이내에 서면으로 통지하되 특별한 사유나 조사 거부가 있으면 60일 이내까지 가능합니다.","종류 14가지는 아동양육시설 / 아동일시보호시설 / 아동보호치료시설 / 공동생활가정 / 자립지원시설 / 아동상담소 / 아동전용시설 / 지역아동센터 / 협동돌봄센터 / 아동보호전문기관 / 가정위탁지원센터 / 보장원 / 자립지원전담기관 / 학대피해아동쉼터 (다함께돌봄센터는 별도 규정)":"아동복지시설은 아동양육시설과 일시보호시설과 보호치료시설과 공동생활가정과 지역아동센터 등 14가지입니다.","주거가 없거나 목적 달성이 불가능하거나 수급자가 희망하면 보장시설이나 타인의 가정에 위탁 실시":"거처가 없거나 수급자가 원하면 보장시설이나 타인의 가정에 맡겨서 급여를 실시합니다.","주거급여는 임차료 수선유지비 그 밖의 수급품을 지급(주택 매입비 아님), 필요한 사항은 따로 법률(주거급여법)에서 정함":"주거급여는 임차료와 수선유지비 등을 지급하고 주택 매입비는 아니며 세부 사항은 주거급여법에 따릅니다.","주거지원·사회복지시설 이용 지원·그 밖의 지원 1개월":"주거지원과 시설 이용 지원과 그 밖의 지원은 한 번에 1개월 동안 합니다.","주민은 조례 제정을 청구할 수 있다":"주민은 필요한 조례를 만들어 달라고 지방자치단체에 청구할 권리가 있습니다.","주민의 권리 제한·의무 부과나 벌칙은 법률의 위임이 있어야 한다":"주민에게 의무를 지우거나 권리를 제한하거나 벌칙을 두려면 법률의 위임이 있어야 합니다.","주민의 복지증진과 삶의 질 향상을 위해 지역사회 차원에서 전개하는 사회복지":"지역사회복지는 주민의 복지와 삶의 질을 높이려고 지역사회 차원에서 펼치는 사회복지입니다.","주·야간보호는 수급자를 하루 중 일정 시간 기관에 보호하며 신체활동 지원과 심신기능 유지·향상 교육·훈련 제공 / 단기보호는 보건복지부령 범위에서 일정 기간 기관에 보호(둘 다 재가급여이고 시설급여가 아님)":"주·야간보호는 하루 중 일정 시간 기관에서 돌보고 단기보호는 일정 기간 기관에서 보호합니다.","중복급여 조정은 둘 이상 수급권이 생기면 수급권자 선택으로 하나만 지급, 선택하지 않은 유족연금이면 유족연금액의 100분의 30을 추가 지급":"급여 사유가 겹치면 수급권자가 하나를 골라 받고 유족연금을 고르지 않으면 그 100분의 30을 추가로 줍니다.","중앙노인보호전문기관은 국가가 지역 간 연계체계를 구축하고 노인학대를 예방하기 위해 설치·운영하여야 한다, 노인인권보호 정책제안 / 연구·프로그램 개발 / 홍보·교육자료 / 실적 취합 / 지역기관 관리·업무지원 / 상담원 심화교육 / 협력체계 / 중앙노인학대사례판정위원회 운영":"중앙기관은 국가가 설치·운영하며 지역 간 연계체계를 만들고 학대 예방 정책 제안과 연구를 맡습니다.","중앙위원회 심의 사항은 의료급여사업의 기본방향 및 대책 / 의료급여의 기준 및 수가 / 그 밖에 보건복지부장관 또는 위원장이 부의하는 사항":"중앙위원회는 의료급여사업의 기본방향과 대책과 의료급여의 기준 및 수가를 심의합니다.","중앙행정기관의 장과 지방자치단체의 장은 제도를 신설·변경할 때 대통령령에 따라 보건복지부장관과 협의하여야 한다(합의 아님, 기획예산처장관 아님)":"제도를 새로 만들거나 바꿀 때는 보건복지부장관과 협의해야 하며 합의나 기획예산처장관은 요건이 아닙니다.","중장기 사회보장 재정추계는 보건복지부장관이 적어도 3년마다 실시하고 공표":"보건복지부장관이 적어도 3년마다 중장기 재정추계를 실시하고 공표합니다.","중증요양상태는 업무상 부상·질병으로 노동능력이 상실·감소된 상태로서 치유되지 아니한 상태":"업무상 부상이나 질병으로 노동능력이 줄었고 아직 치유되지 않은 상태입니다.","중지는 시장·군수·구청장은 의료급여가 필요 없게 된 경우 또는 수급권자가 의료급여를 거부한 경우 의료급여를 중지하여야 한다, 거부한 경우에는 가구원 전부에 대해 중지":"의료급여가 필요 없게 되거나 수급권자가 거부하면 중지해야 하고 거부한 경우 가구원 전부에 대해 중지합니다.","지급 대상 사망자는 ① 노령연금 수급권자 ② 가입기간 10년 이상인 가입자 또는 가입자였던 자 ③ 연금보험료를 낸 기간이 가입대상기간의 3분의 1 이상인 가입자 또는 가입자였던 자 ④ 사망일 5년 전부터 사망일까지 3년 이상 납부한 가입자 또는 가입자였던 자(체납 3년 이상 제외) ⑤ 장애등급 2급 이상인 장애연금 수급권자":"유족연금이 나오는 사망자는 노령연금 수급권자와 10년 이상 가입자와 3분의 1 이상 납부자 등입니다.","지급되는 금전·현물과 긴급지원수급계좌의 긴급지원금은 압류할 수 없고 생계유지 목적 외로 양도·담보 제공할 수 없다":"현금과 현물과 지원금 계좌의 돈은 압류가 막혀 있고 생계 외 목적으로는 넘기거나 담보로 쓸 수 없습니다.","지급 연기는 60세 이상 65세 미만 수급권자가 65세 전까지 연금의 전부 또는 일부 지급을 연기할 수 있다, 연기 1개월마다 1천분의 6 가산, 일부 연기는 1천분의 500~900 다섯 단계":"60세 이상 65세 미만은 연금 지급을 미룰 수 있고 1개월마다 1천분의 6씩 늘어나며 일부 연기는 다섯 단계입니다.","지급은 신청한 날이 속하는 달부터 수급권을 상실한 날이 속하는 달까지 매월 정기적으로 지급, 지급 정지 기간에는 지급하지 않음":"신청한 달부터 상실한 달까지 매월 정기적으로 지급하고 지급 정지 기간에는 주지 않습니다.","지급일은 대통령령에 따라 실업의 인정을 받은 일수분을 지급":"구직급여는 대통령령에 따라 실업의 인정을 받은 일수만큼 지급합니다.","지급 정지(사유 발생일이 속하는 달의 다음 달부터 소멸일이 속하는 달까지)는 ① 금고 이상의 형을 선고받고 교정시설 또는 치료감호시설에 수용 ② 행방불명·실종 등으로 사망한 것으로 추정 ③ 국외 체류기간이 60일 이상 지속(60일이 되는 날 사유 발생) ④ 그 밖에 이에 준하는 대통령령 사유":"교정시설 수용과 행방불명 등 사망 추정과 국외 체류 60일 이상일 때는 사유 발생 다음 달부터 소멸한 달까지 지급을 정지합니다.","지급 정지는 배우자는 수급권 발생 후 3년 동안 지급하고 55세가 될 때까지 정지(장애상태 / 25세 미만 자녀 생계 유지 / 소득 있는 업무 미종사 시 정지 안 함), 소재를 1년 이상 알 수 없는 경우 정지":"배우자는 수급권 발생 후 3년간 받고 55세가 될 때까지 정지되나 장애나 어린 자녀 생계 유지 등이면 정지하지 않습니다.","지급 정지는 정당한 사유 없이 서류 제출 요구·진단 요구에 응하지 않거나 신고를 하지 않은 때 등 급여의 전부 또는 일부 지급 정지 가능":"서류 제출이나 진단 요구에 응하지 않거나 신고를 하지 않으면 급여의 전부나 일부를 정지할 수 있습니다.","지급 제외는 공무원연금·군인연금·사학연금·별정우체국연금의 퇴직연금 등 수급권자와 그 배우자(대통령령으로 정하는 사람 포함) 및 직역재직기간 10년 이상인 연계퇴직연금 수급자":"공무원연금 등 직역연금 퇴직연금 수급권자와 그 배우자 및 직역재직기간 10년 이상 연계퇴직연금 수급자는 지급에서 제외됩니다.","지방의회의 의결로 제정한다(지방의회가 제정하고 지방자치단체의 장은 규칙 제정권)":"조례는 지방의회가 의결해서 만들고 지방자치단체의 장은 규칙을 만드는 권한을 가집니다.","지방자치단체가 법령의 범위에서 그 사무에 관하여 제정한다":"조례는 지방자치단체가 법령의 범위 안에서 자기 사무에 관해 만드는 규범입니다.","지방자치단체는 조례로 정하는 바에 따라 이 법의 급여 범위·수준을 초과하여 급여를 실시할 수 있다":"지방자치단체는 조례로 이 법의 급여 범위와 수준을 넘어서는 급여를 실시할 수 있습니다.","지방자치단체의 장이 법령 또는 조례의 범위에서 그 권한에 속하는 사무에 관하여 제정":"규칙은 단체장이 법령이나 조례의 범위 안에서 자기 권한에 속한 사무에 관해 정합니다.","지방장애인복지위원회는 지방자치단체에 두고 사업의 기획·조사·실시 사항을 심의":"지방자치단체에 두는 위원회로 장애인 복지 사업의 기획과 조사와 실시 사항을 심의합니다.","지속가능한 사회보장제도를 확립하고 매년 필요한 재원을 조달하여야 한다":"제도가 오래 유지되도록 하고 필요한 재원을 해마다 마련해야 하는 책임입니다.","지역가입자는 직장가입자와 그 피부양자를 제외한 가입자":"지역가입자는 직장가입자와 그 피부양자를 뺀 나머지 가입자입니다.","지역노인보호전문기관은 시·도에 둔다(시·군·구 아님), 신고전화 운영 및 사례접수 / 현장조사 / 피해노인·학대자 상담 / 법률 지원 요청 / 기록 보관 / 일반인 예방교육 / 재발방지 교육 / 지역노인학대사례판정위원회 운영":"지역기관은 시·도에 두며 시·군·구가 아니고 신고전화 운영과 현장조사와 상담과 예방교육을 합니다.","지역봉사지도원은 국가 또는 지방자치단체가 사회적 신망과 경험이 있는 노인으로 지역봉사를 희망하는 사람을 위촉할 수 있다":"국가나 지방자치단체가 신망과 경험이 있는 노인 중 지역봉사를 희망하는 사람을 위촉할 수 있습니다.","지역사회를 기반으로 일정한 시설과 전문인력을 갖추고 주민의 참여와 협력으로 지역사회의 복지문제를 예방·해결하기 위해 종합적인 복지서비스를 제공하는 시설":"사회복지관은 전문인력과 시설을 갖추고 주민의 참여로 지역 복지문제를 예방하고 해결하는 종합 서비스 시설입니다.","지역자활센터협회를 설립할 수 있다":"센터 사이의 협력을 위한 협회라는 연합 조직을 만들 수 있게 열어 둔 규정입니다.","지역적·기능적으로 균형 잡힌 사회보장 전달체계를 구축하고, 조직·인력·예산을 갖추며, 공공과 민간 전달체계를 연계하도록 노력":"전달체계는 지역과 기능 면에서 균형 있게 짜고 조직과 인력과 예산을 갖추며 공공과 민간을 연계하도록 노력해야 합니다.","지원기관은 이 법에 따른 지원을 행하는 국가나 지방자치단체, 한부모가족복지단체는 복지 증진을 목적으로 설립된 기관이나 단체":"이 법에서 지원기관은 공공 쪽 주체이고 복지단체는 복지 증진 목적으로 만든 민간 쪽 주체입니다.","지원 내용은 다문화 이해교육 / 생활정보 제공 및 한국어교육 / 평등한 가족관계 유지 / 가정폭력 피해자 보호·지원 / 의료 및 건강관리(산전·산후 도우미 건강검진) / 아동·청소년 보육·교육 / 다국어 서비스":"다문화 이해교육과 생활정보 제공과 한국어교육과 폭력 피해자 보호와 의료 및 건강관리 등이 지원 내용입니다.","지원대상아동은 조화롭고 건강한 성장에 필요한 기초 조건이 갖추어지지 않아 사회적·경제적·정서적 지원이 필요한 아동":"성장에 필요한 기초 조건이 부족해 사회적·경제적·정서적 지원이 필요한 아동입니다.","지원대상자에게 의견을 진술할 기회를 제공하고 조사 방해·기피 또는 자료 제출 요구를 두 번 이상 거부하면 신청을 각하할 수 있다":"조사 때 의견을 말할 기회를 주고, 조사를 방해하거나 자료 요구를 두 번 이상 거부하면 신청을 각하할 수 있습니다.","지원대상자와 그 친족, 민법에 따른 후견인, 청소년기본법에 따른 청소년상담사·청소년지도사, 지원대상자를 사실상 보호하고 있는 자(관련 기관·단체의 장 포함) 등이 지원대상자의 주소지 관할 보장기관에 신청 (사회복지시설의 장은 사실상 보호하는 자에 해당할 수 있는 신청권자이나 직권 신청 주체는 보장기관의 업무담당자)":"지원대상자 본인과 친족과 후견인과 청소년상담사와 사실상 보호자 등이 주소지 보장기관에 신청할 수 있습니다.","지원대상자 조사는 시장·군수·구청장이 매년 1회 이상 관할구역 지원대상자의 가족상황·생활실태 조사":"시장·군수·구청장이 매년 1회 이상 관할 지원대상자의 가족 상황과 생활 실태를 조사합니다.","지원 요청 시 또는 위기상황 확인 시 긴급지원대상자와 가구구성원이 금융·신용·보험 정보 제공 동의 서면을 제출(의식불명 등은 지원 후 제출)":"지원 요청이나 위기 확인 때 대상자와 가구구성원이 정보 제공 동의서를 내지만 의식불명 등은 지원 뒤에 냅니다.","지원요청·신고를 받으면 지체 없이 긴급지원담당공무원이 거주지 등을 방문해 위기상황 확인":"요청이나 신고를 받으면 긴급지원담당공무원이 곧바로 거주지 등을 찾아가 위기상황을 확인합니다.","지원요청은 긴급지원대상자와 친족 그 밖의 관계인이 구술 또는 서면으로 요청, 누구든지 대상자를 발견하면 신고하여야 한다":"본인과 친족과 관계인이 말이나 글로 요청할 수 있고 누구든지 대상자를 발견하면 신고해야 합니다.","지원을 받는 자원봉사단체와 센터는 그 명의로 특정 정당이나 특정인의 선거운동을 하여서는 아니 된다":"지원받는 단체와 센터는 이름으로 특정 정당이나 후보의 선거운동을 해서는 안 됩니다.","지정 기부는 기부자는 배분지역·배분대상자·사용 용도를 지정할 수 있고 모금회는 지정 취지에 따라 사용하여야 한다":"기부자는 배분지역과 대상자와 용도를 지정할 수 있고 모금회는 그 취지대로 써야 합니다.","지정 취소 또는 6개월 범위 업무정지는 거짓 부정 지정(필요적 취소) / 급여외행위 제공 / 지정기준 부적합 / 급여 거부 / 본인부담금 면제·감경 / 수급자 소개·알선 / 1년 이상 무신고 휴업 / 거짓 급여비용 청구 / 종사자의 수급자 폭행·성희롱·방임·금품 유용·정서적 학대 / 업무정지 중 급여 제공(필요적 취소) 등":"거짓으로 지정받은 경우는 반드시 취소하고 급여외행위나 급여 거부 등은 취소하거나 6개월 범위에서 업무를 정지시킵니다.","지정취소 후 3년이 지나지 않거나 업무정지 중인 자는 장기요양기관으로 지정받을 수 없다":"지정이 취소된 지 3년이 안 되었거나 업무정지 중인 사람은 다시 지정을 받을 수 없습니다.","지회는 시·도 단위 사회복지공동모금지회를 둔다, 지회장은 이사회 의결을 거쳐 회장이 임명, 지회 조성 재원은 해당 시·도 배분대상자에게 배분이 원칙, 회계연도 시작 2개월 전 지회로부터 사업계획서를 받아 보건복지부장관에게 보고":"시·도 단위로 지회를 두고 지회장은 이사회 의결을 거쳐 회장이 임명하며 지회 재원은 그 시·도 대상자에게 배분하는 것이 원칙입니다.","직무상 비밀 누설은 5년 이하 징역 또는 5천만원 이하 벌금":"직무상 알게 된 비밀을 누설하면 5년 이하의 징역이나 5천만원 이하의 벌금에 처합니다.","직무상 신고 노력 의무자 10종 + 보건복지부령 지정자는 의료기관 종사자 / 유아교육법·초중등교육법·고등교육법에 따른 교원·직원·산학겸임교사·강사 / 사회복지시설 종사자 / 국가공무원·지방공무원 / 장애인활동지원기관의 장 및 종사자와 활동지원인력 / 학원 운영자·강사·직원 및 교습소 교습자·직원 / 건강가정지원센터·가족센터의 장과 종사자 / 청소년시설·청소년단체의 장과 종사자 / 청소년 보호·재활센터의 장과 종사자 / 평생교육기관의 장과 종사자 / 그 밖에 보건복지부령으로 정하는 자 (국가무형유산 보유자는 해당하지 않음)":"직무상 신고 노력 의무자에는 의료기관 종사자와 교원과 사회복지시설 종사자와 공무원 등이 들어갑니다.","직무상 중대한 위기에 처한 지원대상자를 발견한 신고의무자는 지체 없이 알리고 신속히 지원받도록 노력":"직무 중에 매우 위급한 지원대상자를 알게 된 신고의무자는 바로 알리고 신속한 지원이 되게 해야 합니다.","직업능력개발 수당은 직업안정기관의 장이 지시한 직업능력개발 훈련 등을 받는 기간에 지급":"지시받은 직업능력개발 훈련을 받는 기간에 주는 수당입니다.","직업안정기관의 장에게 인정 신청, 마지막 이직 사업을 기준으로 인정 여부 결정":"수급자격은 직업안정기관의 장에게 신청해 인정받고 마지막 이직 사업을 기준으로 인정 여부를 결정합니다.","직업재활급여는 장해급여자 중 훈련대상자의 직업훈련 비용 및 직업훈련수당 / 업무상 재해 발생 당시 사업에 복귀한 장해급여자에 대해 사업주가 고용 유지·직장적응훈련·재활운동을 실시할 때 지급하는 직장복귀지원금·직장적응훈련비·재활운동비":"직업재활급여는 장해급여자의 훈련 비용과 수당을 주고 복귀한 장해급여자에게는 사업주에게 고용 유지 지원 등을 합니다.","직업훈련비와 훈련기간 중 생계비는 추가 지급 가능":"직업훈련비와 훈련 기간 중 생계비는 추가로 지급할 수 있습니다.","직장가입자는 모든 사업장의 근로자 및 사용자와 공무원 및 교직원":"직장가입자의 범위는 사업장에서 일하는 근로자와 사용자에 더해 공무원과 교직원까지 걸칩니다.","직장가입자 보수월액보험료는 직장가입자와 사업주(공무원은 국가·지방자치단체 / 교직원은 사용자)가 각 100분의 50씩 부담, 사립학교 교원은 본인 50 사용자 30 국가 20, 보수 외 소득월액보험료는 직장가입자 부담, 지역가입자는 세대 전원이 연대 부담":"보수월액보험료는 직장가입자와 사업주가 각각 100분의 50씩 내고 사립학교 교원은 본인 50과 사용자 30과 국가 20으로 나눕니다.","직장가입자 보험료율은 1천분의 80의 범위에서 심의위원회 의결로 대통령령이 정한다, 국외 업무 종사 직장가입자는 그 보험료율의 100분의 50":"직장가입자 보험료율은 1천분의 80 범위에서 정하고 국외 업무 종사자는 그 100분의 50만 냅니다.","직장가입자 월별 보험료는 보수월액보험료(보수월액 x 보험료율) + 보수 외 소득월액보험료, 지역가입자는 세대 단위로 소득(소득월액 x 보험료율) + 재산(재산보험료부과점수 x 점수당 금액)":"직장가입자는 보수월액에 보험료율을 곱한 금액에 소득월액분을 더하고 지역가입자는 세대 단위로 소득분과 재산분을 합칩니다.","직전 계약기간 만료연도 5월 31일까지 계약 체결, 불발 시 보건복지부장관이 6월 30일까지 심의위원회 의결로 결정":"계약은 만료 연도 5월 31일까지 맺고 안 되면 장관이 6월 30일까지 심의위원회 의결로 정합니다.","직접지원 6가지는 생계지원(식료품비·의복비 등) / 의료지원(각종 검사 및 치료) / 주거지원(임시거소 제공 또는 비용) / 사회복지시설 이용 지원 / 교육지원(초·중·고등학생의 수업료 입학금 학교운영지원비 학용품비) / 그 밖의 지원(연료비 등)":"직접지원은 생계와 의료와 주거와 시설 이용과 교육과 그 밖의 지원 여섯 가지입니다.","진단은 공단은 장애에 따른 수급권자나 부양가족연금 계산 대상자에게 지정 의사의 진단을 요구하거나 소속 직원으로 장애 상태를 확인하게 할 수 있다":"수급권자의 장애 상태가 맞는지 공단이 지정 의사 진단을 요구하거나 직원으로 하여금 직접 보게 할 수 있습니다.","진료심사평가위원회는 심사평가원에 두며 위원장 포함 상근 90명 이내 비상근 1천명 이내":"심사평가원 안에 둔 진료심사평가위원회는 상근 90명과 비상근 1천명 이내의 큰 조직입니다.","진찰·검사 / 약제·치료재료의 지급 / 처치·수술과 그 밖의 치료 / 예방·재활 / 입원 / 간호 / 이송과 그 밖의 의료목적 달성을 위한 조치 (장제조치는 포함되지 않음)":"의료급여의 내용은 진찰, 약제, 치료, 예방, 입원, 간호, 이송 등이며 장제조치는 포함되지 않습니다.","진폐는 분진을 흡입하여 폐에 생기는 섬유증식성 변화를 주된 증상으로 하는 질병":"진폐는 분진을 들이마셔 폐에 섬유증식성 변화가 생기는 질병입니다.","진폐에 따른 보험급여는 요양급여 / 간병급여 / 장례비 / 직업재활급여 / 진폐보상연금 / 진폐유족연금":"진폐에 따른 급여는 요양과 간병과 장례비와 직업재활급여에 더해 진폐보상연금과 진폐유족연금이 있습니다.","질병·부상의 예방·진단·치료·재활과 출산·사망 및 건강증진에 대해 보험급여를 실시해 국민보건 향상과 사회보장 증진에 이바지":"국민건강보험법은 질병 예방과 치료와 출산과 사망에 보험급여를 해 국민보건을 높이고 사회보장을 증진하려는 법입니다.","집중모금을 하려면 그 모집일부터 15일 전에 그 내용을 보건복지부장관에게 보고하여야 한다":"집중모금은 모집일 15일 전에 보건복지부장관에게 그 내용을 보고해야 합니다.","징수권 소멸은 지역가입자 등의 보험료를 징수할 권리는 가입자 사망 / 노령연금 또는 반환일시금 수령 / 소멸시효 완성 때 소멸":"지역가입자 등의 보험료를 거둘 권리는 가입자가 사망하거나 연금을 받거나 시효가 지나면 사라집니다.","징수 기간은 자격 취득일이 속하는 달의 다음 달부터 자격 상실일의 전날이 속하는 달까지(매월 1일 취득이면 그 달부터)":"보험료는 자격을 얻은 달의 다음 달부터 상실일 전날이 속한 달까지 걷고 매월 1일에 취득하면 그 달부터 걷습니다.","차상위자 급여는 보장기관이 가구별 생활여건을 고려해 예산 범위에서 주거·의료·교육·장제·자활급여(생계급여 제외 해산급여 제외)의 전부 또는 일부를 실시할 수 있다":"차상위자에게는 예산 범위에서 주거·의료·교육·장제·자활급여를 줄 수 있으나 생계급여와 해산급여는 제외입니다.","처분을 고지받은 날부터 30일 이내에 시장·군수·구청장을 거쳐 시·도지사에게 서면":"이의신청은 처분을 고지받은 날부터 30일 이내에 단체장을 거쳐 시·도지사에게 서면으로 합니다.","처분을 받은 날부터 90일 이내에 처분을 결정한 보장기관의 장에게 할 수 있다":"이의신청의 기한은 처분을 받은 날 기준으로 90일이며 신청 상대는 처분한 보장기관의 장입니다.","청소년 한부모는 24세 이하의 모 또는 부 (18세·25세 이하라는 선지는 오답)":"청소년 한부모는 24세 이하의 모 또는 부이며 18세나 25세 이하가 아닙니다.","청소년 한부모 학업 지원은 학적 유지 / 교육비 / 검정고시 / 평생교육시설 교육비 지원 등, 성평등가족부장관이 청소년 한부모가 학업을 계속할 수 있도록 교육부장관에게 협조를 요청하여야 한다 (교육부장관이 요청하는 것이 아님)":"청소년 한부모의 학적 유지와 교육비와 검정고시와 평생교육 지원으로 학업을 이어 가게 합니다.","초과 비용은 해당 지방자치단체가 부담":"법에서 정한 수준을 넘는 비용은 그 급여를 하는 지방자치단체가 부담합니다.","최고 보상기준 금액은 상용근로자 5명 이상 사업체 전체 근로자 임금 평균액의 1.8배, 최저 보상기준 금액은 2분의 1(최저임금액 미만이면 최저임금액), 휴업급여·상병보상연금에는 최저 보상기준 금액을 적용하지 않는다":"최고 보상기준은 전체 근로자 평균임금의 1.8배이고 최저 보상기준은 그 2분의 1이며 최저임금액 미만이면 최저임금액입니다.","최상위 법규범은 헌법이고 그 다음이 법률":"법규범의 맨 위는 헌법이고 법률이 그 아래에서 뒤를 잇습니다.","최저보장수준은 국민의 소득·지출 수준과 가구 유형 등 생활실태 물가상승률 등을 고려해 제6조에 따라 급여 종류별로 공표하는 금액이나 보장수준":"최저보장수준은 소득과 지출과 가구 유형과 물가 등을 고려해 급여 종류별로 공표하는 금액이나 수준입니다.","최저보장수준은 생계급여와 소득인정액을 포함해 선정기준 이상이 되도록 한다":"생계급여를 받아도 소득인정액과 합친 총액이 선정기준 이상이 되도록 최저보장수준을 맞춥니다.","최저생계비는 건강하고 문화적인 생활 유지에 필요한 최소한의 비용으로 보건복지부장관이 계측하는 금액":"생활에 꼭 필요한 최소 금액으로 장관이 계측해 정하는 기준 금액입니다.","추가 산입 기간의 기준소득월액은 연금보험료를 내지 않은 사용자 공제 기간(2분의 1 산입) 및 군 복무 크레딧은 2분의 1 / 출산 크레딧은 균등부분 금액":"추가 산입되는 기간의 소득은 사용자 공제 기간과 군 복무 크레딧은 2분의 1, 출산 크레딧은 균등부분 금액으로 봅니다.","추후 납부(추납)는 10년 미만의 범위에서 납부 예외 기간 등에 상응하는 보험료를 추후 납부 신청 가능":"납부 예외로 비어 있는 기간에 맞는 보험료를 10년 미만의 범위에서 나중에 내어 가입기간을 채울 수 있습니다.","출산·양육·실업·노령·장애·질병·빈곤·사망 등 사회적 위험으로부터 모든 국민을 보호하고 삶의 질을 향상시키는 데 필요한 소득·서비스를 보장하는 사회보험·공공부조·사회서비스":"사회보장은 사회적 위험으로부터 국민을 보호하기 위한 사회보험과 공공부조와 사회서비스를 아우릅니다.","출산전후휴가 급여 등은 출산전후휴가·유산사산휴가·배우자 출산휴가·난임치료휴가·배우자 유산사산휴가를 받은 피보험자 중 휴가 종료일 이전 피보험 단위기간 합산 180일 이상인 경우 지급":"출산전후휴가와 배우자 출산휴가 등을 받은 피보험자 중 180일 이상의 피보험 단위기간이 있으면 급여를 줍니다.","출산 크레딧은 자녀 2명 이하는 자녀 1명마다 12개월을 가산, 3명 이상은 첫째·둘째 24개월에 2자녀를 초과하는 자녀 1명마다 18개월을 더한다, 부모가 모두 가입자이면 합의로 1명에게 산입하고 합의가 없으면 균등 배분, 재원은 국가가 전부 또는 일부 부담 (2026 기출 정답 문장은 둘째부터 12개월 적용)":"출산 크레딧은 자녀 2명 이하는 1명마다 12개월, 3명 이상은 첫째·둘째 24개월에 초과 1명마다 18개월을 더합니다.","출석임원 전원이 날인하고 2매 이상이면 간인":"회의록에는 참석한 임원 모두의 도장이 필요하고 장이 여러 매이면 간인으로 이어 붙입니다.","출퇴근 경로 일탈·중단 시 그 중 사고와 후 이동 중 사고는 출퇴근 재해가 아니다(일상생활에 필요한 행위로 대통령령 사유가 있으면 출퇴근 재해)":"경로를 벗어나거나 중단한 중간과 이후의 사고는 출퇴근 재해가 아니지만 일상생활에 필요한 행위로 사유가 있으면 예외입니다.","출퇴근은 취업과 관련하여 주거와 취업장소 사이의 이동 또는 한 취업장소에서 다른 취업장소로의 이동":"산재법의 출퇴근은 취업과 관련해 집과 일터 사이 또는 한 일터에서 다른 일터로 이동하는 것입니다.","출퇴근 재해는 사업주가 제공한 교통수단 등 사업주의 지배관리하에서 출퇴근하는 중 사고 / 그 밖에 통상적인 경로와 방법으로 출퇴근하는 중 사고(비통상적인 경로와 방법으로 출퇴근 중 발생한 사고는 업무상 사고가 아님)":"사업주가 제공한 교통수단으로 가거나 통상적인 경로와 방법으로 출퇴근하다 입은 사고가 출퇴근 재해입니다.","취소된 사람은 취소된 날부터 15일 내에 자격증을 반납하고 취소된 날부터 2년 이내에는 재교부를 받지 못한다":"취소된 사람은 15일 안에 자격증을 반납해야 하고 2년 이내에는 재교부를 받지 못합니다.","취업촉진 수당 4가지는 조기재취업 수당 / 직업능력개발 수당 / 광역 구직활동비 / 이주비 (구직급여는 취업촉진 수당이 아님)":"취업촉진 수당은 조기재취업 수당과 직업능력개발 수당과 광역 구직활동비와 이주비이고 구직급여는 여기에 속하지 않습니다.","치료보호는 의료기관은 요청이 있으면 상담·치료 등을 실시하여야 하고 비용은 가정폭력행위자가 부담한다, 피해자가 신청하면 국가·지방자치단체가 대신 지급 후 구상":"의료기관은 요청이 있으면 상담·치료를 해야 하고 비용은 행위자가 부담하며 피해자가 신청하면 공공이 대신 내고 구상합니다.","치유는 부상 또는 질병이 완치되거나 치료 효과를 더 이상 기대할 수 없고 증상이 고정된 상태":"치유는 완치되었거나 치료 효과를 더는 기대할 수 없고 증상이 고정된 상태를 뜻합니다.","통합재가서비스는 장기요양기관은 방문요양·방문목욕·방문간호·주야간보호·단기보호 전부 또는 일부를 통합해 제공할 수 있다":"장기요양기관은 방문요양 등 여러 재가급여를 한꺼번에 묶어서 통합해 제공할 수 있습니다.","퇴소조치는 보호조치 중 아동이 18세에 달하였거나 보호 목적이 달성되었다고 인정되면 보호조치를 종료하거나 퇴소시켜야 한다":"보호 중 18세에 이르거나 목적이 달성되었다고 인정되면 보호조치를 종료하거나 퇴소시켜야 합니다.","퇴직연금등수급권자는 제외(연계 신청 시 예외)":"직역연금 퇴직연금 수급권자는 사업장가입자에서 제외되지만 연계를 신청하면 예외입니다.","특례요양비는 장기요양기관이 아닌 노인요양시설 등에서 재가·시설급여에 상당한 급여를 받은 경우 비용의 일부 지급 / 요양병원간병비는 수급자가 요양병원에 입원한 때 장기요양 비용의 일부 지급":"특례요양비는 장기요양기관이 아닌 시설에서 급여에 상당한 서비스를 받은 경우 비용 일부를, 간병비는 요양병원 입원 시 지급합니다.","특별자치시 계획은 시·군·구 계획 사항 + 기반 구축 + 인력 양성 방안":"특별자치시는 시·군·구 계획 항목에 기반 구축과 인력 양성까지 더해 한 번에 수립합니다.","특별한 관계에 있는 사람은 이사 현원의 5분의 1을 초과할 수 없다":"특별 관계인이 이사진에서 지나치게 많아지지 않도록 비율을 이사 현원의 5분의 1 이하로 묶습니다.","특별현금급여 3가지는 가족요양비 / 특례요양비 / 요양병원간병비":"현금으로 지급하는 급여가 따로 있어 가족요양비와 특례요양비와 간병비의 세 가지로 이루어집니다.","평가결과에 따라 가산 또는 감액 조정":"평가 결과가 좋으면 가산하고 나쁘면 감액해서 급여비용을 조정할 수 있습니다.","포기하는 것이 다른 사람에게 피해를 주거나 사회보장 관계 법령에 위반되면 포기할 수 없다":"포기가 다른 사람에게 피해를 주거나 법령을 어기는 경우라면 포기할 수 없습니다.","포함 사항은 건강보험정책의 기본목표 및 추진방향 / 보장성 강화 추진계획 / 중장기 재정 전망 및 운영 / 보험료 부과체계 / 요양급여비용 / 건강증진 사업 / 취약계층 지원 / 통계 및 정보 관리 / 그 밖에 대통령령이 정하는 사항":"종합계획에는 기본목표와 보장성 강화와 재정 전망과 보험료 부과체계와 요양급여비용과 취약계층 지원 등이 들어갑니다.","프로그램규정설(입법 방침) / 추상적 권리설(법률이 있어야 구체화) / 구체적 권리설":"사회적 기본권의 법적 성격을 입법 방침으로 보는 설, 법률이 있어야 구체화된다는 설, 바로 권리라는 설 세 가지입니다.","피보험 단위기간은 피보험기간 중 보수 지급의 기초가 된 날을 합하여 계산":"자격 요건의 일수를 셀 때 보수가 지급된 날만 하루씩 합산해 따진다는 계산 방식입니다.","피보험자격 취득일은 근로자는 이 법이 적용되는 사업에 고용된 날, 상실일은 이직한 날의 다음 날 / 사망한 날의 다음 날 / 적용 제외 근로자가 된 날 / 보험관계 소멸일":"근로자는 적용 사업에 고용된 날 자격을 얻고 이직한 날의 다음 날이나 사망한 날의 다음 날 등에 자격을 잃습니다.","피보험자는 고용산재보험료징수법에 따라 보험에 가입되었거나 가입된 것으로 보는 근로자 예술인 노무제공자 / 고용보험에 가입한 자영업자":"고용보험의 피보험자는 보험에 가입되었거나 가입된 것으로 보는 근로자와 예술인과 노무제공자와 가입 자영업자입니다.","피부양자는 직장가입자에게 주로 생계를 의존하는 사람으로 소득·재산이 보건복지부령 기준 이하인 ① 배우자 ② 직계존속(배우자의 직계존속 포함) ③ 직계비속(배우자의 직계비속 포함)과 그 배우자 ④ 형제·자매":"피부양자는 직장가입자에게 주로 생계를 의존하고 소득과 재산이 기준 이하인 배우자와 직계존속과 직계비속 등입니다.","피성년후견인 / 금고 이상 실형 선고 후 집행이 끝나거나 면제되지 않은 사람 / 금고 이상 집행유예 기간 중인 사람 / 법원 판결로 자격이 상실·정지된 사람 / 마약·대마·향정신성의약품 중독자 / 정신질환자(전문의가 적합하다고 인정하는 사람은 제외)":"결격사유에는 피성년후견인과 실형 집행이 끝나지 않은 사람과 집행유예 중인 사람과 약물 중독자 등이 있습니다.","피한정후견인은 이 목록에 없다":"결격사유 목록에는 피한정후견인이 들어 있지 않습니다.","피해자가 동반한 아동 취학 지원은 주소지 외의 지역에서 취학할 필요가 있을 때 원활한 취학을 지원하여야 한다":"피해자와 함께 온 아동이 주소지 밖 학교를 다녀야 할 때 취학을 원활하게 지원해야 합니다.","피해자는 가정폭력으로 인하여 직접적으로 피해를 입은 자, 아동은 18세 미만":"피해자는 가정폭력으로 직접 피해를 입은 사람이고 이 법의 아동은 18세 미만입니다.","피해자 의사 존중은 상담소나 보호시설의 장은 피해자 등의 명시한 의사에 반하여 보호를 할 수 없다":"상담소나 보호시설은 피해자가 분명히 밝힌 뜻과 달리 보호를 할 수 없습니다.","피해장애인 쉼터는 시·도지사(특별시장·광역시장·특별자치시장·도지사·특별자치도지사)가 설치·운영할 수 있다(보건복지부장관 아님)":"피해장애인 쉼터는 시·도지사가 설치·운영할 수 있으며 보건복지부장관이 하지 않습니다.","필요로 하는 모든 국민에게 적용 / 급여 수준과 비용 부담에서 형평성 유지 / 정책 결정·시행 과정에 공익의 대표자·이해관계인 참여로 민주적 결정 / 연계성과 전문성 제고":"운영원칙은 필요한 모든 국민에게 적용하고 형평성을 유지하며 민주적으로 결정하고 연계성과 전문성을 높이는 것입니다.","필요적 취소 사유는 ① 거짓이나 그 밖의 부정한 방법으로 자격 취득 ② 결격사유에 해당하게 됨 ③ 자격증 대여·양도 또는 위조·변조":"반드시 취소하는 사유는 부정하게 자격을 취득한 경우와 결격사유에 해당하게 된 경우와 자격증 대여·양도·위조입니다.","필요한 사람은 누구든지 자신의 의사에 따라 신청할 수 있고 보장기관은 안내·상담 등을 충분히 제공 / 누락 방지를 위해 지원대상자를 적극 발굴 / 공정·투명·적정 제공 / 민간 법인·단체·시설의 복지혜택과 연계 / 편리한 이용 / 지역의 사회보장 수준이 균등하게 실현되도록 노력":"신청은 본인 뜻에 따라 누구나 할 수 있고 보장기관은 충분히 안내하며 누락 없이 발굴하고 공정하게 제공해야 합니다.","학대피해노인 전용쉼터는 국가와 지방자치단체가 설치·운영할 수 있고 노인보호전문기관에 운영을 위탁할 수 있다":"국가와 지방자치단체가 쉼터를 설치·운영할 수 있고 운영은 노인보호전문기관에 맡길 수 있습니다.","학대피해아동쉼터는 시·도지사 및 시장·군수·구청장이 설치·운영할 수 있다, 피해아동 보호·숙식 제공 / 심리상담·치료 / 학습·정서 지원":"시·도지사와 시장·군수·구청장이 설치·운영할 수 있고 피해아동에게 숙식과 심리상담과 학습 지원을 합니다.","한국자원봉사협의회는 자원봉사단체가 설립하며 법인, 정관을 작성해 행정안전부장관의 인가를 받아 등기":"협의회는 자원봉사단체가 설립한 법인으로 정관을 만들어 행정안전부장관의 인가를 받아 등기합니다.","한부모가족의 권리는 모 또는 부는 임신·출산·양육을 이유로 합리적 이유 없이 교육·고용 등에서 차별받지 않는다, 한부모가족의 모 또는 부와 아동은 한부모가족 관련 정책결정과정에 참여할 권리가 있다, 자산과 노동능력을 최대한 활용해 자립하도록 노력":"모 또는 부는 임신·출산·양육을 이유로 합리적 이유 없이 교육·고용에서 차별받지 않을 권리가 있습니다.","한부모가족의 날은 5월 10일 (9월 7일은 사회복지의 날)":"5월 10일이 한부모가족의 날이라는 점과 9월 7일 사회복지의 날과 구별하는 비교입니다.","한부모가족이 안정적인 가족 기능을 유지하고 자립할 수 있도록 지원해 생활 안정과 복지 증진에 이바지":"한부모가족지원법은 한부모가족이 가족 기능을 유지하고 자립하도록 지원해 생활 안정과 복지를 높이려는 법입니다.","합병은 시·도지사의 허가, 주된 사무소가 서로 다른 시·도에 있으면 보건복지부장관의 허가":"합병은 원칙적으로 시·도지사가 허가하지만 시·도가 서로 다르면 장관이 허가권자입니다.","합병증 등 예방관리는 치유된 사람 중 재요양 사유 발생 우려자에게 예방에 필요한 조치를 받도록 할 수 있다":"치유된 뒤에도 재요양이 필요할 우려가 있는 사람에게는 예방 조치를 받게 할 수 있습니다.","해산급여는 생계·주거·의료급여 중 하나 이상을 받는 수급자에게 조산 및 분만 전후 필요한 조치와 보호를 실시":"해산급여는 생계·주거·의료급여 수급자에게 출산 전후의 필요한 조치와 보호를 하는 급여입니다.","해산한 법인의 남은 재산은 정관으로 정하는 바에 따라 국가 또는 지방자치단체에 귀속된다(유사 목적 다른 법인 귀속 아님)":"해산한 법인의 남은 재산은 정관에 따라 국가나 지방자치단체에 귀속되고 유사한 다른 법인에 귀속되지 않습니다.","해임명령을 받은 법인은 2개월 이내에 이사회를 소집하여야 한다":"해임명령을 받으면 법인은 두 달 안에 이사회를 열어 후속 조치를 취해야 합니다.","허가 후 주된 사무소 소재지에서 설립등기":"허가를 받은 뒤에는 주된 사무소가 있는 곳에서 설립등기를 합니다.","헌법 / 법률 / 명령(대통령령·총리령·부령 = 시행령·시행규칙) / 조례 / 규칙 / 조약과 일반적으로 승인된 국제법규":"성문법원은 문서로 만들어져 공포된 법으로, 헌법에서 조약과 국제법규까지 여섯 갈래가 있습니다.","헌법에 의하여 체결·공포된 조약과 일반적으로 승인된 국제법규는 국내법과 같은 효력을 가진다, 외국인의 지위는 국제법과 조약이 정하는 바에 의하여 보장":"헌법에 따라 체결·공포된 조약과 승인된 국제법규는 국내법과 같은 효력을 가지며 외국인의 지위도 국제법과 조약이 보장합니다.","헌법에 의해 체결·공포된 조약과 일반적으로 승인된 국제법규는 국내법과 같은 효력을 가진다(법원에 포함)":"헌법 절차에 따라 맺은 조약과 승인된 국제법규는 국내법과 같은 효력이 있어 법원이 됩니다.","협의가 이루어지지 않으면 사회보장위원회에 조정을 신청할 수 있다":"부처 간 합의가 안 될 때는 사회보장위원회가 조정하도록 신청하는 절차가 있습니다.","협의회는 중앙(한국사회복지협의회)·시·도·시·군·구 3단계이고 사회복지법인으로 한다":"사회복지협의회는 중앙과 시·도와 시·군·구 세 단계로 이루어지고 사회복지법인으로 합니다.","협회는 사회복지사의 전문지식·기술 개발·보급 / 교육훈련 / 복지증진을 위해 설립한 법인":"한국사회복지사협회는 사회복지사의 전문지식과 기술 개발, 교육훈련, 복지증진을 위해 설립한 법인입니다.","혼인 관계에 있지 아니한 출산 전 임신부와 출산 후 아동을 양육하지 아니하는 모는 출산지원시설을 이용할 때 지원대상자가 된다":"미혼 임신부와 출산 후 아동을 기르지 않는 모는 출산지원시설을 이용할 때 지원대상자가 됩니다.","홀로 사는 노인은 방문요양·돌봄 서비스와 안전확인 등 보호조치를 취하여야 한다, 독거노인종합지원센터는 보건복지부장관이 설치·운영할 수 있다(노인복지시설 종류가 아님)":"홀로 사는 노인에게는 방문요양과 돌봄과 안전확인을 하고 독거노인종합지원센터는 노인복지시설의 종류가 아닙니다.","확인되면 지체 없이 지원의 종류·내용을 결정해 지원":"위기가 확인되면 바로 지원의 종류와 내용을 정해 지원합니다.","환수는 거짓 부정한 방법으로 받은 경우(이자 가산) / 지급 정지 기간에 지급된 경우 / 잘못 지급된 경우 환수하여야 한다":"거짓으로 받았거나 정지 기간에 받았거나 잘못 지급된 연금은 반드시 환수하며 거짓의 경우 이자를 더합니다.","활동지원급여는 국가와 지방자치단체가 일상·사회생활을 위해 지원할 수 있다":"공공이 장애인의 일상과 사회생활을 위해 활동지원급여를 줄 수 있다는 규정입니다.","회의록은 공개(대통령령 사항은 이사회 의결로 비공개 가능)":"회의록은 공개하는 것이 원칙이고 대통령령 사항은 이사회 의결로 비공개할 수 있습니다.","훈련 거부 등에 따른 지급 제한은 직업안정기관이 소개한 직업의 취직 거부 또는 지시한 직업능력개발 훈련 거부 시 구직급여 지급 정지, 정지 기간은 1개월 범위":"직업 소개나 훈련 지시를 거부하면 구직급여를 정지하며 정지 기간은 1개월 범위입니다.","휴업급여는 요양으로 취업하지 못한 기간에 1일당 평균임금의 100분의 70, 취업하지 못한 기간이 3일 이내이면 지급하지 않는다":"일하지 못한 날의 소득을 메우려고 평균임금의 100분의 70을 주지만 3일 이내이면 주지 않습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
